window.POETRY_REGISTER("v4-poems-595.js",{"records":[["罢钓归来晚，前溪水正深。\n临桥不敢渡，谁识此翁心。",""],["茅堂枕江涯，种竹只九个。\n时有清风来，还同故人坐。",""],["石染湘江泪，真涵太极情。\n百年双老眼，相对两无声。",""],["江上春潮静，舟中日似年。\n不须生羽翼，无事即神仙。",""],["东寺复西寺，朝游还暮游。\n百年尘迹里，同醉几中秋。",""],["寒月出关山，秋窗白如曙。\n空流云中影，不照云中戍。",""],["朝看长白山，暮看长白山。\n山色有朝暮，吾心常自闲。","朝看长白山，暮看长白山。\n山色有朝暮，吾心常自閒。"],["清川映白石，游鱼止复行。\n共有临渊羡，能无结网情。",""],["月落古堤上，人行春陌头。\n晓烟如有意，长伴绿杨楼。",""],["初日照园桃，盈盈散霞绮。\n主人窗中坐，颜色宛相似。",""],["共道农家事，辛勤在一春。\n静观田野际，多少辍耕人。",""],["近浦寒烟上，平沙落雁遥。\n行人欲归去，舟子故招招。",""],["寒泉冽古井，上有双梧桐。\n借问往来者，谁知疏凿功。",""],["城外望城中，朝来气逾爽。\n吾心浩然者，入夜还能长。",""],["闻道南湖曲，芙蓉似锦张。\n如何一夜雨，空见水茫茫。",""],["水殿穿湖入，风阑过雨凭。\n微微夕阳外，时见出林僧。",""],["盈盈绿水际，泛泛白鹅群。\n借问乘舟客，何如王右军。","盈盈绿水际，汎汎白鹅群。\n借问乘舟客，何如王右军。"],["碧树围青殿，朱垣接绀堤。\n王孙罕游豫，驰路草萋萋。",""],["风恬湖水平，画舸月中行。\n不见渔父处，但闻渔笛声。",""],["泛泛白鸥鸟，悠悠长自随。\n忆君何处切，湖上月明时。","汎汎白鸥鸟，悠悠长自随。\n忆君何处切，湖上月明时。"],["深浅元无定，行舠识水频。\n急流天下险，最好是平津。",""],["袅袅暮风细，团团秋月明。\n沙河闻不远，起我故山情。",""],["赤日乱青霞，照我湖中艑。\n来船时借问，前途水深浅。",""],["睡起看云坐，玄心入杳冥。\n吾将访蓬岛，双棹莫教停。",""],["落日照行盖，凉风吹不休。\n未消临水兴，还倚对山楼。",""],["白日隐寒树，层阴万里生。\n归人望烟火，岁晏返柴荆。",""],["黄金满归橐，白日行亦惧。\n道左遗爱碑，贼来将不去。",""],["乳燕巢古堤，流莺度层阁。\n试看白马郎，金丸向谁落。",""],["东山雷殷殷，南涧雨冥冥。\n爱尔衡门下，团团松盖青。",""],["行人争渡急，江黑雨鸣船。\n戢戢中林鸟，归飞薄暮前。",""],["下马古寺门，偶与山僧遇。\n相对两不言，蝉声在高树。",""],["园果垂丹实，园丁日夜看。\n未曾供寝庙，不敢献中官。",""],["杨柳三春暮，沙场万里馀。\n紫骝何日返，空有寄来书。",""],["鸦啼古城上，月落古城𬮱。\n城外车马道，清风飘素尘。","鸦啼古城上，月落古城闉。\n城外车马道，清风飘素尘。"],["沙苑平如掌，青青苜蓿痕。\n昔时放马地，今作牧牛村。",""],["朝从田父饭，憩马古林西。\n村鸡不知曙，日高犹自啼。",""],["蜿蜿野田中，白鹭静如扫。\n停鞭问征客，云是居庸道。",""],["枯杨临大堤，上有鸲鹆窠。\n春风几日至，会使绿阴多。",""],["山中风日暖，蔼蔼似初春。\n乱石牛羊径，时逢扫叶人。",""],["月出东陵峰，照见西陵树。\n何事同心子，山中不相遇。",""],["袅袅叶含雨，菲菲香近人。\n如何向阳蕊，开花向阳春。",""],["秀色红翻坐，浓阴绿绕阶。\n觑花还拄杖，冲雨不怜鞋。",""],["借问雨中好，何如晴后看。\n锦江红湿处，应记独凭阑。",""],["室静客稀赏，地偏花更清。\n自开还自落，宛似野人情。",""],["斜日清源北，浮云岱岳东。\n故山归路好，不得与君同。",""],["逆旅逢秋感倍深，美人何处坐鸣琴。\n南宫只隔西河水，一夜相思万里心。",""],["此身飘泊苦西东，未就丹砂愧葛洪。\n多病所须惟药物，知君才是济川功。",""],["卿到朝廷说老翁，秋来相顾尚飘蓬。\n钓竿欲拂珊瑚树，未掣鲸鱼碧海中。",""],["长开箧笥拟心神，巾拂香馀捣药尘。\n词翰升堂为君扫，已知仙客意相亲。",""],["断肠分手各风烟，肺病几时朝日边。\n同辇随君侍君侧，自称臣是酒中仙。",""],["柴门空闭锁松筠，燕子衔泥两度新。\n不是尚书期不顾，故园犹得见残春。",""],["未有涓埃荅圣朝，便应华发老渔樵。\n东流江水西飞燕，人事音书漫寂寥。",""],["偶然同渡不同舟，风到扬帆共逆流。\n莫谓狂澜无砥柱，嵩行千古镇中州。",""],["南幸三吴北幸幽，乾坤开辟两神州。\n文儒自守高皇训，武将谁分圣主忧。",""],["石头城如银虎盘，金陵山似玉龙蟠。\n休讶六军停跸久，本来江左是长安。",""],["羽盖霓旌晓出游，绀霞红日映江流。\n云中帝子三千阙，海上仙人十二楼。",""],["扬子江头驻六师，太平天子赏功时。\n红云影乱黄龙舰，白日光摇绣虎旗。",""],["江口传呼大驾临，顺流风雨注江心。\n风起半山群虎啸，雨来深水一龙吟。",""],["大君仁圣迥非常，远似唐宗近宋皇。\n访道先过赵普宅，哀贤还吊魏徵丧。",""],["潮落江门烟水秋，云帆八月过扬州。\n两京驰道三千里，夹岸垂杨接御沟。",""],["翩翩龙马控雕戈，白日清秋沛上过。\n圣主守边思猛士，临风高咏大风歌。",""],["叠鼓凝笳入禁中，似闻韶乐奏南风。\n通明殿敞秋云碧，阊阖楼开晓日红。",""],["雪殿云墀列羽旄，天王开宴赏勋劳。\n封侯未赐将军印，归马先分战士袍。",""],["日射江流生紫氛，喧喧铙吹隔江闻。\n江头巨石高千尺，好勒元戎破贼勋。",""],["帐前银甲映朱旄，帐外牙旗卷日高。\n白书红尘飞一骑，尚方新赐玉麟袍。","帐前银甲映朱旄，帐外牙旗捲日高。\n白书红尘飞一骑，尚方新赐玉麟袍。"],["虎豹鲸鱼一夜擒，湖南湖北动欢心。\n论功宜并衡山峻，比德还同汉水深。",""],["秋水沈沈漾列星，盘涡殷殷斗雷霆。\n扁舟昨夜巴陵过，风起犹闻战血腥。",""],["凤仪兽舞尽来王，犬豕何知悖且狂。\n高垒固巢今不见，麻洋滩下水汤汤。",""],["御沟东畔古松盘，曾得先皇倚笑看。\n龙驭不归鸾吹杳，石廊圆殿镇秋寒。",""],["六军歌舞健长征，五色云随九仞旌。\n传语单于休近塞，太平天子驻天城。",""],["万岁声欢四海闻，大同新策破戎勋。\n汉文可是勤边主，按辔闲过细柳营。","万岁声欢四海闻，大同新策破戎勋。\n汉文可是勤边主，按辔閒过细柳营。"],["天山戎马本天骄，入贡能轻道路遥。\n底事内兵翻作乱，祸胎疑自武宗朝。",""],["一自甘州杀宪臣，国家纲纪似秋尘。\n各边声势元相倚，缓急谁为死力人。",""],["代郡城中十万家，膏粱珠翠甚繁华。\n兵残火烈须臾事，女哭男啼亦可嗟。",""],["宣府云中五日程，朱门王子白衣行。\n回头却向西山哭，玉眷金昆知死生。",""],["诸将邀勋各逞能，边军反侧寝还兴。\n抚哺休夸桂元帅，绥来还有蔡中丞。","诸将邀勋各逞能，边军反侧寝还兴。\n抚哺休誇桂元帅，绥来还有蔡中丞。"],["紫荆西望白云山，腹里云中指顾间。\n好降丝纶促诸将，急操兵马备三关。",""],["城中金鼓昼逄逄，城上高悬首级双。\n二十四家同日死，自今休更说招降。",""],["白日城门四不开，就中情状颇难猜。\n乘时早定安边计，只恐春深牧马来。",""],["佳丽曾矜得宠先，后宫歌舞一当千。\n那知宠极能生妒，不是青娥误少年。",""],["前山云接后山烟，可道公归是偶然。\n霖雨出山知有日，入山亲纪甲申年。",""],["北窗闲卧读南华，出处吾生信有涯。\n五色晓云天子宅，一篱秋菊野人家。","北窗閒卧读南华，出处吾生信有涯。\n五色晓云天子宅，一篱秋菊野人家。"],["黑发勋名镜里看，紫宸章疏早辞官。\n闲心自爱商山曲，懒听人歌蜀道难。","黑发勋名镜里看，紫宸章疏早辞官。\n閒心自爱商山曲，懒听人歌蜀道难。"],["落落朝廷醉眼中，苦缘忧国愿年丰。\n老臣心事如工部，只有升沈迹未同。",""],["留公无计奈公何，外国中朝属望多。\n此日同为太行赋，几时重和庆云歌。",""],["华发王门晚拜官，齐竽声里独成叹。\n何人为荐长沙傅，一见文皇献治安。",""],["十日春无一日晴，客堂沽酒莫辞倾。\n纸窗风信梨花雨，恼乱归心是此声。",""],["撚断吟须字未安，短歌聊尔代长叹。\n春风座上无边景，漫道儒官是冷官。",""],["春归花落鸟无声，一夜闲愁带雨倾。\n自古浮云本无定，漫将消息问阴晴。","春归花落鸟无声，一夜閒愁带雨倾。\n自古浮云本无定，漫将消息问阴晴。"],["院台深处绿阴屯，松下棋枰竹下尊。\n苦忆去年欢赏地，碧天如水月当门。",""],["宦接乡山事已稀，谪居犹得近王畿。\n劝君今夜且雄饮，明日出城风叶飞。",""],["华发青袍不染尘，宦程回复主恩新。\n县人争说中都宰，曾向云霄忤贵人。",""],["斜日照雨明霜台，红花白花相映开。\n野老爱花情太剧，不须招致也能来。",""],["葵花半红山雨来，不辞沾湿看花开。\n主人莫扫花前径，恐破青阴与绿苔。",""],["一尊花底思悠然，落日空庭席屡前。\n酒熟共欢游此地，花开谁与坐明年。",""],["王升店前秋草生，秦皇台畔暮蝉鸣。\n海翁欲访无人识，何处孤舟短笛横。",""],["菊花元自菊泉分，见菊真如即对君。\n安得对君还见菊，短篱斜日坐秋薰。",""],["丈菊亭亭入座新，白花辉映白纶巾。\n生来自有凌云志，可是孤高不近人。",""],["一枝分取到山家，月映疏篱水映花。\n欲把赠梅诗赠菊，暗香浮动影横斜。",""],["月闰逢秋菊早芳，盛开还喜近重阳。\n休怜阒寂朝临水，且看孤清晚耐霜。",""],["月下山车往复回，秋深歧路满青苔。\n不缘乡饮邀宾坐，肯向城池故故来。",""],["暮春庭馆见花稀，黄鸟嘤嘤燕子飞。\n堂北假山苔藓蚀，祇应偏待主人归。",""],["雨过茅屋秋草生，霜凄榆塞候禽鸣。\n闲来倚杖柴门外，童子骑牛短笛横。","雨过茅屋秋草生，霜凄榆塞候禽鸣。\n閒来倚杖柴门外，童子骑牛短笛横。"],["十年离思一宵同，坐歇寒钟意不穷。\n碧草未舒湖石畔，黄花争艳竹篱中。",""],["图史春行满客囊，此中偏载晚篱香。\n临歧欲采寒花赠，似隔盈盈水一方。",""],["贾生只合住长沙，三载江陵却寄家。\n云静碧天秋日午，讲堂吟对木樨花。",""],["春日黉宫花正开，宫前宫后锦成堆。\n如今南郡多桃李，尽是黄公种得来。",""],["隐君家住白云间，不爱功名只爱闲。\n闻说花园新更好，门前流水屋中山。","隐君家住白云间，不爱功名只爱閒。\n闻说花园新更好，门前流水屋中山。"],["卧牛山前春草肥，华阳宫外雨霏霏。\n主人侵晓踏青去，日暮家童扶醉归。",""],["梦里神交几见亲，画中还比梦时真。\n岁寒心事东风面，人与梅花一样春。",""],["故乡风景梦依然，鱼浦窗西兔岭颠。\n谁道不归归未得，芙蕖窗下抱愁眠。",""],["赤日帘栊如火然，野夫怀秋病欲颠。\n安得海风吹霹雳，九渊呼起蛰龙眠。",""],["荒凉棋社隔秋春，世事年来著著新。\n眼底相逢论成败，谁知当局苦心人。",""],["髹几文楸光照云，僧堂长与对斜曛。\n翻愁置我南窗下，一度临棋一忆君。",""],["杏子成林竹护墙，傍河云物昼苍苍。\n园中似是林家屋，过客时闻药草香。",""],["凶年老稚多奇病，吉水仙人有妙方。\n不用相逢问名字，满城人说是医王。",""],["芍药开时三月过，京华五月见犹多。\n云栽露种元相异，雨骤风狂奈尔何。",""],["长安日日走尘沙，春尽多时不见花。\n蒲州公子能相送，醉倒东山处士家。",""],["白马香风度落花，绛桃秾李避妍华。\n长安陌上归来晚，笑指龙楼是外家。",""],["艾家河边蒲叶长，扁舟昨日过端阳。\n荆南客路千馀里，回首铜台亦故乡。",""],["燕市分携十七春，白门相见白头新。\n凤凰楼畔含香侣，江海飘零有几人。",""],["玉藕根移玉井高，感君分赠谢君劳。\n书生见惯秋江色，且向名园问碧桃。",""],["睡起看图气未降，丹青谁有笔如杠。\n欲烦画我茅亭下，静数飞帆涉大江。",""],["两家儿女对船窗，学语真同乳燕双。\n日午梦回成一莞，不知身世在清江。",""],["远携尊酒惠山来，梦草情牵对月杯。\n云际忍听双雁别，水边愁见一帆开。",""],["京国论交记往年，城南风景梦依然。\n春江未卜看花地，秋水空歌伐木篇。",""],["宋台梁馆暮霜馀，野色苍茫拥使车。\n马首不随南去雁，袖中元有北征书。",""],["岸苇萧萧河水寒，骄嘶骢马鞴银鞍。\n燕山代谷飞腾过，送别无歌行路难。",""],["行部能教阴雨晴，渡河还遣浊流清。\n愿磨中岳山头石，记取西江御史名。",""],["漫怀家庆感晨昏，国士须凭国士论。\n闻道阿翁将阿母，花间长日醉清樽。",""],["谏草书残驿舍灯，翠华冲雪恐难胜。\n回轺莫向春明路，见说君王在白登。",""],["羽盖飘飖白日临，回光应烛小臣心。\n愿同汲黯留中闼，更拟相如赋上林。",""],["每逢朝客转惊神，北望长安几侧身。\n紫禁烟花夹城柳，别来今已十番春。",""],["闪闪龙旗树五更，煌煌芝火照层城。\n当年奉引趋蹡地，曾听钧天广乐声。",""],["三载风尘一见难，每将书札报平安。\n梁园幸是同官地，春月春花却自看。",""],["蜀玺离离金错光，远随骢马过秦梁。\n奉持敢作寻常看，一道清风五月霜。",""],["梁王台前春草生，梁王台上鸟嘤嘤。\n美人遥在黄金屋，客子登临空复情。",""],["鸟语深宫白日斜，彩毫浓墨散春霞。\n王孙不学雕虫技，只写忠花与孝花。",""],["瑶室青编万卷馀，宫中谁道日闲居。\n家臣昨夜长安去，犹问君王乞秘书。","瑶室青编万卷馀，宫中谁道日閒居。\n家臣昨夜长安去，犹问君王乞秘书。"],["汉江明月照归人，万里秋风一叶身。\n休把客衣轻浣濯，此中犹有帝京尘。",""],["客来君寄一双鱼，客去还君一纸书。\n欲买扁舟向东下，洞庭春浪近何如。",""],["江上逢君感昔年，往来相见陆陵前。\n那知宦迹如萍梗，犹得相依一水边。",""],["同朝同寺十年情，迢递燕山隔楚城。\n一别天涯今万里，欲从何处望春明。",""],["跃马横戈老尚堪，时时游猎过龙潭。\n遥知此日非熊兆，不在周南在汉南。",""],["鹤发虬须八十龄，白头长对岘山青。\n朝来虎帐看云坐，闲课诸孙读武经。","鹤发虬须八十龄，白头长对岘山青。\n朝来虎帐看云坐，閒课诸孙读武经。"],["眉际生毫似发长，采苓时到白云乡。\n闲来莫向桃源去，恐有渔人识阮郎。","眉际生毫似发长，采苓时到白云乡。\n閒来莫向桃源去，恐有渔人识阮郎。"],["文园消息近如何，酒盏生疏药裹多。\n却向故山忆旧隐，膏肓从古在烟萝。",""],["长镵秋圃自锄荒，望入高山路渺茫。\n不信爱莲亭子上，有人白日到羲皇。",""],["尘满纱帷旧业荒，江都云水暮苍茫。\n清时不用天人策，方朔诙谐侍武皇。",""],["自入秋来日日晴，看花看月每同行。\n一夜六街风雨恶，莫言天不解离情。",""],["早凉冲晓入纱帷，听雨听风睡起迟。\n街西咫尺不相见，却似河梁别后时。",""],["济水源南舜井旁，月明曾共坐宵长。\n六春暌隔离江路，五月相逢是帝乡。",""],["双雁北来河水平，两岸秋阴芦荻生。\n黑头七度曾过此，不似今回感别情。",""],["淮浦泱泱淮水流，月明长照浦中楼。\n白鹤青猿好相访，主人今只在滁州。",""],["清淮蒲荻晚萧萧，浦口山明欲上潮。\n七里正贪渔艇乐，九重无耐鹤书招。",""],["水蓼花红淮浦烟，晚来鸥鹭下翩翩。\n依沙宿桨当门系，莫是扬家问字船。",""],["郁郁青松尺许长，似看颜色有风霜。\n何时却睹干霄势，六月浓阴覆草堂。",""],["月明风静雨初收，一鹗横空万里秋。\n四海苍生正翘首，秀峰岩下莫迟留。",""],["翩翩骢马度秋涯，思入风云句意佳。\n多病独怜梁苑客，闭门高卧草侵阶。",""],["诗来恰值酒醒馀，起步秋庭病忽除。\n唤妇不须愁夜黑，老夫今日得明珠。",""],["病里怀人掩客窗，尚闻仙舸在龙江。\n观音阁下梅花水，对雨何时倒玉缸。",""],["屋里琴书屋外田，绕庭松树古藤缠。\n何时却遂东山约，闲伴先生乐暮年。","屋里琴书屋外田，绕庭松树古藤缠。\n何时却遂东山约，閒伴先生乐暮年。"],["绿阴回首代红英，客舍流光只可惊。\n病起偶宽书簿债，独将尊酒向谁倾。",""],["博得荆南五裤歌，一钱囊底奈贫何。\n匣中犹有龙泉在，闲就巴江石上磨。","博得荆南五裤歌，一钱囊底奈贫何。\n匣中犹有龙泉在，閒就巴江石上磨。"],["一麾江郡领尘官，何似山中菽水欢。\n梁楚板舆平似砥，凭君休说路行难。",""],["黄鹤楼前夜泊舟，苇花枫叶似江州。\n乐天本是多情客，卧听歌声起别愁。",""],["逆旅相逢意惘然，四年䰟梦一灯前。\n即教乍见还分手，犹胜山阴雪夜船。",""],["薄暮霜篱景色加，名园分得岁寒花。\n谁知建业骚人馆，不是浔阳处士家。",""],["䢴江西路溯流风，城郭山林道路通。\n兄弟自为真率会，秪应随俭复随丰。",""],["腰袅燕台白玉珂，水亭山寺赏吟多。\n相看已恨俱华发，更奈苍江远别何。",""],["登临随处见题名，想像当年载酒行。\n山翠不遮牛首寺，江流长抱石头城。",""],["竹门潇洒对江开，中有高亭扁快哉。\n为问亭中二仙客，几时骑鹤上蓬莱。",""],["扬舲无奈客心何，暑雨平添潞水波。\n草阁驿亭谈笑别，碧山回首暮云多。",""],["短棹长江下蜀州，家中风景画中收。\n蒲牙出水荷钱小，一笑相看两白头。",""],["碧衣黄简照青春，宠宴传呼出尚珍。\n辞罢阁门东上马，道傍罗列拜王臣。",""],["楼船风景入春多，铙吹声中故里过。\n两岸绿杨阴不断，隔江知是柳州河。",""],["手捧鸾书下九天，恩光初到墓门前。\n山川不改孤儿恨，风木萧萧似往年。",""],["十年知己一绨袍，万里南云望尔劳。\n待得明年好春日，牡丹花里候旌旄。",""],["虎头将军图画奇，成都待诏功名迟。\n春风草草拂衣去，投老相寻知几时。",""],["冥鸿杳杳碧天秋，虞人网罗空复求。\n朔地苦寒江渚燠，常时虚拟稻粱谋。",""],["青门挂冠春欲暮，白首放歌江上归。\n野老相逢话朝市，龙飞天子正垂衣。",""],["老子田园归兴豪，已将功业付儿曹。\n庭中手种梧桐树，他日朝阳看凤毛。",""],["莲叶田田溪日曛，竹竿袅袅白鸥群。\n水南即是长洲苑，杳霭歌声穿暮云。",""],["东观鸡号风雨冥，十年通籍绾银青。\n栖栖不向故山去，兀兀穷愁何以醒。",""],["秦州石经半埋土，藓剥苔封谁为开。\n凭君觅取吴中本，江上云帆日往来。",""],["露冕南征火井西，东过漉水北泥溪。\n借问乡愁何处切，千山明月子规啼。",""],["五马骄嘶锦水隈，双旌遥指剑门开。\n巴童吹笛羌儿舞，重见文翁镇蜀来。",""],["五月泸州蕉叶黄，武侯祠下水如汤。\n行人莫恶南中热，自有参天古柏长。",""],["古箐人稀秋草深，碧松苍桧接阴森。\n高楼永日弹棋暇，海北天南万里心。",""],["汉家驿路止牂牁，相望龙湖路几何。\n闻说夜郎天更远，浔阳李白亦经过。",""],["石栈凌云鸟路赊，汉中城府枕三巴。\n风林落叶猿声满，那得行人不忆家。",""],["白马河边春日晴，黄牛山下百花明。\n家家耒耜居民出，太守来时亲课耕。",""],["金城户曹张凤翔，埋玉空山宿草长。\n天上故人驱五马，经过流涕问孤孀。",""],["天涯相见地曹郎，郡阁清尊夜语长。\n休向灯前易成别，江头春水正茫茫。",""],["曾并长安逐马蹄，谪居同过楚云西。\n他年纵有看花句，休向玄都观里题。",""],["去岁秋风别省闱，木樨花落雨霏霏。\n那知此日江陵郡，春草连天送客归。",""],["春风江阁喜同游，苦恨逢君不少留。\n东去巴陵三日路，几时同上岳阳楼。",""],["知君元在识君先，水国相逢亦偶然。\n何日一尊还远别，暮云春树暗江天。",""],["冉冉游云覆短檐，霏霏寒霭度重帘。\n羁怀正苦逢春别，行李何妨入夜淹。",""],["送君泺源溪水滨，岸桃堤柳俱鲜新。\n黄鹂声中白日晚，又是乡园一度春。",""],["林花欲开春草生，村烟漠漠午鸡鸣。\n君行落魄似阮籍，休叹路歧纵复横。",""],["腊月驱车东郡来，元宵今始雪中回。\n临清城外成林杏，尽是州人为尔栽。",""],["鸡声喔喔宵近庭，出户忽闻春雨腥。\n西江高士别我去，日出烟消山更青。",""],["行李萧条石径荒，贾生东去路茫茫。\n卢龙不是长沙地，莫把吾皇比汉皇。",""],["卑耳溪边秋草深，裂坡山北树阴阴。\n西风匹马吊孤竹，一曲商歌千古心。",""],["汴上相逢一载馀，五云回首送轺车。\n河梁别意真堪画，行李萧萧几卷书。",""],["霜云千里朔风寒，豸锦貂裘独据鞍。\n大厦如今要梁栋，凭君归报得材难。",""],["夜来风雨晓来晴，万里无尘海岳清。\n白日共看骢马色，青天不负使君名。",""],["漫谈时事共伤神，白首丹心许国身。\n归觐正逢长至节，六阴行且见阳春。",""],["荣亲报国皆吾事，孝子忠臣只此心。\n闻说致身同养志，莫分朝市与山林。",""],["客窗风雨对寒灯，午夜怀人思不胜。\n梁苑宋台秋色里，也应回首忆同登。",""],["别来公署易黄昏，心曲凭谁与细论。\n宦海风波无定处，相逢何日对芳樽。",""],["梦回欹枕夜三更，烟树微茫隔卫城。\n独向屋梁惊落月，不堪还听雁来声。",""],["宦情时事剧秋云，话到伤心不忍闻。\n别梦迢迢似明月，汉关楚塞远随君。",""],["半生湖海识君迟，可奈相逢是别期。\n扁舟独泛秋溪水，采得芙蓉欲赠谁。",""],["六月戎船上逆流，书生弹铗取封侯。\n夜来羽檄江边过，闻说西戎破剑州。",""],["巫峡瞿塘十丈波，大宁盐井火云多。\n贼巢散满空山里，旧日居民有几何。",""],["万山深护一书楼，此际栖迟景最幽。\n浮海未酬当日志，北归还买洞庭舟。",""],["薰风江上棣花开，醉倚兰桡首重回。\n孤影却随南雁去，尺书还附北鸿来。",""],["水耨方闲即火耕，土风遥识楚江程。\n汀花冉冉凫鹥色，岸柳阴阴布谷声。","水耨方閒即火耕，土风遥识楚江程。\n汀花冉冉凫鹥色，岸柳阴阴布谷声。"],["鬓丝端为别兄皤，魂梦真如道路何。\n滇海万峰秋雁少，楚江千里月明多。",""],["远从江左入湖南，姜被初分思岂堪。\n闲算长公年纪数，白头今已六旬三。","远从江左入湖南，姜被初分思岂堪。\n閒算长公年纪数，白头今已六旬三。"],["望远时从郭外游，好登江阁与山楼。\n烟开碧树通吴苑，日落黄云接楚丘。",""],["苏公楼前海日晴，伏波祠畔瘴烟清。\n荔枝垂实桄榔暗，太守来时双鹤迎。",""],["诗人出守是寻常，万古心期一瓣香。\n若道雷州非乐土，请君时到十贤堂。",""],["海邦云雾昼霏霏，榕树林中孔雀飞。\n驿骑忽传天使到，九重亲赐玉环归。",""],["我在江陵望帝乡，登楼时恨楚天长。\n怜君更隔三千里，岭树湖烟更渺茫。",""],["黄梅绿竹两寥寥，一段清光惜浪抛。\n看遍乾坤空老眼，几人解取岁寒交。",""],["海棠盈盈开素秋，雨晴斜日上帘钩。\n幽芳不与春风约，碧榭朱阑俱暮愁。",""],["海棠开日近重阳，秋蝶翩翩过短墙。\n题品要知观物眼，只须风骨不须香。",""],["海棠花开秋雨霏，休将迟暮怨芳菲。\n东园桃李盈千树，昨日秾华今日稀。",""],["庭下秋棠开紫绵，映风含雨净娟娟。\n羽人自解丹丘术，种得花来亦是仙。",""],["梧桐叶凋金井阑，芭蕉风雨怨秋残。\n海棠十月犹含蕊，故伴青松当岁寒。",""],["节过重阳菊已残，倚霜欹露不胜寒。\n山堂正少黄金蕊，试看君家白玉团。",""],["雪白狸奴尾胜金，曾娱白发戏花阴。\n急须分乞邻姬养，莫遣空摧孝子心。",""],["带叶生英颗颗新，竹蓝初发齿生津。\n清酸本是儒家味，不道山僧亦戏人。",""],["梅花枝上报初春，泺水源头忆故人。\n天宇自清心自白，不知何处有红尘。",""],["江树青山歇晚秋，草堂幽僻对寒流。\n故人远赴关西去，明月芦花系钓舟。",""],["鲈鱼钓得上纶钩，归去应须与妇谋。\n携取一尊同客醉，江风山月更何忧。",""],["白石冈头榆柳新，苍苍茅屋掩深春。\n山翁不注扬云易，怪底门无问字人。",""],["岁寒池馆暮相依，雪共心期月共辉。\n南北宦游三十载，碧山回首故人稀。",""],["绿惨红蔫春色阑，枝间黄鸟任绵蛮。\n知机自合高飞去，莫遣矰罗绊羽翰。",""],["我来赠君玉兔图，我去留君双湛卢。\n月殿秋风桂花发，一枝能斫寄来无。",""],["水榭山林向夕幽，笛声遥在木兰舟。\n江空处处多明月，不用相寻秉烛游。",""],["绕膝曾玄认不真，北堂风景日长春。\n堂前满种宜男草，一度花开一度新。",""],["万里乾坤见此亭，四围山色绕阑青。\n何当著我亭中坐，闲校神农本草经。","万里乾坤见此亭，四围山色绕阑青。\n何当著我亭中坐，閒校神农本草经。"],["玄菟城外草连天，鸭绿江头春可怜。\n将军饮马临江水，东指扶桑在日边。",""],["小结幽亭倚大江，万竿深处听飞泷。\n横琴试鼓湘妃怨，彷佛鸣珂过北窗。",""],["苕水羌山清更深，萧萧芦渚间桑林。\n青枫树里三间屋，十载常悬万里心。",""],["万竹深深一径斜，草堂门巷接江沙。\n主人游宦不归去，时有白鸥来钓槎。",""],["华发当年倚笑看，北堂春色映朱阑。\n披图彷佛慈颜在，零落霜风夜雨寒。",""],["云暗霜天雪满衣，鴐鹅声乱海青飞。\n李陵台下燕山北，正是单于夜打围。",""],["蓉溪主人溪上来，来时廉访去都台。\n共道溪花似溪主，暂时摇落又还开。",""],["溪水溪花相映鲜，溪风时拂案头弦。\n轻鸥白鹭知人意，双去双来精舍边。",""],["锦江东会蜀江流，卜筑还依江上洲。\n十里锦云千顷碧，此中风物最宜秋。",""],["秋溪明月夜经过，两岸芙蓉照绿波。\n溪上主人元好静，巴童休唱下渝歌。",""],["月落江空万里秋，一声长篴古槎头。\n渔郎此意何人解，水底蛟龙水上鸥。",""],["江草芊绵江雨霏，王孙孤艇泛潮归。\n寂寂江亭摇落处，碧云回首雁行稀。",""],["十亩山田一舍幽，草窗闲卧白云秋。\n行人若问墨溪主，不是当年柳柳州。","十亩山田一舍幽，草窗閒卧白云秋。\n行人若问墨溪主，不是当年柳柳州。"],["明时不作大夫官，偃盖空山老岁寒。\n试问玄都旧桃树，几回花实几凋残。",""],["溟蒙湖水抱村斜，湖上扁舟载晚霞。\n怪得看图意渺渺，图中风景似侬家。","溟濛湖水抱村斜，湖上扁舟载晚霞。\n怪得看图意渺渺，图中风景似侬家。"],["百战功高旧破戎，侯门却似布衣穷。\n傲霜枝叶凌云干，画里分明国士风。",""],["风蕊纷披霜叶清，画图秋色笑渊明。\n持杯只爱东篱赏，未识金门大隐情。",""],["御寇曾摅报主心，野云孤鹤伴闲吟。\n时人若欲知名姓，须向凌烟阁上寻。","禦寇曾摅报主心，野云孤鹤伴閒吟。\n时人若欲知名姓，须向凌烟阁上寻。"],["西府频看策旧勋，北山常恐负移文。\n如何九五飞龙日，闲得无心出岫云。","西府频看策旧勋，北山常恐负移文。\n如何九五飞龙日，閒得无心出岫云。"],["卧龙山下结茅新，乞得匡时未老身。\n此日此庵真独幸，天涯多少未归人。",""],["十五年前别帝州，早看风节动儒流。\n渠阳此日新开府，不数先朝定远侯。",""],["袅雾流云水阁寒，浴凫飞鹭满江干。\n风潮莫向愁中听，雪竹还留醉里看。",""],["曲径回廊接圃深，竹窗松户晚阴阴。\n幽花不阻三春梦，明月长悬万里心。",""],["蜀吴舟楫槛前经，万里乡心杳不扃。\n莫问兴亡异时事，满川斜日下空庭。",""],["朱旗绣斧两昭回，南郡城池亦壮哉。\n明月楼中堪坐啸，关山何处有尘埃。",""],["睥睨连云十二楼，西南形胜数荆州。\n已教岘首为屏绕，更遣巴江作带流。",""],["江日曈曈散晓鸦，湖田漠漠隐桑麻。\n中丞本是阳春脚，散得东风与万家。",""],["城廓周回十里通，遥从城上见城中。\n不知多少王孙第，万户楼台一半红。",""],["古堰迢迢枕郭门，城南城北万家村。\n行人共指丰年兆，雪里青青见麦痕。",""],["大北门西掷甲山，山头古庙草斑斑。\n中丞驻马看遗像，认得将军旧姓关。",""],["百雉城头小队行，下闻闾里动欢声。\n防边不在多戎马，只有人心是甲兵。",""],["泺水桥西一亩宫，小窗春度碧荷风。\n老夫野性无拘束，便欲移家向此中。",""],["门巷沈沈草径纡，绿槐深护野人居。\n鸟声不断日亭午，时有小童来捕鱼。",""],["树绕园亭水漫池，西溪风物最宜诗。\n即教痛饮成深醉，莫遣空悬别后思。",""],["靡靡菰蒲傍水涯，粼粼白石映青鞋。\n今年欲此消长夏，合扁君堂作我斋。",""],["白云渺渺水悠悠，两岸芦花覆钓舟。\n年少自知官绂在，寻常不敢问沧洲。",""],["云水地临三宪节，江湖天放一渔舟。\n虚烦倚树看黄帽，耐可乘槎漾碧流。",""],["漾漾莲舟系古槎，沈沈波影照乌纱。\n多情最喜台中客，乘兴能看水际花。",""],["水岸风回晚更凉，菰蒲零乱拂衣裳。\n扁舟莫到花深处，恐碍波心片月光。",""],["万竹阴阴暑气微，主人迎客敞山扉。\n翻愁使节传呼近，惊起舟前白鹭飞。",""],["层阿回眺独行行，日落春山烟雾生。\n山下荒城隐丛薄，路人云是古昌平。",""],["山径春深满绿苔，景陵东去转萦回。\n忽逢樵父惊相问，言自黄花镇里来。",""],["牧马场边苜蓿香，回龙宫外树苍苍。\n当年骏骨今何处，曾被金鞍侍武皇。",""],["汲水浇花柳贯鱼，草堂巢燕暮春馀。\n要知开径诛茅意，不为浓阴好读书。",""],["御沟东畔柳成林，御水盈盈十里阴。\n白马青衫桥上客，春来多少故园心。",""],["琴台书榭绿阴深，杖履时时隔水寻。\n闲过永明湖上看，几家桃李自成阴。","琴台书榭绿阴深，杖履时时隔水寻。\n閒过永明湖上看，几家桃李自成阴。"],["塘烟漠漠水迢迢，摇荡春风几万条。\n不傍御园歌舞地，只愁宫女妒纤腰。",""],["回马岭前春日西，涧花岩树郁萋萋。\n上方钟落不知处，惟见白云岩畔栖。",""],["长城在秦那在齐，齐山古寺春草萋。\n千载哭夫能变俗，至今犹说杞梁妻。",""],["庞公旧隐鹿门山，近在襄城汉水间。\n石洞草荒无路入，夕阳时见鸟飞还。",""],["习家池上草萋萋，流水成渠稻作畦。\n山简不来游客散，居人犹唱白铜鞮。",""],["大树萧萧白日寒，羊公祠下独凭栏。\n寻常一种青山石，长使行人洒泪看。",""],["东岳名高四海间，此山之外更无山。\n何时倚杖青云上，与尔朝登复暮攀。",""],["望岳亭临河水隈，碧窗遥对孔林开。\n谁知仰止平生意，不为岩岩气象来。",""],["岱宗西与太行临，岚翠霏微晓不分。\n底是灵州狄刺史，不看岩障只看云。",""],["沙海原南古战场，曲池荒畎荫堤长。\n相逢折得芙蕖赠，莫向西风笑冷香。",""],["大堤女儿花见羞，大堤杨柳映青楼。\n金壶满注樊城酒，醉杀狂夫不解愁。",""],["睡起僧房日未斜，兴来随处即为家。\n美人不见幽期渺，闲对苍黄数落花。","睡起僧房日未斜，兴来随处即为家。\n美人不见幽期渺，閒对苍黄数落花。"],["楝塘老人塘上游，飒飒西风吹素秋。\n记得看花三四月，满塘红紫映波流。",""],["竹坞柴关破晓开，石池花径转萦回。\n春深漫有寻芳兴，老近惭非作赋才。",""],["零零宵露湿春堤，杨柳风清晓月低。\n童子莫愁江路滑，老夫扶老有青藜。",""],["云浮剑阁夜英英，白马江边踏月行。\n传语啼猿莫相近，恐教游子不胜情。",""],["雨色岩花入牖斜，城中风景似山家。\n横琴不奏朱弦调，对菊惟看白玉花。",""],["十月霜庭菊正肥，亭亭寒影照山扉。\n野夫本是渊明侣，可怪淹留夜不归。",""],["红芳瘦尽绿阴肥，幽鸟枝头自在栖。\n一日天风吹羽翮，上林便作好声啼。",""],["客衣零落鬓毛斑，迢递沙场负骨还。\n三尺古碑千载恨，曹娥江上水潺潺。",""],["兴在桃源山水间，幅巾藜杖每忘还。\n沙田雨湿青牛卧，石洞花深白鹿闲。","兴在桃源山水间，幅巾藜杖每忘还。\n沙田雨湿青牛卧，石洞花深白鹿閒。"],["北窗无人春睡安，时闻春树鸟关关。\n老翁元是避喧者，又欲移家向别山。",""],["迢迢亲舍白云下，长日登楼思有馀。\n代谷燕山空说近，经时不见一封书。",""],["薰风帘幕燕翻翻，庭际榴花火欲然。\n睡起忽生千里思，慈颜一别又三年。",""],["雁门秋高多烈风，烟沙极目见云中。\n怜君弓马年来惯，不数翩翩塞上雄。",""],["红石冈头夜雨晴，湖田水满接堤平。\n行人欲问年丰俭，试向田中听鼓声。",""],["庭下梅花开未开，帝孙邀月久停杯。\n终知不入繁华梦，莫遣笙歌取次催。",""],["春眠不奈鸟声催，起立荒园傍古槐。\n怪底幽寻苦无力，梦中曾上故山来。",""],["草堂双燕垒新巢，坐感琴丝理断胶。\n麦饭一壶香一瓣，此情何处哭芳郊。",""],["好学平生说仲舒，绛帷常坐五更馀。\n春来睡足三竿日，应是无人唤读书。",""],["白发萧萧五十春，宦途犹作未归人。\n何时杖履柴门路，风景依然远俗尘。",""],["六月漳河舣客舟，小窗闲卧白云秋。\n怜君馈药如康子，不疗山翁四海忧。","六月漳河舣客舟，小窗閒卧白云秋。\n怜君馈药如康子，不疗山翁四海忧。"],["柳覆崇垣水护门，不依邻舍自为村。\n何缘却近山陵道，日夕时闻车马喧。",""],["薛家池中千叶莲，出波今已叠青钱。\n分栽不为看花色，要向山窗听雨眠。",""],["行尽荒山更涉溪，故人闻说在城西。\n空庭日午车马寂，惟有鹁鸪深树啼。",""],["翡翠衣裳云母軿，往来常在碧霄行。\n老君台上凌风过，王母池边看月生。",""],["一寸灵光万古心，笑看乌兔两升沉。\n已遣寿颜同紫玉，更欺仙骨比黄金。",""],["冉冉霓旌覆羽仙，双双玄鹤舞芳筵。\n眼看庭树真琼树，不数蓝田是玉田。",""],["江流山色绕金堂，管领年华入寿觞。\n仙家自与人间别，千岁都来一刻长。",""],["西园十月菊花黄，花底流泉水亦香。\n汲水采花宵酿酒，晓筵倾入万年觞。",""],["八旬遐齿三龄锡，四海升平见七朝。\n颍上漫随巢父隐，渭南还有太公招。",""],["晚照长云合，春帆细雨开。\n别离予正苦，魂梦子频来。\n石路齐南境，风花白下台。\n十年今去国，千里独怜才。\n会有荷裳寄，应烦想像裁。",""],["黄帝昔好道，相传驻此山。\n至今炼药处，犹见五云还。\n丹井霞空聚，清池水自潺。\n凤笙归寂寞，龙驾绝追攀。\n旷劫留仙迹，何年启佛关。\n看花周法界，钟鼓隔人寰。\n瀑响千岩应，潭虚万象闲。\n排空云木古，夹道翠泉环。\n涧鹿冲人返，山花照酒殷。\n寺荒翻雅淡，僧老更萧闲。\n问法空群妄，探奇始一斑。\n未能兼吏隐，回首愧尘颜。","黄帝昔好道，相传驻此山。\n至今鍊药处，犹见五云还。\n丹井霞空聚，清池水自潺。\n凤笙归寂寞，龙驾绝追攀。\n旷劫留仙迹，何年启佛关。\n看花周法界，钟鼓隔人寰。\n瀑响千岩应，潭虚万象閒。\n排空云木古，夹道翠泉环。\n涧鹿冲人返，山花照酒殷。\n寺荒翻雅淡，僧老更萧閒。\n问法空群妄，探奇始一斑。\n未能兼吏隐，回首愧尘颜。"],["忽报王孙使，新从相府旋。\n下阶忘病足，开牍醒愁眠。\n碧落仙人字，黄初大雅篇。\n空岩泣神鬼，白日走云烟。\n策杖东峰外，看碑北岳前。\n依微穿雪窦，想像俯春泉。\n客路千馀里，离心两隔年。\n倦游甘散拙，高举谢联翩。\n水国身犹寄，山堂梦屡牵。\n愧非清庙质，虚枉佩刀传。",""],["故居移杏圃，新宠沐枫宸。\n天马飞黄日，云龙际会辰。\n华陀初入魏，扁鹊旧鸣秦。\n术妙乾坤秘，功存社稷臣。\n东衢迎宝镪，西第拥朱轮。\n家是华胥国，人呼有脚春。\n翻嗟缝掖士，章句老风尘。",""],["碧落新移牒，玄津晚系槎。\n天临北斗地，人住上清家。\n树古金坛静，花深玉洞斜。\n灵砂飞绛雪，仙醴注青霞。\n缑岭音书密，函关道路遐。\n月明苍鹤羽，风度紫鸾车。\n几见桃成实，重闻海变沙。\n瑶窗礼星后，闲坐读南华。","碧落新移牒，玄津晚系槎。\n天临北斗地，人住上清家。\n树古金坛静，花深玉洞斜。\n灵砂飞绛雪，仙醴注青霞。\n缑岭音书密，函关道路遐。\n月明苍鹤羽，风度紫鸾车。\n几见桃成实，重闻海变沙。\n瑶窗礼星后，閒坐读南华。"],["路转长干渡，洲传白鹭名。\n沧波去不息，绿芷复丛生。\n隐隐江田抱，团团堰日明。\n镞沙沈壁垒，墙堞隐台城。\n湍古晴霓下，蒲深昼虎行。\n渔人牵网迹，商女踏歌声。\n佳丽千年恨，豪华六代情。\n经过夕临眺，谁并客舟横。",""],["上郡防戎切，中丞入陜遥。\n隼旗明晓甸，铙吹转春桥。\n二月花新缀，三川雪正消。\n北门来寇准，西极使班超。\n国仗和戎利，人传破胆谣。\n按图收地险，坚壁阻天骄。\n礼乐钦儒将，经纶翊圣朝。\n长城一身是，讵数霍嫖姚。","上郡防戎切，中丞入陜遥。\n隼旂明晓甸，铙吹转春桥。\n二月花新缀，三川雪正消。\n北门来寇准，西极使班超。\n国仗和戎利，人传破胆谣。\n按图收地险，坚壁阻天骄。\n礼乐钦儒将，经纶翊圣朝。\n长城一身是，讵数霍嫖姚。"],["暂布山东化，还为陇右行。\n中丞新受敕，贱子旧知名。\n玉露承冠剑，金飙卷旆旌。\n神羊心自直，孤隼势初横。\n地接祈连砦，星罗冒顿营。\n未须怀破斧，先喜号长城。\n草映边云白，沙流汉月明。\n陜人歌召伯，关吏识终生。\n许国知公志，通家是我情。\n离筵忽隔水，秋望转盈盈。","暂布山东化，还为陇右行。\n中丞新受敕，贱子旧知名。\n玉露承冠剑，金飙捲旆旌。\n神羊心自直，孤隼势初横。\n地接祈连砦，星罗冒顿营。\n未须怀破斧，先喜号长城。\n草映边云白，沙流汉月明。\n陜人歌召伯，关吏识终生。\n许国知公志，通家是我情。\n离筵忽隔水，秋望转盈盈。"],["奉诏还将母，南归乐未涯。\n日明吴苑树，风引邵陵槎。\n万里遥瞻阙，三湘近接家。\n望滩怀孔雀，临洞识桃花。\n寿祝青山永，书传碧海遐。\n赵张前史艳，曾闵后人夸。\n去值桑蚕老，迎看竹马斜。\n却怜春别苦，飞絮满江沙。","奉诏还将母，南归乐未涯。\n日明吴苑树，风引邵陵槎。\n万里遥瞻阙，三湘近接家。\n望滩怀孔雀，临洞识桃花。\n寿祝青山永，书传碧海遐。\n赵张前史艳，曾闵后人誇。\n去值桑蚕老，迎看竹马斜。\n却怜春别苦，飞絮满江沙。"],["晓骑传中旨，春曹陟上卿。\n乐推吴季札，经许郑康成。\n车马秋江出，乡邦昼锦行。\n论交袜始结，惜别盖初倾。\n拜手双龙阙，承恩五凤城。\n御阶听曳履，枢密待持衡。\n制作登三殿，声华振八瀛。\n新班岱岳重，旧寺雪山轻。\n古貌看常健，冰衔列自清。\n英英伯夷志，垂白转精明。",""],["蜀道军容使，秋风振旅还。\n功成万里外，捷报五云间。\n电扫妖氛灭，川流战血殷。\n汉兵随指顾，蕃部凛威颜。\n晓坐辕门静，宵登剑阁闲。\n丹心悬海日，绣斧照江关。\n饮马瞿唐峡，封刀麦子山。\n班超桓典后，芳驾几人攀。","蜀道军容使，秋风振旅还。\n功成万里外，捷报五云间。\n电扫妖氛灭，川流战血殷。\n汉兵随指顾，蕃部凛威颜。\n晓坐辕门静，宵登剑阁閒。\n丹心悬海日，绣斧照江关。\n饮马瞿唐峡，封刀麦子山。\n班超桓典后，芳驾几人攀。"],["见说林居胜，清江绕舍流。\n元方登琐闼，小谢隐沧洲。\n草茜辰占丽，梧飘岁识秋。\n烟霞互吞吐，鸥鹭接飞浮。\n日有高轩过，时同静者游。\n麈挥山榻冷，棋对竹窗幽。\n宝笈通三昧，牙签富九丘。\n侧闻能尚志，应不爱封侯。\n薇省牵魂梦，萸樽阻唱酬。\n讵谙方岳寄，深切庙廊忧。",""],["吴子近南游，龙江复虎丘。\n三分形胜地，六代帝王州。\n望月晴临峤，听潮夜泛舟。\n宝珠商女得，灵剑海人求。\n去日蘼芜绿，归来菡萏秋。\n逢宵话奇赏，吾兴亦云浮。",""],["送归客，送归客，东城复西苑。\n碧草萋萋别路长，苍山历历愁心远。\n愁心远征，驾不可留。\n去年送归陌上雪，今年送归江上秋。\n江上秋江雨霁，返照入林光翳翳。\n家在齐川未得归，年年送客来沙际。\n送归客，请客听我歌。\n我如水中凫，君如江上波。\n波流去不息，凫飞无远翼。\n回桥转岸君已遥，薄暮徘回此何极。",""],["风怒号，振城瓦。\n塞草白，朔云赭。\n汉兵出火，扫荡原野。\n祝融驰，炎帝下。\n腾赤龙，走朱马。\n云涛沸，星雨洒。\n黄沙一望千里通，魍魉书啼巢穴空。\n敌人临水不敢过，将军归来闭关坐。",""],["大儿龙，小儿虎。\n碌碌犬与豚，眼中何足数。\n将军回猎骑，帐下斑衣舞。\n天河东倾月西落，兰膏夜射帘珠薄。\n庭槐乌鸟栖复惊，弦诵声高应金柝。\n将有法，兵有机，吁嗟易闻不易知。\n长平一坑万人死，君不见，邯郸子。",""],["苫为席，块为枕，憔悴孤儿墓田寝。\n墓田树，声萧萧，寒涛卷空风叶飘。\n树不止，风不息，孤儿欲化田中石。","苫为席，块为枕，憔悴孤儿墓田寝。\n墓田树，声萧萧，寒涛捲空风叶飘。\n树不止，风不息，孤儿欲化田中石。"],["海上屋，几千尺。\n丽日起扶桑，鳞鳞曙烟碧。\n仙筹刻玉云花湛，海尘一飞筹一点。\n借问仙翁寿几何，十屋仙筹充画槛。\n仙翁家住海中村，平原公子宋王孙。\n相逢欲访桑田事，双鹤何年下海门。",""],["岿岿光复堂，汤汤岁寒溪，故家世业传江西。\n他园岂无木，重是祖手植。\n他地岂无土，重是祖手辟。\n物生各有主，天道终好还。\n岚光映朝牖，不改门前山。\n堂有趾，溪有涘，我溪不竭堂永峙。",""],["舟横断岸日斜，雁度空山落霞。\n欲采芙蓉赠远，秋江何处天涯。",""],["一溪流水秋碧，两岸垂杨昼阴。\n绝爱王家池馆，酒旗低拂波心。",""],["田田莲叶洲北，寂寂孤亭水南。\n恐有人来摘取，淆他万顷清潭。",""],["村南村北云山，亭外亭中烟景。\n东岩过客重来，萝径萧萧薄暝。",""],["鸟啼千树万树，云起前山后山。\n门外青春向晚，雨中游客西还。",""],["西山半衔落日，东岭尚宿归云。\n雨过荒村向暮，柴门流水沄沄。",""],["瓠叶翻翻雨骤，竹枝袅袅风斜。\n忽见绿柽花发，犹疑春在山家。",""],["流莺百啭深树，巢燕双飞短帘。\n过客不惭阮籍，主人只似陶潜。",""],["烟中白鸟双度，草际黄牛独还。\n山寺暮钟何处，随风飘落人间。",""],["缀树同梅止渴，登筵比蔗生津。\n却忆帝炉烧赐，曾分衣白山人。",""],["淮北荥南接境，冻姿霜色含秋。\n如得此君万颗，岂论千户封侯。",""],["不缘摘取商洛，定自传分秣陵。\n笑杀山妻鄙俗，安排慢火相蒸。",""],["武帝巡游不返，文园渴病难除。\n谁致内林一颗，且成封禅之书。",""],["隼旟低拂垂柳，骢马娇嘶落花。\n碣石春风万里，卢沟晓月千家。",""],["生憎白云春去，无奈黄莺昼啼。\n欲采芙蓉赠远，北湖莲叶初齐。",""],["廊庙江湖身世，先忧后乐心情。\n本是仲淹孙子，怪来夷夏知名。",""],["君山已归地下，燕泉却在天南。\n落落故人如此，萧萧短发何堪。",""],["向风征马频嘶，独客行吟古堤。\n百里文星斗下，三年水部河西。\n遥心浦树烟渺，短梦城乌曙啼。\n记取今宵醉别，雪堂灯火凄凄。",""],["还耕惬初愿，揖世返空林。\n虽非志士理，已获静者心。\n嘉宾清云客，枉驾忽相临。\n携酒共斟酌，张弦扬妙音。\n义厚情自叶，道合契滋深。\n漪漪𣲗川水，幽幽南山岑。\n相值不相乐，奈此逝者侵。","还耕惬初愿，揖世返空林。\n虽非志士理，已获静者心。\n嘉宾清云客，枉驾忽相临。\n携酒共斟酌，张弦扬妙音。\n义厚情自叶，道合契滋深。\n漪漪湋川水，幽幽南山岑。\n相值不相乐，奈此逝者侵。"],["初夏草木长，鸣雨更相逼。\n来牟生意佳，枝旟望如织。\n阳日不下临，此物终且蚀。\n往者己巳夏，颇为旱干棘。\n徂春苦无雨，两麦俱丰息。\n因怀老农语，往往未差忒。\n穷居繁口食，所恃耕耨力。\n明日更如此，与君甚胸臆。","初夏草木长，鸣雨更相逼。\n来牟生意佳，枝旟望如织。\n阳日不下临，此物终且蚀。\n往者己巳夏，颇为旱乾棘。\n徂春苦无雨，两麦俱丰息。\n因怀老农语，往往未差忒。\n穷居繁口食，所恃耕耨力。\n明日更如此，与君甚胸臆。"],["春中渡河阳，倏忽到曲里。\n满村开杏花，参差亦堪喜。\n关吏自北来，云承吕夫子。\n遣之迎野翁，谨愿颇谦礼。\n述答俱有章，稽援或通理。\n感叹君子居，端能化凡鄙。\n隔岁慕良觌，不谓迩若此。\n芳春解人意，夹路叠红紫。\n宿酲方苦人，毕览兴弥起。",""],["积怨世岂恻，感别会仍艰。\n置酒话夙昔，讵终千万端。\n叹息泪沾臆，徒令摧肺肝。\n昔为双飞龙，今为孤翼鸾。\n丈夫耻微谅，况尔烈士颜。\n跃马窖上别，欲归中自难。\n徒切报主恨，安悔军吏言。\n胜负有微数，奋励心所安。\n所以君子人，不处嫌疑间。",""],["春风缬芳林，虚堂翳修竹。\n苟惬静者心，宁惭世人目。\n昔予怀此游，悠悠几更宿。\n岂期联舆来，沉醉卧兹曲。\n高歌叹往踪，遐眺览前躅。\n主人古司徒，雅兴薄裴陆。\n但能永今夕，何忧乏?醁。","春风缬芳林，虚堂翳脩竹。\n苟惬静者心，宁惭世人目。\n昔予怀此游，悠悠几更宿。\n岂期联舆来，沉醉卧兹曲。\n高歌叹往踪，遐眺览前躅。\n主人古司徒，雅兴薄裴陆。\n但能永今夕，何忧乏?醁。"],["秋风西北来，偃蹇坐茅屋。\n四壁无纤尘，当窗有书牍。\n不问作者谁，启窗再三读。\n一读意已骇，三读见衷曲。\n忆昔年少时，心志各有蓄。\n不意谬通籍，先君被薄禄。\n朝夕望君起，如彼饥者谷。\n我已罢馆职，君方屧官禄。\n味苦不可人，旋车亦何促。\n主上尧舜姿，旧章理当复。\n平生稷契心，岂为世情覆。\n尚期谨药石，慰此百姓蹙。\n予也素蹇劣，兹志每中熟。\n屡犯涵逊怀，几搆邪罔狱。\n顾影苟不亏，于道果奚辱。\n山水性所嗜，喧恢岂吾欲。\n屈指君归来，三年但忽倏。\n人生不满百，激励在初服。\n可似山中人，忘机泛?醁。",""],["鸿雁不老越，蛟龙不潜冈。\n平生志嘉遁，佐储抑何狂。\n因叹务光辈，恻恻令心伤。\n传记尚溢美，其言或荒唐。\n嗟彼高帝业，赫赫继三王。\n孺子安所见，胡为遽辞商。\n契会视豪杰，出处圣所详。\n感叹掷其策，愿为史臣伥。",""],["天边有黄鹄，高飞一千里。\n烈士耻庸节，世事特敝屣。\n朝辞上东门，暮从赤松子。\n感嘅风云期，超悟往还理。\n进既有所因，退亦何所倚。\n猎犬贪兔狐，不免灶傍死。\n富贵多崄巇，英雄如蝼蚁。\n所以明哲人，穷达重徇已。",""],["泥泞抵终南，迷蒙失山色。\n指点太平宫，崔嵬白云极。\n不暇自抖擞，冒雨且综核。\n凭高瞷村落，嘉树万重黑。\n此地索灵异，气候故不测。\n旦日云气消，嫩碧竞寰域。\n绿草弥望浮，波光与山逼。\n迤逦白鸟来，涤荡千虑息。\n宿性喜丘壑，跻攀易筋力。\n深秋事佳游，长歌厌轻默。\n早晚幽卜筑，终以卧斯侧。",""],["穷居无别悰，扫径揖清霭。\n浊醪自斟酌，幽花复芬馤。\n虽微恣性欢，亦鲜迷津嘅。\n寒虫相续鸣，潦水参互沛。\n节物渐以更，人事纷相代。\n猗彼巢由徒，旷音昭物外。",""],["此日复何日，眷言会君子。\n方拟跃马寻，忽焉具来止。\n来止将何为，握手论文史。\n春城沽酒佳，斟酌一何喜。\n普缘古仙游，山水嘉无比。\n若赋南山篇，请君自兹始。",""],["我本支谩人，啸歌浒西曲。\n心喜谈道术，性憎傍尘俗。\n二君英俊才，世事岂拘束。\n同游终南山，文采夺人目。\n数日返墟里，此意常在腹。\n因念苏与黄，声臭一何属。\n我有辋川吟，鄙近不可读。\n请君勉和之，永为此行馥。",""],["汝母我之姊，同胞无别亲。\n不幸去年死，㷀㷀惟汝身。\n汝父既早没，汝依当何人。\n数数与汝语，令我泪沾襟。\n汝性颇灵慧，力作何不勤。\n青春易凋丧，岁月良可珍。\n汝能事卓立，非止裕汝屯。\n指名为令士，汝亲当见伸。\n何苦逐游冶，弗肯志讨论。\n挞之尚不易，况乃颊舌云。\n汝祖好男子，豪爽多誉闻。\n辛苦教汝父，冀登要路津。\n汝父乃不谷，漂荡成苦贫。\n幸以汝母故，托居我南邻。\n黾勉相劝讽，粗能御寒温。\n谓将致兴发，岂意掩泉坟。\n遗汝无寸土，汝母复长沦。\n近日乏良吏，役赋甚纷纭。\n富者尚难理，贫者安可徇。\n不见抬舆者，四体如火薰。\n不见负输者，锁桎令肉皴。\n我年已五十，岂得常逡巡。\n作诗以告汝，请汝书诸绅。","汝母我之姊，同胞无别亲。\n不幸去年死，㷀㷀惟汝身。\n汝父既早没，汝依当何人。\n数数与汝语，令我泪沾襟。\n汝性颇灵慧，力作何不勤。\n青春易凋丧，岁月良可珍。\n汝能事卓立，非止裕汝屯。\n指名为令士，汝亲当见伸。\n何苦逐游冶，弗肯志讨论。\n挞之尚不易，况乃颊舌云。\n汝祖好男子，豪爽多誉闻。\n辛苦教汝父，冀登要路津。\n汝父乃不谷，漂荡成苦贫。\n幸以汝母故，托居我南邻。\n黾勉相劝讽，粗能禦寒温。\n谓将致兴发，岂意掩泉坟。\n遗汝无寸土，汝母复长沦。\n近日乏良吏，役赋甚纷纭。\n富者尚难理，贫者安可徇。\n不见抬舆者，四体如火薰。\n不见负输者，锁桎令肉皴。\n我年已五十，岂得常逡巡。\n作诗以告汝，请汝书诸绅。"],["为荐吕夫子，因之泾渭川。\n中道遇来使，慇勤出素编。\n久知滞王役，不谓会此廛。\n晴春悬明月，惠风乘远天。\n木末双舆至，迎我城西阡。\n握手但相笑，恐是梦寐然。\n宴我旅人舍，坐我紫毹毡。\n童子出名酒，饮如鲸吸川。\n吕君赋葛藟，予具南山篇。",""],["自予抱幽戚，三载鲜游眺。\n春日忽言征，聿底沧洲妙。\n柳色参差生，芳意远近耀。\n张宴临溪波，弹琴递清调。\n惠风当襟怀，游赏恣舒啸。\n匪效苏门狂，将追虎溪笑。\n少日牵王役，结绶事廊庙。\n粗直虽见称，龌龊果成诮。\n馌稼浒西曲，探奇历幽徼。\n叹君本素心，晤言希久要。",""],["适性即为乐，处安宁怨贫。\n客来遗我书，乃在泾水滨。\n再拜读此书，道意何慇勤。\n昔为鸾与凤，今为参与辰。\n相思千万端，缕缕难具陈。\n浮云蔽白日，游子殊苦辛。\n道远行不易，戚恻伤我心。",""],["桑君英妙人，恨与识不早。\n脱颖岂性成，豪爽盖天造。\n再会益琤琤，故言皆了了。\n眼底似君稀，勉旃为世宝。\n半年下山寺，乃趍坊里道。\n所过六七村，村村胜城堡。\n柝声远近连，人家气色好。\n共言今两年，怀抱绝不恼。",""],["我前抵华原，访子云槐舍。\n偶值何仲默，清谈忘晨夜。\n冲怀世寡知，繁文俗方化。\n芳臭不同科，辩别每未暇。\n群口虽见珍，私心窃常讶。\n庄生吾马云，其见岂欺诈。\n后会王敬夫，飘然契兹话。\n乃钦吾侪真，益陋杞妻下。\n浒西春酒熟，南山翠如射。\n明日会同君，细看盘谷画。",""],["古意世方疾，太音人和稀。\n岂不逐群好，恐与贤达违。\n朝游三畤原，暮宿唐山矶。\n感此荣悴异，已悲驰骛非。\n所以素心者，见之心每希。\n灼灼园中花，膴膴南山薇。\n及兹不努力，老大将焉归。",""],["膏雨既周彻，田工粗可期。\n黾勉命童仆，篮舆诣东菑。\n欣此麰麦遂，坐令芳意弥。\n业岁望丰衍，行乐值晴熙。\n况与良士同，更惬山水思。\n击筑发古调，弹筝奋新词。\n夜以继白日，潇洒孰可追。",""],["达旦不成寐，卧听秋雨声。\n雨亦竟不歇，吾意何时平。\n前年秋八月，淫雨百谷盈。\n禾稼尽腐黑，况云屋圮倾。\n此雨复弥月，岩崖千里崩。\n不知上帝意，岂欲移苍溟。\n吾生殊坎轲，一纪事农耕。\n两田俱不稔，百口常见婴。\n奈何越庸调，已欲樵栋楹。\n老妻向我道，但坐且勿惊。\n人事尚莫定，天道宁易明。\n修短有恒数，丰歉惟所丁。\n床头有美酒，馨香盈玉瓶。\n君姑自斟酌，可以助颓龄。\n醉卧忽将午，此物方雷鸣。","达旦不成寐，卧听秋雨声。\n雨亦竟不歇，吾意何时平。\n前年秋八月，淫雨百谷盈。\n禾稼尽腐黑，况云屋圮倾。\n此雨复弥月，岩崖千里崩。\n不知上帝意，岂欲移苍溟。\n吾生殊坎轲，一纪事农耕。\n两田俱不稔，百口常见婴。\n奈何越庸调，已欲樵栋楹。\n老妻向我道，但坐且勿惊。\n人事尚莫定，天道宁易明。\n脩短有恒数，丰歉惟所丁。\n床头有美酒，馨香盈玉瓶。\n君姑自斟酌，可以助颓龄。\n醉卧忽将午，此物方雷鸣。"],["励志古犹鲜，嗟尔英妙人。\n超然契神理，谢此曲米春。\n盛时富游燕，昌龄当令辰。\n但恐乐不满，安知中足嗔。\n所以贤达士，寸阴日以珍。\n张甥出名裔，磊落吾所亲。\n奋迅冀往哲，慷慨怀先民。\n述此止酒事，言辞皆绝伦。\n彭泽虽有作，徒以愠同尘。\n岂若慕宏达，精诣吾道津。\n事以久乃定，节惧中路屯。\n愿言永初服，白首以为真。",""],["还车浒西曲，半山含暝色。\n朔风刺我衣，欲止不可得。\n入城逢都人，白马衔金勒。\n下马揖车前，被服甚奇特。\n授我一缄书，题识颇修敕。\n展书读其辞，耿耿乱胸臆。\n一别十三年，安知如顷刻。\n劳君远问讯，况此常相忆。\n习静厌世喧，冠冕志颇息。\n秦马不嘶越，南鸟岂栖北。\n野人各有怀，所务在稼穑。\n慇勤谢都人，去去慎登陟。",""],["悠悠不能寐，恻恻与心违。\n百岁若一瞬，怨言长分飞。\n结发溯伊始，搴帷念馀辉。\n纫兰坐崇阿，调弦拂金徽。\n志愿各相许，窀穸幸同归。\n岂期中道别，空馀衾与衣。\n临风想德音，当窗拭残机。\n往者既莫谅，嗣者安可希。",""],["陟山披丛薄，览景惬幽素。\n降观万壑奔，平临千嶂赴。\n宿爱弥见欣，新赏豁相聚。\n未睹赤城游，彷佛兴宗赋。",""],["秋雨复如注，旌旗仍赴西。\n仆马不能立，杯酒那可携。\n公归定十月，山庄事粗没。\n新酿既已成，嘉殽有薇蕨。\n即今搆小亭，亭成伫公坐。\n虽无丝竹陈，可试风雅课。\n南山秋暮佳，气色清且翠。\n眺览既中惬，啸歌或幽邃。\n此役千国经，天下由重轻。\n古哲务成事，今人唯酿名。\n往往十年迩，边陬太乏理。\n舆皂皆所亲，毁誉出憎喜。\n虽悉延访心，纷乱若丝枲。\n积今日益滋，君子复轻信。\n自谓根蒂获，岂有纤细近。\n治边如治鲜，要在审其势。\n剖断贵神速，宰制厌牵系。\n近闻甘泉城，皇皇尽危惧。\n主者谕不开，仓卒何以计。\n远人遵讹言，其情易摇曳。\n片言昆仑摧，转拟万夫毙。\n公固岂弟人，弛张有程具。\n向既失缓急，今且须砥砺。\n同事六七公，休休皆伟器。\n当事必安舒，临机戒轻蓦。\n嗟嗟千里心，顾此岂能白。\n亦知刍荛微，赠公冀公择。","秋雨复如注，旌旗仍赴西。\n仆马不能立，杯酒那可携。\n公归定十月，山庄事粗没。\n新酿既已成，嘉殽有薇蕨。\n即今搆小亭，亭成伫公坐。\n虽无丝竹陈，可试风雅课。\n南山秋暮佳，气色清且翠。\n眺览既中惬，啸歌或幽邃。\n此役千国经，天下由重轻。\n古哲务成事，今人唯酿名。\n往往十年迩，边陬太乏理。\n舆皂皆所亲，毁誉出憎喜。\n虽悉延访心，纷乱若丝枲。\n积今日益滋，君子复轻信。\n自谓根蒂获，岂有纤细近。\n治边如治鲜，要在审其势。\n剖断贵神速，宰制厌牵系。\n近闻甘泉城，皇皇尽危惧。\n主者谕不开，仓卒何以计。\n远人遵讹言，其情易摇曳。\n片言昆崙摧，转拟万夫毙。\n公固岂弟人，弛张有程具。\n向既失缓急，今且须砥砺。\n同事六七公，休休皆伟器。\n当事必安舒，临机戒轻蓦。\n嗟嗟千里心，顾此岂能白。\n亦知刍荛微，赠公冀公择。"],["君家篆江侧，秀屏当户开。\n知是神仙人，胡为尘世来。\n黄氛缁素车，皂盖冒朱埃。\n以兹谢民役，返耕白云隈。\n少小稽古昔，中式得此阶。\n亦知慎官服，奈与寸心违。\n欲往昧前算，欲止递成哀。\n繄予丘壑士，谛此良用骇。\n因陈接淅义，颇究蓬矢怀。\n我固互相发，君固耿难回。\n丈夫志四海，好念济川才。\n嗟彼长沮徒，泛泛岂根荄。",""],["返耕厕幽壑，服义屈高轩。\n握手立斯须，倾倒见雄论。\n昔宦志孤陋，中路忽履屯。\n负罪苟不死，兹已含溢恩。\n疏懒循故性，竟志纫山荪。\n感君缱绻意，幡然谢前闻。\n杀鸡馔雕胡，列坐开荜门。\n斗酒醉方已，徘徊惜日曛。\n今夕别君去，孟冬定回辕。\n尚期撰杖屦，共眺南山云。",""],["明农谢昌宦，良觌羡予征。\n敦义昔所重，况此骨肉情。\n嗣岁节物改，朱阳喜开晴。\n感今叹伊昔，发车临广庭。\n所期德音迈，永修三径盟。","明农谢昌宦，良觌羡予征。\n敦义昔所重，况此骨肉情。\n嗣岁节物改，朱阳喜开晴。\n感今叹伊昔，发车临广庭。\n所期德音迈，永脩三径盟。"],["平生尚超旷，结庐武亭川。\n本非青云姿，竟作金闺愆。\n托交三十载，孤抱亦何渊。\n邈观古昔事，弥想梁甫篇。\n感此发深省，誓以俟馀年。",""],["露坐架棚箔，邻翁高兴多。\n转觞话农事，绝胜陈绮罗。\n西村二三子，携酒复相过。\n忽忽至更尽，悠悠奈乐何。",""],["我来彭麓下，坐爱青山色。\n雨过忽新凉，苍烟望无极。\n秋禾行欲成，岂畏骄阳逼。\n垄亩绿如屯，原隰少螟螣。\n同欣有年乐，讵知天子力。",""],["层峰拱堂宇，苍翠何嵲嶭。\n盈盈青衿子，弦诵夜不辍。\n斯文今在兹，感叹怀往哲。\n繄予值乖蹇，望道日辽绝。\n衣冠羞壮游，疏懒愧先烈。\n结交君子徒，努力崇明德。\n变故身屡轻，涵养意恒切。\n岁序不待人，君子慎其节。",""],["诸君青云姿，宿志各高尚。\n奋迅良有期，优游每中谅。\n修礼慎逸居，稽古却支宕。\n得师忻折衷，遵道决趋向。\n我来坐兹堂，诵习惟睹创。\n始信豪杰人，履历不虚妄。\n科条从昔云，谦恭见今让。\n文采虽所珍，躬行以为上。",""],["近世尚夸毗，造诣实终鲜。\n徒以言语微，遂谓道昏显。\n推行跬步艰，况此继坟典。\n狂澜及明兴，愈觉支粗浅。\n徒有析理名，竟为粉饰免。\n天锡泾野君，特被人文选。\n笃行遵诚明，因时表舒卷。\n吾道果不绝，觌此脉如线。",""],["猗猗青衿子，励志各有图。\n逸志凌天云，丽作惊九区。\n或为庙廊器，或为章句徒。\n华丰实乃啬，枝荣干还枯。\n岂若铲雕琢，逖为君子儒。\n所需出所养，与世作匡扶。\n蓺谷谛嘉种，种木审良株。\n我诗揭堂左，百尔慎所趋。",""],["澄莹绝纤翳，一泓泻千里。\n寒月摇轻波，山光彻波底。\n鱼鰅不敢游，虬龙得猗狔。\n转盻清素心，挹饮涤凡鄙。\n平生畏炎蒸，见之辄中喜。\n愿言保真寂，勿以尘氛浼。","澄瑩绝纤翳，一泓泻千里。\n寒月摇轻波，山光彻波底。\n鱼鰅不敢游，虬龙得猗狔。\n转盻清素心，挹饮涤凡鄙。\n平生畏炎蒸，见之辄中喜。\n愿言保真寂，勿以尘氛浼。"],["𬨎车戒晨发，循此东南域。\n握手立斯须，徘徊意安极。\n念子有幽思，别言心如织。\n昔为同生兰，今为特飞翼。\n人生易悲乐，良晤昔所恤。\n黄尘暗清渭，对飧安可食。\n嗟嗟君子心，遐眺在燕北。","輶车戒晨发，循此东南域。\n握手立斯须，徘徊意安极。\n念子有幽思，别言心如织。\n昔为同生兰，今为特飞翼。\n人生易悲乐，良晤昔所恤。\n黄尘暗清渭，对飧安可食。\n嗟嗟君子心，遐眺在燕北。"],["昔并少陵骑，长眺望夷宫。\n故都多景象，近迹迷往雄。\n感嘅发孤咏，宛若思悲翁。\n粤惟霸上玦，已昧天所穷。\n自非大雅操，讵识卑与崇。\n挹泉漱寒碧，酌醴揖群公。\n志直意不忝，巍然君子风。",""],["关辅比多事，钦公能自绥。\n养寇盖往昔，弭乱岂今䚹。\n崇货狎卑吏，饰貌忘远规。\n公来屏笑色，事至任安危。\n素衷物莫浼，逸驾古所窥。\n虽有麛裘谤，倏动赤舄悲。\n所以丈夫行，不与流俗随。",""],["逍遥奋孤迈，葳蕤惬渊想。\n北眺崆峒津，南瞷孟诸坱。\n麾麈靖疆场，抚剑清罔象。\n黔庶丁溢恩，牧宰获嘉赏。\n中原久疮痍，西州独丰穰。\n感叹乖崖心，讵俟益州榜。\n夷诵南山章，令人发森爽。",""],["道以无垢尊，迹超诚所贵。\n皇皇廊庙姿，世运实经纬。\n翩翩翊鸿业，皎皎分万汇。\n嗟自丁卯来，海宇日腾沸。\n群公徒悯艰，虚恢果奚谓。\n薄俗慕驩虞，君子念聋聩。\n巍巍城边略，足回万夫气。",""],["披丛憩轩下，抚卷辄中惭。\n笑我伎微薄，无能续高骖。\n缅思雄咏侈，一发连数函。\n咀嚼味逾隽，咏叹诚所耽。\n赠瑶似刘傅，酬德怅庐参。\n清风溘将远，鄙志揆岂堪。\n那知邂逅际，复送旌旆南。",""],["公归止信宿，予饯苦淹后。\n耿耿徒忧伤，役役定谁咎。\n忆昔承明直，相企亦已厚。\n公念薄绮纨，予质等蒲柳。\n虽能慎初服，终恐易衰朽。\n乐游观五陵，气候稍非旧。\n叹息君子陈，宵兴望南斗。",""],["徂岁始炎郁，岩洞共公萃。\n趣若陶公琴，兴越滁守醉。\n旁眺牛头原，横坐竹林邃。\n微风涤烦襟，冲抱浥灵秘。\n偶闻林鸟鸣，遽动舞雩喟。\n公度比莘父，予志岂荷蒉。\n喜贶弥笥来，欲和复中避。",""],["悠悠长安道，车骑纷如云。\n父老泣相谓，童稚声欲吞。\n借问道傍士，述答甚慇勤。\n三秦失慈母，黔首怀使君。\n饯送顺心意，昊天安肯闻。\n徘徊玩此语，感嘅异前云。\n不睹泽门诵，焉契章甫文。",""],["予怀絷莫即，公训安可聆。\n矢诗虽不多，聊以宣德馨。\n高驾既难挽，孤忠益屏营。\n北风嗣元序，节物改仙蓂。\n追送理应及，郁陶浩岂平。\n华山有崎崛，髣髴出青冥。\n烦公待予至，同访少微星。",""],["独居意靡畅，行吟心更伤。\n晨发望原际，佳气郁相望。\n恨无同怀人，跃马陟暾冈。\n徘徊日忽暮，感叹琴屡张。\n山妻出美酒，斟酌为君尝。\n三觞起孤抱，百忧忽若忘。\n丈夫生世间，磊落斯所臧。\n何须久郁郁，自如陌上桑。",""],["我闻白石楼，乃在太行下。\n丹梯凌紫霄，朱甍接岩罅。\n盘郁横汾曲，崔巍紫金叉。\n斜烟荡洄潏，朝晖耀檐庌。\n两溪互萦带，千峰随晦冥。\n嶂屏万翠列，花柳四时明。\n平生喜游眺，讵可如孙登。\n春中过函谷，遂有渤澥行。\n徒怀南庄老，安能惬初盟。\n人事苦促迫，三日滞虞乡。\n虽有泛舟趣，却无曾点狂。\n回想王官谷，新诗满素墙。\n不识仲南姓，徒怀诗思长。\n便思与握手，于时共徜徉。\n同游诵其名，知是南庄子。\n故家有若人，私为李公喜。\n翱翔翰墨场，倏忽逾四纪。\n不谓英俊姿，尚在秦晋里。\n何当登此楼，醉汝贤乔梓。\n三叹发朝邑，弥月兴犹起。\n感君寄书至，展转爱君才。\n欲见不可得，空望白云隈。\n吾有双黄鹤，飞飞自天来。\n因逢王子晋，借之游蓬莱。\n一去竟千载，寥寥犹未回。\n回时坐鹤背，挈子临高台。\n先过昆仑顶，后瞷弱水涯。\n徐访紫华君，持其双玉芝。\n吾意竟不歇，君心幸勿改。\n寄君白石吟，惟君为予待。","我闻白石楼，乃在太行下。\n丹梯凌紫霄，朱甍接岩罅。\n盘郁横汾曲，崔巍紫金叉。\n斜烟荡洄潏，朝晖耀檐庌。\n两溪互萦带，千峰随晦冥。\n嶂屏万翠列，花柳四时明。\n平生喜游眺，讵可如孙登。\n春中过函谷，遂有渤澥行。\n徒怀南庄老，安能惬初盟。\n人事苦促迫，三日滞虞乡。\n虽有泛舟趣，却无曾点狂。\n回想王官谷，新诗满素墙。\n不识仲南姓，徒怀诗思长。\n便思与握手，于时共徜徉。\n同游诵其名，知是南庄子。\n故家有若人，私为李公喜。\n翱翔翰墨场，倏忽逾四纪。\n不谓英俊姿，尚在秦晋里。\n何当登此楼，醉汝贤乔梓。\n三叹发朝邑，弥月兴犹起。\n感君寄书至，展转爱君才。\n欲见不可得，空望白云隈。\n吾有双黄鹤，飞飞自天来。\n因逢王子晋，借之游蓬莱。\n一去竟千载，寥寥犹未回。\n回时坐鹤背，挈子临高台。\n先过昆崙顶，后瞷弱水涯。\n徐访紫华君，持其双玉芝。\n吾意竟不歇，君心幸勿改。\n寄君白石吟，惟君为予待。"],["三年困人事，何曾理书帙。\n鸟鼠白昼游，入门忽首疾。\n架阁具倾覆，点检切中怵。\n凌晨趣洒扫，整顿倏终日。\n种类既品题，编简复齐一。\n不但几案清，幸靡万一失。\n焚香坐望馀，俨然成静室。\n平生风雅情，殊以乖蹇窒。\n追惟感叹生，端坐还羞㥾。\n何如溪上翁，翩翩独闲逸。","三年困人事，何曾理书帙。\n鸟鼠白昼游，入门忽首疾。\n架阁具倾覆，点检切中怵。\n凌晨趣洒扫，整顿倏终日。\n种类既品题，编简复齐一。\n不但几案清，幸靡万一失。\n焚香坐望馀，俨然成静室。\n平生风雅情，殊以乖蹇窒。\n追惟感叹生，端坐还羞㥾。\n何如溪上翁，翩翩独閒逸。"],["此日春气和，万木具含秀。\n况我山林居，园列颇成就。\n客自盩厔来，驱车扣圭窦。\n白杨二百株，绋纚载其后。\n根繁生意多，干润理宜茂。\n倩人速植之，行列未差谬。\n虽惬静者心，尚祈后土祐。\n浇灌分所勤，盘踞晚应觏。\n结庐谢王役，怀愚负时谬。\n糊口聊秉耕，舒形得佳岫。\n即非松菊场，已还榆柳旧。\n但资歌啸心，绝胜笙竽奏。",""],["三月诣兹曲，八月今始复。\n结辔送君归，投壶泛?醁。\n风清怀抱优，暑退凉气淑。\n我歌苦不长，聊以咏幽独。\n荒径残草多，空堂蛛网覆。\n岂无洒扫资，纷纠在尘俗。",""],["时日得君来，开豁极心目。\n夜坐对明月，清谈倒筐腹。\n方儗千日欢，讵忍后期促。\n饯子卓午天，徘徊日西没。\n眷恋勿复言，去去保馀馥。",""],["诗人古不易，流靡及兹俗。\n片言务剽窃，侃侃遂骄足。\n还耕十三载，安能惬吾欲。\n览子中秋篇，翩然接华毂。\n大雅当在兹，斯文有归宿。\n丽藻虽可珍，雄浑久未复。\n愿言溯其源，开彼汉魏毒。",""],["我登罨翠楼，川原郁回合。\n方喜风雾开，倏见烟云匝。\n直东看黄山，三秦如堵圜。\n兴亡理堪惜，念之凋朱颜。\n同把一尊酒，劝君为君寿。\n莫负当春游，人生若刍狗。",""],["我闻昔人言，此即汉漆县。\n其东故有邰，草木殊葱茜。\n终南当面朝，清渭过如练。\n直北倚黄山，逶迤控周甸。\n前望松桧场，知是何王殿。\n王迹日以微，气色或隐见。\n西南庆善宫，郁当漆村面。\n胜地迁变多，往躅审弥眩。\n繄自虞夏来，百祥具兹奠。\n地灵昔所庇，谛此窃中羡。",""],["长川直南泻，清渭横其冲。\n灏光触云汉，此下潜真龙。\n钦想还谯赋，缅怀天日容。\n地秘非天发，安能为人钟。\n改寺报慈德，谨护列崇墉。\n沦没几百载，所遗惟巨钟。\n后当景泰末，移置荐福东。\n千牛不可载，百室或启凶。\n嗟此亦神物，似与守灵踪。\n迹灭不能见，大约闻老农。\n但与看气色，巍巍冠秦雍。",""],["南原双白杨，直上数千尺。\n彷佛齐彭山，不为后上扼。\n山房当其阴，潇洒殊曩昔。\n置酒劝君饮，慷慨尽三石。\n岁月不肯留，人生岂常适。\n试问华冈子，谁见王维宅。",""],["我从华山归，刈麦已大半。\n自长安迤东，实美如火炭。\n繄我返耕来，此麦才再见。\n接岁禾不登，宝玉咸所贱。\n周人重农食，特分田畯职。\n公私积蓄繁，讵有旱干棘。\n春首饿莩多，朝廷甚忧恤。\n今日得佳物，守护须谨饬。\n黄金殪米下，其语殊谠直。\n作诗告有位，国宝在稼穑。","我从华山归，刈麦已大半。\n自长安迤东，实美如火炭。\n繄我返耕来，此麦才再见。\n接岁禾不登，宝玉咸所贱。\n周人重农食，特分田畯职。\n公私积蓄繁，讵有旱乾棘。\n春首饿莩多，朝廷甚忧恤。\n今日得佳物，守护须谨饬。\n黄金殪米下，其语殊谠直。\n作诗告有位，国宝在稼穑。"],["生儿望长成，儿长吾已老。\n自谓百事足，讵知夭横早。\n儿童搜故书，颇获见遗稿。\n文思顾葳?，曲折未探讨。\n岂羡长吉名，仍并郦炎好。\n造物忌瑰奇，成性返灵灏。\n一读既一悲，千读则千懊。\n倘假十年龄，尚齐圣哲造。\n元理杳莫测，吾欲问穹昊。",""],["儿气甚宏达，少有丈夫容。\n博识物岂眩，逸思若风从。\n俯仰鲜中诎，奋迅有孤踪。\n苟能假天命，郁为今词宗。\n顾我忝明德，神理夺所钟。\n英物且凋丧，况云痴与庸。\n岂无子夏戚，尚虞用昭凶。\n绪馀今似君，烦将附秦雍。",""],["太微神仙人，佳思逐云上。\n挥洒乾坤珍，飘飖出尘鞅。\n游宦建章宫，才名借方仰。\n萋斐反南山，闭门却交往。\n我东游华峰，每过时临访。\n麾麈话羲皇，拂剑悲魍魉。\n或诣少微原，歌啸历苍莽。\n倚坐看云生，策杖听泉响。\n遐烛远不隔，幽抱近弥想。\n以兹酬宿心，晨夕共欢赏。\n别来忽五月，予衰殊非曩。\n百忧结我肠，许过约恒爽。\n梦寐时见之，太息诮欺罔。\n新霁起微凉，何不谢纷攘。","太微神仙人，佳思逐云上。\n挥洒乾坤珍，飘飖出尘鞅。\n游宦建章宫，才名藉方仰。\n萋斐反南山，闭门却交往。\n我东游华峰，每过时临访。\n麾麈话羲皇，拂剑悲魍魉。\n或诣少微原，歌啸历苍莽。\n倚坐看云生，策杖听泉响。\n遐烛远不隔，幽抱近弥想。\n以兹酬宿心，晨夕共欢赏。\n别来忽五月，予衰殊非曩。\n百忧结我肠，许过约恒爽。\n梦寐时见之，太息诮欺罔。\n新霁起微凉，何不谢纷攘。"],["昔遇王子乔，谓君有仙骨。\n遨游三岛中，万里一超忽。\n朝餐石门霞，莫吸海陵月。\n朱颜浥瑶辉，长乐安可歇。\n天上降元鹤，白日升玉阙。\n懒答麻姑书，况肯事干谒。\n我虽不适意，逢君欲飞越。",""],["忆昔己卯春，曾与泾野约。\n因访岐东君，于兹共行乐。\n登山瞷岐雍，临池事澡瀹。\n子时多杂人，秽气远相搏。\n微憩古祠下，魂魄苦销铄。\n斜阳且衔山，亟去步未却。\n黾勉宿横渠，是意竟荒落。\n弃置至壬午，来自郿东郭。\n赖有王李曹，先驱为充拓。\n泉水煖且莹，一汤百疴掠。\n始信灵物佳，翻嫌表章略。\n今此复临池，神思益恢扩。\n莹彻一如昔，清净宛非昨。\n形畅意转新，神适喜如跃。\n嗟哉华清宫，安能与之若。\n作诗告后来，此地不可薄。","忆昔己卯春，曾与泾野约。\n因访岐东君，于兹共行乐。\n登山瞷岐雍，临池事澡瀹。\n子时多杂人，秽气远相搏。\n微憩古祠下，魂魄苦销铄。\n斜阳且衔山，亟去步未却。\n黾勉宿横渠，是意竟荒落。\n弃置至壬午，来自郿东郭。\n赖有王李曹，先驱为充拓。\n泉水煖且瑩，一汤百疴掠。\n始信灵物佳，翻嫌表章略。\n今此复临池，神思益恢扩。\n瑩彻一如昔，清净宛非昨。\n形畅意转新，神适喜如跃。\n嗟哉华清宫，安能与之若。\n作诗告后来，此地不可薄。"],["老境百虑息，所好在山林。\n况此洞室閟，尘氛安可侵。\n开帘见芳碧，迤逦闻鸟禽。\n因之感宿好，笑歌梁甫吟。\n丈夫志四海，何人识此心。\n所以夷与惠，旷世怀高襟。\n日夕凉风发，逸兴拂西岑。\n沽酒共斟酌，惭无丝竹音。\n扫石卧烟雾，听子广陵琴。",""],["山居二十年，未见蓬莱客。\n秋暮邂逅君，文彩甚彪赫。\n因读治安策，所拟吻不隔。\n西游遇中道，探囊出素册。\n琼瑰射人目，殊会杳今昔。\n再拜睹宸章，炳烁照光宅。\n叹君英妙时，丁此滂沛泽。\n宛如闻都俞，依稀见傅说。\n握手私谓君，丈夫志已获。\n尚宜践所陈，与世为表格。",""],["虚堂挂翠筠，玉涛满壁起。\n知君彻骨清，志意特欣此。\n兴剧须我题，予好亦若尔。\n回视桃李姿，秾芳胡足齿。",""],["昔逢华阳君，云为五帝使。\n检箓下九州，为予泄元秘。\n指点峨嵋傍，谓有仙人气。\n仙人尹之先，卓荦万夫贤。\n吐气成五色，为世鼓朱弦。\n绝调人莫知，徒见春江篇。\n予亦遁世者，闻之心洒然。\n恨不遂一见，相与定草元。\n天风自楚下，吹落岐周前。\n相见即相信，今岁成罕焉。\n款洽苦不久，俄赴天子宣。\n饯酒荜门下，逸兴浩难传。",""],["积雨晦皋陆，我车不可前。\n徘徊望北墅，迤逦横云烟。\n退坐草堂下，篱菊灿且妍。\n节物忽将改，引杯吟太元。\n微醉体亦倦，梦谒九华天。\n仙人中麓子，揖予出素编。\n云是广成撰，孰能叩其筌。\n忆昔魏伯阳，谓我骨当仙。\n苦逐世人好，落魄武亭川。\n缘业殆将满，数命或有然。\n始思饮刀圭，却老觅长年。\n语既执我手，欢笑极周旋。\n振袖出两药，光如朝日鲜。\n挹彼松露下，同吞各一圆。\n五内倏清爽，神采非昔焉。\n我居太白下，君庐太山颠。\n采芝拾瑶草，餐玉茹井莲。\n欲会但瞬息，跨鹤何翩翩。\n赤松作参伍，玉女侍几筵。\n翛然万物表，世网安可牵。",""],["早发潼关道，微风动林木。\n长峡百里去，我行正仆仆。\n大风变顷刻，万里惨以逐。\n树杪闻过沙，何须问平陆。\n我口不可开，我身只匍匐。\n挽车两少年，行行亦长哭。\n云是阌乡人，先世有官禄。\n县官急边粮，十户九逃伏。\n里长利赂钱，我故苦独速。\n太平作男儿，庸调天亦福。\n所恨身不长，筋力易羸蹙。\n母寡已十年，萧条但空椟。\n有田不得耕，有事在忽倏。\n近岁严转输，使者日三复。\n迢迢百里途，如历经纬轴。\n我喉亢如火，我行迅如䎘。\n吏来督我行，跃马恨不骛。\n使者讨押钱，鞭挞褫我服。\n我冤向孰陈，我泪向天瀑。\n语终心益伤，声吞色犹恧。\n我感少年语，涕泪泫如漉。\n皇明百年来，万姓各安育。\n草木亦有滋，少年尔曷蹙。\n匈奴二三载，骄气如鹯鹔。\n主将小儿行，焉能办𬭤镞。\n尔居见尔难，不见九边族。\n一夫八人管，剥削尽膏肉。\n往者禁军出，人家无完畜。\n膂力代出役，瘁敝内供谷。\n土炕亦见夺，何况妻与仆。\n此本亡赖子，亡命入军牍。\n三帅皆诡随，安知有钤束。\n少年尔莫苦，主上正恭穆。\n行当致雍熙，边庭永安肃。\n尔身当不劳，尔家亦永复。\n少年感我言，再拜向天祝。\n愿主万年寿，保我有𫗴粥。\n愿民如春草，长养无践㱩。\n挽车向西去，气色犹睦睦。","早发潼关道，微风动林木。\n长峡百里去，我行正仆仆。\n大风变顷刻，万里惨以逐。\n树杪闻过沙，何须问平陆。\n我口不可开，我身只匍匐。\n挽车两少年，行行亦长哭。\n云是阌乡人，先世有官禄。\n县官急边粮，十户九逃伏。\n里长利赂钱，我故苦独速。\n太平作男儿，庸调天亦福。\n所恨身不长，筋力易羸蹙。\n母寡已十年，萧条但空椟。\n有田不得耕，有事在忽倏。\n近岁严转输，使者日三复。\n迢迢百里途，如历经纬轴。\n我喉亢如火，我行迅如䎘。\n吏来督我行，跃马恨不骛。\n使者讨押钱，鞭挞褫我服。\n我冤向孰陈，我泪向天瀑。\n语终心益伤，声吞色犹恧。\n我感少年语，涕泪泫如漉。\n皇明百年来，万姓各安育。\n草木亦有滋，少年尔曷蹙。\n匈奴二三载，骄气如鹯鹔。\n主将小儿行，焉能办鍭镞。\n尔居见尔难，不见九边族。\n一夫八人管，剥削尽膏肉。\n往者禁军出，人家无完畜。\n膂力代出役，瘁敝内供谷。\n土炕亦见夺，何况妻与仆。\n此本亡赖子，亡命入军牍。\n三帅皆诡随，安知有钤束。\n少年尔莫苦，主上正恭穆。\n行当致雍熙，边庭永安肃。\n尔身当不劳，尔家亦永复。\n少年感我言，再拜向天祝。\n愿主万年寿，保我有饘粥。\n愿民如春草，长养无践殰。\n挽车向西去，气色犹睦睦。"],["白日西南驰，人生直如寄。\n芳林春风发，百物畅以萃。\n君心谐金石，良晤成斯醉。\n于焉弥欢洽，倏忽老将至。\n孔跖今安存，何须辨真伪。","白日西南驰，人生直如寄。\n芳林春风发，百物畅以萃。\n君心谐金石，良晤成斯醉。\n于焉弥欢洽，倏忽老将至。\n孔蹠今安存，何须辨真伪。"],["忆昔与君别，悠忽今十年。\n不能见颜色，徒存秋夕篇。\n展玩泪沾臆，相思隔万川。\n男儿奋迅虽有时，叹息君才诚绝弦。\n竖儒仅能诵章句，腾踏青云凌钜贤。\n珍味安能通俗口，广陵之散谁可传。\n罕山金可卿，三原马溪田。\n徒使高名贯星斗，科场不售惟我怜。\n昔也令人羡三凤，今我孤骞情惘然。\n相如既有凌云赋，讵待吹嘘方上天。",""],["庚申长安一见君，知君气盖千人军。\n正德八年定蜀贼，延绥健儿如虎奔。\n此时天子方西顾，名公才将如云屯。\n君从制帅适经过，老眼拂拭知有人。\n果然三月破绵汉，遂令巴蜀无风尘。\n向也王师亦尝奋，山东河北根株尽。\n岂系将军纪律疏，由来战士骁腾靳。\n扫荡宁夸廖贼收，笑谈直羡终郎俊。\n渭水秦山壮气回，金台恒岳益崔嵬。\n相逢意气还如昔，愧尔经邦济世才。",""],["长安道上秋风起，吹入青门草靡靡。\n客子携琴燕赵来，一感秋风心欲死。\n鸣鞭跃马过我前，那堪杯酒重留连。\n酒酣气发百志奋，谈笑须臾空百年。\n坐中叹尔壮士心，人事何劳问古今。\n张仓亦能论刑法，君平徒然卜六壬。\n仲尼治国苦不称，曾参事母犹难信。\n时势摧人著处生，英雄遇抑常迟钝。\n南山磊磊云气横，寒泉湔湔终日鸣。\n请君拂袖谢人世，与尔常为谷口耕。",""],["十日一晴晴复阴，斜风细雨何浸淫。\n山根泥滑寸薪苦，水面苔生平地深。\n神怒天摧或如此，已看百谷半将死。\n饥寒盗贼著处生，诛斩翻忧乱兵起。\n征求无度民自难，诸公徒尔叹微官。\n豺狼当道捕不得，三公列卿何足观。\n忽忆成化甲辰岁，公私充国纲维系。\n皇帝临轩发禁钱，细民尚作沟壑毙。\n况复艰难至此时，九重深严那得知。\n台谏徒陈利害策，闾阎不见宁息期。\n斗粟尺布命所直，吏促官输转相逼。\n甘肃纵横土鲁番，商洛纷纭织染给。\n中丞受诏不敢来，此地生灵一何极。\n呜呼斯民天所生，州县相看何太轻。\n祖宗宏业振千古，陛下神武复英明。\n一朝收取坏事者，会见尔曹双眼清。","十日一晴晴复阴，斜风细雨何浸淫。\n山根泥滑寸薪苦，水面苔生平地深。\n神怒天摧或如此，已看百谷半将死。\n饥寒盗贼著处生，诛斩翻忧乱兵起。\n徵求无度民自难，诸公徒尔叹微官。\n豺狼当道捕不得，三公列卿何足观。\n忽忆成化甲辰岁，公私充国纲维系。\n皇帝临轩发禁钱，细民尚作沟壑毙。\n况复艰难至此时，九重深严那得知。\n台谏徒陈利害策，闾阎不见宁息期。\n斗粟尺布命所直，吏促官输转相逼。\n甘肃纵横土鲁番，商洛纷纭织染给。\n中丞受诏不敢来，此地生灵一何极。\n呜呼斯民天所生，州县相看何太轻。\n祖宗宏业振千古，陛下神武复英明。\n一朝收取坏事者，会见尔曹双眼清。"],["忆昔与子游乡学，短褐彯彯俱总角。\n千人过眼无一堪，私拟君才当颖脱。\n以兹常听万里鸣，岂意萧条饭场藿。\n我昔应时官翰林，世间名士空相博。\n转觉君才近所无，垂老科场意羞缩。\n奋迅因求勾漏闲，声华晔晔今非昨。\n苟能行事何足猜，丈夫要见青天阔。\n国家名公不可数，俱向专城事民瘼。\n君不见汉庭黄霸与鲁恭，至今名誉振天地，何况当时为列公。","忆昔与子游乡学，短褐彯彯俱总角。\n千人过眼无一堪，私拟君才当颖脱。\n以兹常听万里鸣，岂意萧条饭场藿。\n我昔应时官翰林，世间名士空相博。\n转觉君才近所无，垂老科场意羞缩。\n奋迅因求勾漏閒，声华晔晔今非昨。\n苟能行事何足猜，丈夫要见青天阔。\n国家名公不可数，俱向专城事民瘼。\n君不见汉庭黄霸与鲁恭，至今名誉振天地，何况当时为列公。"],["黄金台上云依依，黄金台下水沵沵。\n臣今万里去，辛苦安可辞。\n但愿陛下寿万岁，使臣万里无遗思。\n祖宗洪业际天地，尺地皆土，人咸臣之。\n斩刈流徙，惟上所为。\n遐方炎炎，有肉不可食，有酒不可卮。\n况臣侍从迩文墀。\n心之彷徨岂在此，惟愿陛下有长期。\n陛下神圣古帝少，臣心不为遐方老。",""],["瑞州太守邝廷瑞，瑞至之日贼乃鸷。\n手无寸铁兵卫空，健儿闻惊皆逃避。\n郡吏不敢更趋承，苦谏当虞身后事。\n四境安危系此身，太守一逃何以徇。\n当衙一呼士争奋，始信英雄气有神。\n贼兵星散城已保，转顾因知寇所巧。\n樊破毁栅敛近民，贼失所资如逝鸟。\n至今瑞郡立生祠，君与刘周如在兹。\n丈夫寻常薄钟鼎，毁誉升沉何足疑。\n嗟嗟贝锦者谁子，谤君翻使君名起。\n盖棺事定古所传，才去几时民若此。\n天道恢恢监独明，区区庶子胡为尔。",""],["忆昔正统天顺间，渭南薛丈同先子。\n关内通称夫子名，二老实为天下士。\n以此通家数十年，善行嘉言时在耳。\n后嗣全如兄弟亲，前修自笃谦恭礼。\n往岁逢君巴蜀归，厚意遥遥还若此。\n愧我疏慵未敢当，闻君谈论心私喜。\n盛世自宜英迈人，迂儒岂识经纶理。\n萧望难居侍从官，贾生肯与绛灌比。\n司马逍遥忽见疑，谁知中道生萋斐。\n治郡无能返异才，看花尚切群公齿。\n丘壑徒深社稷忧，庙堂独忍乾坤否。\n春暮闲游少华峰，逢迎幸辱贤乔梓。\n握手那知感慨生，酣歌不觉希声起。\n君臣之义君莫忘，还期三月下和阳。\n用舍自为大臣事，显晦岂为吾道妨。\n君不见昆仑黄河天上来，银涛雪浪如山摧。\n不遗涓滴尽入海，谁谓海门开不开。","忆昔正统天顺间，渭南薛丈同先子。\n关内通称夫子名，二老实为天下士。\n以此通家数十年，善行嘉言时在耳。\n后嗣全如兄弟亲，前修自笃谦恭礼。\n往岁逢君巴蜀归，厚意遥遥还若此。\n愧我疏慵未敢当，闻君谈论心私喜。\n盛世自宜英迈人，迂儒岂识经纶理。\n萧望难居侍从官，贾生肯与绛灌比。\n司马逍遥忽见疑，谁知中道生萋斐。\n治郡无能返异才，看花尚切群公齿。\n丘壑徒深社稷忧，庙堂独忍乾坤否。\n春暮閒游少华峰，逢迎幸辱贤乔梓。\n握手那知感慨生，酣歌不觉希声起。\n君臣之义君莫忘，还期三月下和阳。\n用舍自为大臣事，显晦岂为吾道妨。\n君不见昆崙黄河天上来，银涛雪浪如山摧。\n不遗涓滴尽入海，谁谓海门开不开。"],["苍云烂，白日长。\n并辔游，辞曲房。\n君去不来我心伤。\n山寂寂，阒无侣，愁检故诗历孤屿。\n孤屿亭亭当大河，下有万尺之洪波。\n洪波万尺有时尽，此意悠悠君若何。",""],["夹河战，事已亟。\n张御幄，虎来逼。\n将军怒目射虎死，来日沙场身且殪。\n元身之说古亦有，将军之射乃其守。\n可使身后殪，毋使虎前走。\n君不见军中壮士空千万，仓卒虎至无人见。\n眼底不知报主恩，何况明朝夹河战。",""],["吾宗有孙子，玉质光嶙峋。\n总好纸墨事，敏捷如有神。\n温克过诸父，私为予所珍。\n缉学绿野忘寒暑，奋志直欲追先民。\n大美不竟乃夭折，使我痛哭闻者辛。\n汝死不复作，我哀谁可陈。\n少年弱冠随鬼录，爷娘兄弟哭声直上干清旻。\n埋玉于土几时出，荒郊日落惟孤坟。\n孤坟三尺生秋草，愁杀东西南北人。",""],["去年秋雨苦淋沥，今年淋沥更无敌。\n自从初一涨潦河，至于初七声逾激。\n浸淫若遣太华崩，轰豗岂但平川汩。\n百谷腐烂莎草长，惟有芙蓉水中直。",""],["崩墙坏壁人夜号，比邻处处通波涛。\n明灯执伞待天曙，片云浮来声益号。\n富家或能饱鸡黍，嗟嗟奈此贫儿曹。\n拽椽为薪曲为粥，斗粟千钱肯相鬻。",""],["原上官道泥已深，原下卑湿人怎禁。\n四方极目尽明水，野菜可餐何处寻。\n绹涂匍匐寡筋力，宾客逢迎甚胸臆。\n安得大禹凿九州，更使苍生免昏匿。",""],["此雨初晴人亦狂，为能洗却烦蒸凉。\n那知狼藉遂如此，积阴郁郁行坐妨。\n儿童阶下戏舟楫，风动樯帆行猎猎。\n不知何日坠莲房，乱向波心逐莲叶。",""],["戊辰与子别京国，一别十年如顷刻。\n野人心性百事慵，尺书未入扬雄宅。\n丈夫豪气九鼎轻，六品微官有何得。\n吾子风流近代稀，新诗首首追曹植。\n鹏飞凤翥变化殊，龙舞蛟腾果安极。\n有怀欲语谁可知，寻常思汝心如塞。\n山东李梦弼，河间李宗易。\n人来往往寄我书，兼有篇诗如络绎。\n民怀昨日信亦至，独怪尔锡非曩昔。\n直卿山西消息无，粹夫河内声尤赫。\n数君才名先后无，义气上与云霄浮。\n愧我龌龊只饮酒，未能彷佛身后图。\n前日客从浒西过，历诵诸君有程课。\n此意萧条久不闻，私心岂但同年贺。\n廊庙山林各有怀，好景不常时易蹉。\n愿君努力思古人，人生当作万年身。\n有才上可报明主，坐令四海承经纶。\n浒西山水亦非恶，断壁悬崖何磊落。\n终南太白走其下，清渭汧𣲗面相错。\n秋来朝夕云气横，乔木森森鸣鸟雀。\n中情泮奂何所撄，旧日粗豪心渐薄。\n或向西河学钓鱼，或向东原访隐居。\n割鸡饮如壑，跣足蓬头奚愧怍。\n譬如野鹜山鸡被樊絷。\n一朝脱翅向空山，玉柱金甍肯轻集。\n达亦无所欢，穷亦无所苦。\n我曹心事久不白，秃颖安能为君数。\n去年二月经紫阁，怪石惊湍陋天姥。\n其下一里秦草堂，古人题咏横如堵。\n此时思欲与君游，击筑徜徉歌石鼓。\n或时策杖瀑布间，或时坐远临高岵。\n此意寥寥不复同，因君叹息泪如雨。","戊辰与子别京国，一别十年如顷刻。\n野人心性百事慵，尺书未入扬雄宅。\n丈夫豪气九鼎轻，六品微官有何得。\n吾子风流近代稀，新诗首首追曹植。\n鹏飞凤翥变化殊，龙舞蛟腾果安极。\n有怀欲语谁可知，寻常思汝心如塞。\n山东李梦弼，河间李宗易。\n人来往往寄我书，兼有篇诗如络绎。\n民怀昨日信亦至，独怪尔锡非曩昔。\n直卿山西消息无，粹夫河内声尤赫。\n数君才名先后无，义气上与云霄浮。\n愧我龌龊只饮酒，未能彷佛身后图。\n前日客从浒西过，历诵诸君有程课。\n此意萧条久不闻，私心岂但同年贺。\n廊庙山林各有怀，好景不常时易蹉。\n愿君努力思古人，人生当作万年身。\n有才上可报明主，坐令四海承经纶。\n浒西山水亦非恶，断壁悬崖何磊落。\n终南太白走其下，清渭汧湋面相错。\n秋来朝夕云气横，乔木森森鸣鸟雀。\n中情泮奂何所撄，旧日粗豪心渐薄。\n或向西河学钓鱼，或向东原访隐居。\n割鸡饮如壑，跣足蓬头奚愧怍。\n譬如野鹜山鸡被樊絷。\n一朝脱翅向空山，玉柱金甍肯轻集。\n达亦无所欢，穷亦无所苦。\n我曹心事久不白，秃颖安能为君数。\n去年二月经紫阁，怪石惊湍陋天姥。\n其下一里秦草堂，古人题咏横如堵。\n此时思欲与君游，击筑徜徉歌石鼓。\n或时策杖瀑布间，或时坐远临高岵。\n此意寥寥不复同，因君叹息泪如雨。"],["武功节妇李锐妻，节操直与青天齐。\n夫子舅姑苦欲嫁，不从见逐何所栖。\n阿舅宦去卖田亩，妻孥俱作燕台走。\n悲号陨绝夫冢边，血泪如波心欲剖。\n遗息在抱求死难，欲守夫家岂能守。\n吞声自赁宗人居，夜纺绩织苟糊口。\n辛勤匍匐二十载，息儿成长为人妇。\n三十年馀舅死官，姑来置屋比旧宽。\n小叔家口自逼仄，岂容老妪供姑餐。\n纪侯去国纪季在，叔姬故与酅宗对。\n先后不免舅姑嗔，立锥无地肠空碎。\n小叔近又卖新屋，西入汧阳不东复。\n身计萧条兄弟疏，安得不就寡女宿。\n庶民自与邦君殊，贫人赁僦何弗居。\n南里豸史苦执礼，岂未尽谙胡氏书。\n庄公元年纪已拔，宗庙所系情难恝。\n三年遣季存馀酅，吾君既死身安极。\n所以归酅死宗庙，谓酅如纪心所悼。\n秦人鲜义自古然，父子尚有耰锄较。\n寻常岂异不顾亲，区区嫠妇尔何人。",""],["姑未老，夫已亡，事姑惟恐姑心伤。\n妾幸不死得事姑，姑病经年惟妾扶。\n但得姑好妾常侍，那惜此身成骨枯。\n可怜阿母死时语，愿汝有妇还似汝。\n不见贤郎丧汝时，三载居庐不出户。",""],["养雏自恨羽翼短，翼长飞去岂思返。\n老乌目断东南枝，白日青天一何远。\n尾秃唇焦徒自啼，啼杀老乌雏讵知。\n愿雏养雏还胜雏，慎勿龌龊如老乌。",""],["昨日有雨尘不洒，今日雨多云更长。\n遥天四望无寸碧，野人稼穑何所妨。\n顷闻江淮人相食，父子不保况路傍。\n关中虽无横盗苦，边饷转输日相望。\n麦豆半为风雨蚀，我秋未布人皇皇。\n晨兴东出望云气，晴天赤日心自伤。\n千叹万息日将昃，天风不动帘影黑。\n须臾雨脚下平地，豗喧何啻万马力。\n向夕虽看悬溜微，达旦霏霏雨如织。\n喜闻优渥遍九土，倏忽之间信难测。\n天地之德本好生，大块岂厌物生成。\n人身痞逆百体滞，气运所生谁可明。\n丰年弗俭歉时极，却与造化生搀枪。\n安得官长息杂役，令此黔首俱深耕。\n禁侈薄敛久自足，何必义仓与长平。",""],["西溪草堂春水深，西溪主人溪上吟。\n割鸡把酒劝客醉，少小几时衰老侵。\n朱颜白日休自负，请君试看芳春林。\n我闻此语倍感激，世上几人如此心。\n明朝何不出美酒，更与东眺华山岑。",""],["为学不努力，瞬息弃前功。\n老夫衰境倦筋骨，安能久坐空庭中。\n徘徊不见朗诵人，迤逦岂羞长跪同。\n昨日街头黄发儿，今已倏忽成老翁。\n谆谆念汝理不达，切切宁为虞困穷。\n此心逐物返自易，勉哉莫作长匆匆。",""],["何日到吾家，牡丹应著花。\n开图一见兴已发，遥似当年宴紫霞。\n雕栏不受春风抑，绿叶红蕤舞风力。\n终日回旋不肯休，根株苦被丹青匿。\n远路邅洄销客心，梦魂惟在草堂阴。\n牡丹牡丹吾语汝，三月八日始谷雨。",""],["客向华山去，过宿长安坊。\n明日复延伫，大醉使君堂。\n使君之父松鹤翁，银髯雪鬓来从容。\n见我更取大斗出，一饮已倾三百钟。\n匆匆数语见胸次，四座通看独神异。\n此翁本是天上人，世间图画空相似。\n徂徕之松千尺长，终日纷纷云气翔。\n南极老人跨鹤至，其下可许寻常当。\n翁言明日是初度，满庭宾客如烟雾。\n使君自喜春日长，天际谁知有仙婺。\n灵药闪烁堆玉盘，持以赠翁翁自看。\n一粒便可八千岁，几度笑观沧海干。\n我执翁手为翁语，世上如翁几人许。\n生儿不忝杜与房，举手争看乔共梓。\n群仙今日上翁堂，何以赠之云锦章。\n彩衣先见二千石，使翁姓字千载香。","客向华山去，过宿长安坊。\n明日复延伫，大醉使君堂。\n使君之父松鹤翁，银髯雪鬓来从容。\n见我更取大斗出，一饮已倾三百钟。\n匆匆数语见胸次，四座通看独神异。\n此翁本是天上人，世间图画空相似。\n徂徕之松千尺长，终日纷纷云气翔。\n南极老人跨鹤至，其下可许寻常当。\n翁言明日是初度，满庭宾客如烟雾。\n使君自喜春日长，天际谁知有仙婺。\n灵药闪烁堆玉盘，持以赠翁翁自看。\n一粒便可八千岁，几度笑观沧海乾。\n我执翁手为翁语，世上如翁几人许。\n生儿不忝杜与房，举手争看乔共梓。\n群仙今日上翁堂，何以赠之云锦章。\n綵衣先见二千石，使翁姓字千载香。"],["春阳迟迟仓庚鸣，我公东归旌旆扬。\n蒸黎连络啼路傍，慈母欲去安所望。\n搴帷扳驾心皇皇，行道之人咸感伤。\n繄自我公来抚堂，吏就典列民用襄。\n剂量绅缩心百方，拯救提挈如被戗。\n使者冠盖徒相仍，固闭不得为民殃。\n文移反复千万箱，借措却恼司空郎。\n公身虽去德在民，公德在民民忍忘。\n掇拾民意述此章，惟公保爱履嘉祥。\n华山高高摩穹苍，大河逶迤接扶桑。\n西土令闻同穹长，秦民世世赖休光。\n天子仁圣思股肱，公当不久还岩廊。\n公德旁布四海康，千秋万岁永寿昌。","春阳迟迟仓庚鸣，我公东归旌旆扬。\n蒸黎连络啼路傍，慈母欲去安所望。\n搴帷扳驾心皇皇，行道之人咸感伤。\n繄自我公来抚堂，吏就典列民用襄。\n剂量绅缩心百方，拯救提挈如被戗。\n使者冠盖徒相仍，固闭不得为民殃。\n文移反覆千万箱，借措却恼司空郎。\n公身虽去德在民，公德在民民忍忘。\n掇拾民意述此章，惟公保爱履嘉祥。\n华山高高摩穹苍，大河逶迤接扶桑。\n西土令闻同穹长，秦民世世赖休光。\n天子仁圣思股肱，公当不久还岩廊。\n公德旁布四海康，千秋万岁永寿昌。"],["我非汉阴叟，灌园𣲗水东。\n处世本无机巧心，胡为桔槔悬此中。\n园丁再拜向我语，此意千古谁可通。\n舟车亦是古帝作，胡不辞去存古风。\n言者自有托，读者自无穷。\n坂泉之战至今诵，安用区区矢与弓。","我非汉阴叟，灌园湋水东。\n处世本无机巧心，胡为桔槔悬此中。\n园丁再拜向我语，此意千古谁可通。\n舟车亦是古帝作，胡不辞去存古风。\n言者自有托，读者自无穷。\n坂泉之战至今诵，安用区区矢与弓。"],["常作华山游，遂为华山客。\n爱君小楼当华山，日日开帘玩山色。\n偶逢方平跨鹤来，握手而语若有得。\n便欲同君炼九霞，勿使红颜坐销歇。","常作华山游，遂为华山客。\n爱君小楼当华山，日日开帘玩山色。\n偶逢方平跨鹤来，握手而语若有得。\n便欲同君鍊九霞，勿使红颜坐销歇。"],["自别河阳驿，于今二十年。\n轰豗忧正急，倾覆意常悬。\n共济欢无极，同归事可怜。\n此时俱尚老，语及欲潸然。",""],["长安相饯后，倏忽又秋风。\n伏枕浑三月，征医赖两公。\n世人憎贾傅，予意得王充。\n努力趣吾道，乾坤若转蓬。","长安相饯后，倏忽又秋风。\n伏枕浑三月，徵医赖两公。\n世人憎贾傅，予意得王充。\n努力趣吾道，乾坤若转蓬。"],["吾道仍须酒，秋分酿更宜。\n便当炊百石，犹未足千卮。\n行乐年空暮，闻歌日尚迟。\n风流杜陵老，倾倒是吾师。",""],["太微清苦士，弱冠即知名。\n英气千人废，新诗四座惊。\n爱身辞一芥，当士陋诸生。\n可惜龙光剑，悠悠闭斗城。",""],["抱病卧林壑，思君安可亲。\n忽蒙枉书札，便已惬心神。\n曲艺竟何益，虚名常愧人。\n沜东有垂柳，堪送百年身。",""],["二月高陵县，逢君发庆阳。\n十年方邂逅，百岁几徜徉。\n词赋名须久，安危望已长。\n青尊今夜月，好醉浒西堂。",""],["返耕得兹麓，习静欲长年。\n山水向春碧，烟霞当暮妍。\n结庐垂四壁，枉驾辱诸贤。\n遣兴沽村酒，呼童鸣绿弦。",""],["长空云气静，今夜月偏明。\n且喜高人至，犹怜湛露生。\n金波摇桂影，彩凤落瑶笙。\n潇洒王夫子，飘飘共此情。",""],["尔爱文章事，应知著力难。\n涵容须有日，操纵亦多端。\n大义如分烛，圆机自跃丸。\n果能追古作，先向老夫看。",""],["繄自辞京邑，遥遥十六年。\n婚姻谢儿女，游眺历山川。\n总谓终聊尔，谁知事偶然。\n忧来唯洒泪，魂逐夜台边。",""],["愁里窥明镜，惊看白发多。\n行年自驱迫，服食谩如何。\n有相终岩穴，无机任薜萝。\n平生忧国志，何惜酒中过。",""],["不到幽栖处，悠悠将十春。\n古堂悬见日，静地寂无尘。\n俎豆思周礼，威仪忆鲁苹。\n愧非程伯子，何以坐松筠。","不到幽栖处，悠悠将十春。\n古堂悬见日，静地寂无尘。\n俎豆思周礼，威仪忆鲁蘋。\n愧非程伯子，何以坐松筠。"],["独好中林隐，因家清渭川。\n园开溪尽处，山合水西边。\n曲艺明时弃，长歌稚子传。\n已深疏旷志，不是欲游仙。",""],["出郭望精舍，满墙皆杏花。\n香风当户合，艳影入林斜。\n日煖烟生玉，春晴锦映霞。\n兴来呼酒坐，不必问年华。",""],["寂寞高陵县，慇勤怀大防。\n义于昆弟切，情视范张长。\n累辱驰音问，聊能达报章。\n总令瞻第宅，那复共徜徉。",""],["吾亦爱沧洲，春风信所游。\n不须歌桂棹，浑胜坐兰舟。\n浊浪排风起，轻帆及岸收。\n稍东瞻太华，遥在碧云头。",""],["水部风流古，云亡亦有年。\n重来因问讯，孤坐思凄然。\n孙子犹儒服，门墙托市廛。\n向时豪爽论，谁为世人传。",""],["官舍草初青，君应坐小亭。\n谩吟谁共续，高论我常听。\n莫叹冯唐老，终期阮籍醒。\n由来丈夫志，唾手出青冥。",""],["自出华山道，时时怀此翁。\n名园春定好，佳节远谁同。\n社稷思君实，文章略季通。\n望中欢喜极，若坐小楼东。",""],["鹿苑何王殿，明时尚赐秦。\n芳林春碍日，幽草昼眠麇。\n畎亩馀生计，乾坤信此身。\n西京谁欲赋，韦曲有词人。",""],["小殿俯芳林，丹台挹翠岑。\n重来多好兴，孤眺惬春心。\n时序关华发，丘园受短吟。\n如何韩吏部，已放二毛侵。",""],["客谢酆桥道，逶迤紫阁阴。\n云霞馀夕照，花柳暗春林。\n灯火城中出，星河望里沉。\n不知王逸少，何处赏偏深。",""],["方作城南别，重为鄠杜逢。\n岂期尘雾里，今日见人龙。\n邂逅非无意，酕醄谅可从。\n明朝予北去，何处望仙踪。",""],["水北君归隐，匆匆十五年。\n我来重极目，疑似岳阳川。\n楼阁参差里，亭台杳霭边。\n鸟声听不尽，花底有鸣弦。",""],["二曲交游客，如君信不多。\n几时违笑语，荒冢已烟萝。\n却望题诗处，其如洒泪何。\n谩看忧乐事，千古一南柯。",""],["复从车马去，何以遂襟期。\n始信山林趣，全归燕暇时。\n霁云随望薄，流曜落秋迟。\n不及东岩子，常衔浊酒卮。",""],["再过此亭下，森疏真可人。\n樊墙俱胜昔，花柳忽如春。\n总得林间趣，偏宜物外身。\n修篁轩后出，何啻万竿新。","再过此亭下，森疏真可人。\n樊墙俱胜昔，花柳忽如春。\n总得林间趣，偏宜物外身。\n脩篁轩后出，何啻万竿新。"],["回首双流细，森疏万木长。\n绕溪蒲粉落，夹路稻花香。\n所向皆殊绝，平看却渺茫。\n几时同鄠叟，伐竹构茆堂。",""],["一自京华别，悠悠十七年。\n形容常入梦，笑语竟无缘。\n岂忆穷冬日，相逢华岳前。\n无能共杯酒，相对益凄然。",""],["诣华情空切，相过意已深。\n那知百年里，又此一沾襟。\n儿女方粗了，存亡忽见寻。\n吾生何日定，对酒若为心。",""],["不见平田子，匆匆已二年。\n再聆绝交论，应笑养生篇。\n晴日园花细，春风榭柳悬。\n不知游乐处，谁是竹林贤。",""],["多君省春野，逢我遇仙宫。\n共宿临川寺，徘徊及夜中。\n弦歌兴汉邑，恭俭即邠风。\n更听忧时论，何惭底柱功。",""],["不到幽人舍，匆匆又五年。\n槛花交砌密，园果出墙悬。\n夹路皆清荫，当阶过碧泉。\n微风沾客坐，吟望兴翛然。",""],["羡君天下士，犹恋碧山游。\n盛世须英物，明珠肯暗投。\n秋风桑柘里，晴日凤凰楼。\n语及箕裘事，生儿已食牛。",""],["汝向名园去，佳游兴若何。\n柳溪须对月，花坞且停歌。\n不寐杯空泻，微吟思转多。\n老来心数仄，徙倚立庭柯。",""],["客滞燕台久，春深始到家。\n异乡惊见汝，归思渺无涯。\n但酌弘农酒，休言杜曲花。\n我来应首夏，知剩几枝斜。",""],["扫地坐芳草，阑斑如锦茵。\n况有青莲幕，偏宜乌角巾。\n经纶辞壮志，萋斐得间身。\n不作酕醄饮，桃花亦笑人。",""],["山雨幸初霁，微风犹峭寒。\n峰高常带雪，湍杀不成澜。\n野鹿含芝过，山鸡隔竹看。\n碧桃多半落，若可奈春残。",""],["拂雾寻山寺，篮舆上转轻。\n晓云生石细，旭日映岩明。\n梵磬遥空出，天花夹路迎。\n何须似摩诘，方是学无生。",""],["今日汧阳发，知当宿凤翔。\n中秋亦何幸，同子浥清光。\n𪩘外来旌节，云间下凤凰。\n白头疏旷久，徙倚望原冈。","今日汧阳发，知当宿凤翔。\n中秋亦何幸，同子浥清光。\n巘外来旌节，云间下凤凰。\n白头疏旷久，徙倚望原冈。"],["腊日暖如春，君归谒紫宸。\n一尊奉天酒，千古五陵人。\n剑佩勤边远，风云入梦新。\n明时逢圣主，令世浥清尘。",""],["近日观风使，贤郎独擅名。\n熊丸勤昔教，凤诰逖金声。\n八帙慈闱福，三时令子情。\n瑶池灵药下，可上百年荣。",""],["间气扶鸿化，昌时得钜儒。\n我师关辅彦，高义古今逾。\n执礼钦程伯，言文陋董狐。\n数奇场屋蹇，道在性情俱。\n未薄常州幕，何惭楚泽虞。\n居贫馀岂弟，望重极抠趋。\n桃李乘春遍，芝兰接岁殊。\n素心原不染，椟玉讵求沽。\n迟日明仙馆，灵光拂寿图。\n愿餐千载药，与世作规模。",""],["三春数枉故人书，去使虚无报德疏。\n幸有𬨎车堪问讯，谁能感事不踌蹰。\n西亭素壁愁经眼，此日安危切跂予。\n待得升平十年后，东冈休负草堂居。","三春数枉故人书，去使虚无报德疏。\n幸有輶车堪问讯，谁能感事不踌蹰。\n西亭素壁愁经眼，此日安危切跂予。\n待得升平十年后，东冈休负草堂居。"],["梓里逍遥又一年，风光何处不堪怜。\n鸣禽应谷声逾碎，露菊侵阶影自圆。\n无病有时看碧水，多情终日卧苍烟。\n斜阳牧笛从吾意，漉酒呼邻兴渺然。",""],["此日秋风绝可人，年时炎溽尚伤神。\n且看晓色清如洗，转觉寒光翠欲嚬。\n松下有时双鹤舞，溪边无数白鸥驯。\n便须酌酒酬心事，莫谩支吾愧此辰。",""],["故人清晨来叩庐，野人尚作深岩居。\n握手扫地坐相语，忆昔交游俱不如。\n情真唤妇馔鸡黍，道厚抚躬惭绪馀。\n多病寻常少筋力，感慨直欲凌空虚。",""],["昨日见月赏不及，今夜月来云亦开。\n已促新词翻楚调，却疑清影落阳台。\n冰轮果惬诗人意，玉椀当酬白雪才。\n新病欲瘳仍讳饮，不胜高兴谩含杯。",""],["谷口寻源入渐深，回峦相接昼阴阴。\n屿禽掠水应愁下，野鹤穿云太不禁。\n暝接草房烟漠漠，树当若岫绿森森。\n重游始得名山趣，老去翻惭少日心。",""],["养生无状病经旬，药裹缘君更有身。\n明日西归休恨别，他时相见却惊人。\n稽康徒作形神论，魏野终非翰墨臣。\n早晚南山云气发，请君天际望纶巾。",""],["山居久谢风云使，今日西堂为子开。\n三百同年谁更好，八千滇水几时来。\n循良作郡纾民力，落魄逢人爱酒杯。\n青镜霜髭吾亦老，骊歌汀柳不胜哀。",""],["江头横槊任群凶，过腊经春未息踪。\n秪以官输相逼迫，岂能比屋自从容。\n尚忧巴蜀仍多事，莫倚秦雍足利锋。\n闻道军衙更节镇，东方黎庶益汹汹。",""],["年来唯与白鸥群，春暮谁知两见君。\n幸有青尊须纵饮，况当明月更论文。\n山房迤逦浓花发，草阁迂回野径分。\n长句短吟俱大雅，朱轮华毂正浮云。",""],["不见清辉又隔年，人生能得几回圆。\n登楼漫落千山雨，忆第空瞻万里天。\n欲遣倦怀须贳酒，为酬佳节强登筵。\n亦知潦倒为吾事，烛影歌声入夜偏。",""],["忆昔承明侍从朝，先皇端拱似神尧。\n万家箫鼓传双阙，三殿风云护九韶。\n剑佩缓归青琐夕，蛮夷通款越裳遥。\n可怜湖上龙飞后，人事官曹渐寂寥。",""],["渭川草堂清渭滨，无数好花开暮春。\n小窗不受风雨逼，烂醉岂忧儿女嗔。\n数椽自可藉疏豁，百亩谁曾辞贱贫。\n凭君分我万竿竹，令我因以东卜邻。",""],["禅堂晨起惜清幽，野客西归兴不休。\n两妙过予应恨别，隔年同此足消忧。\n林花掩映香台落，旭景霏微宝殿浮。\n自古城南名胜地，何时极意遍追游。",""],["驼峰孤眺郁嵯峨，自觉西来乐事多。\n千折笑看洪水细，双岩不见白云过。\n周公礼乐空遗庙，谢傅风流有浩歌。\n太白南瞻真咫尺，关中佳气近如何。",""],["拂曙披云到此关，喜随綦履望名山。\n芙蓉半出青天外，沆瀣中分白石间。\n定有神功扶帝力，岂须灵药驻衰颜。\n攀蔂未觉寻行倦，细和新诗及暮还。",""],["使君爱客宴闲堂，客醉歌狂殊未央。\n自以笑言偕四俊，虚疑时序到重阳。\n炎天过雨先销暑，美酒当筵岂论觞。\n旦日东征更疏阔，赠予何惜远游章。","使君爱客宴閒堂，客醉歌狂殊未央。\n自以笑言偕四俊，虚疑时序到重阳。\n炎天过雨先销暑，美酒当筵岂论觞。\n旦日东征更疏阔，赠予何惜远游章。"],["群公相见亦忧时，事势推移却未知。\n岂有明王崇侈好，总缘中使辱恩私。\n典刑具在公平法，台谏何劳激烈辞。\n掎麈漫思忠献议，英雄当事盖如斯。",""],["空堂雷雨送微寒，爱汝萧萧竹万竿。\n安得云霄乘羽翼，一过台榭重游观。\n园英带湿皆凝碧，墙杮须秋始放丹。\n我已炎蒸愁作客，君应迤逦卜新欢。",""],["仙家楼观俯层岑，春色逶迤万木阴。\n槛外歌声初迤逦，寰中人事几销沉。\n谁将玉醴传金椀，自欲浮生憩此林。\n本是无心名利客，悔教华发到如今。",""],["危楼迥对一峰孤，哀壑平连万顷芜。\n摩诘画图空掩映，伯阳道德岂虚无。\n方西涧谷汉驰道，直北河山周故都。\n风土不殊人事异，谁将绵瓞问司徒。",""],["今日浒西开牡丹，携儿漉酒坐相看。\n秾花自识春风好，接叶休为夜雨残。\n深院紫泥巢翡翠，层楼朱槛宿鹓鸾。\n衰容任遣韶华逼，幽抱常教酩酊宽。",""],["年年高宴赏花天，明日花开赏更偏。\n昆弟总能吟五字，儿童不必报三鳣。\n承颜幸有步兵菽，行乐何须卢女弦。\n已促行厨烹玉鲤，好随佳节醉琼筵。",""],["佳辰每作看花燕，老去风流亦可怜。\n草阁于吾非漫兴，花溪同汝试鸣弦。\n红英且莫交春暮，绿醑还期醉月边。\n千古豪华谁更在，请将青镜问流年。",""],["卜筑于兹三十春，年来忙似宦游人。\n羞将白发随儿戏，且向青山著此身。\n海内宾朋消息断，林间风月酒杯新。\n长岒何必如张翰，短酌从他笑李绅。",""],["君从二曲城西去，我向双厓月下归。\n夕日烟云迷远寺，晴天花柳暗春扉。\n娇莺过𪩘娟娟语，乳燕冲波故故飞。\n对景相思期痛饮，凭君莫自惜罗衣。","君从二曲城西去，我向双厓月下归。\n夕日烟云迷远寺，晴天花柳暗春扉。\n娇莺过巘娟娟语，乳燕冲波故故飞。\n对景相思期痛饮，凭君莫自惜罗衣。"],["诸君并是风流客，殢酒微歌我不如。\n十载飘零浑一梦，百年问讯祗双鱼。\n诗篇尚忆同趋省，组绶空怜共直庐。\n白发青袍吾独老，愧从扬子问潜虚。",""],["列镇迎恩介胄雄，赭袍遥映塞云红。\n武臣敌忾馀虓虎，圣主忧时起卧龙。\n天上使星临阃外，斗间紫气照关中。\n长城万里今增重，不数平淮一线功。",""],["水际孤云合，船头细浪生。\n青山飞白鹭，绿竹啭黄莺。",""],["已办花前饮，花神岂避人。\n欲将花尽发，故著雨留人。",""],["邮亭新柳厌春阴，驿路黄尘销客心。\n碧水苍山予未晚，衰容短鬓尔何侵。",""],["凤泉东是美阳城，秦后离宫迹已平。\n细草不知龙辇去，城边日日唤愁生。",""],["许公碑石尚参天，科斗消磨不记年。\n公子经纶唐第一，乡邦述作近谁先。",""],["夕阳隐隐抱孤村，知是何王晾马原。\n龙种自随彤盖去，人烟常傍厩门繁。",""],["岁岁看花花已飞，花神若恨赏来迟。\n今年坐赏花才发，却到春风第几枝。",""],["新来无事已堪怜，春服初成二月天。\n同醉花前不同赋，转看金谷意萧然。",""],["此日庭柯尽著花，老夫逸兴正无涯。\n崦西莫羡千株柳，水际先看一带霞。",""],["五十五年才不忙，清尊同汝有谁妨。\n行歌正恐花阴短，大椀那论饮兴长。",""],["谩省年时醉里诗，便须极意饮金卮。\n幸无辛苦输公事，却看风流在水涯。",""],["西堂新酿酒如泉，还我南窗酒圣编。\n有景便看看便醉，古今人里让谁先。",""],["繁弦剧管坐花前，转觉春园花可怜。\n若把花枝对明月，红英笑杀镜中天。",""],["我醉君歌兴洒然，不知花影坐中迁。\n须教酩酊同今日，那许萧条似去年。",""],["繄自还京愿不违，柳边花底坐忘归。\n新诗美酒朝朝乐，莫管春归花乱飞。",""],["好句吟成便写墙，老来日日为春狂。\n天公有意随吾好，别借春游十万场。",""],["北泉精舍菊花开，节过重阳我始来。\n坐对菊花酬节物，危楼南眺望登台。",""],["自拟重阳醉此楼，不堪诗酒作淹留。\n狂夫老去情逾放，笑折黄花插满头。",""],["去年与客赏重阳，痛饮溪亭迟日光。\n今日月明情兴爽，何辞三万六千觞。",""],["月白花黄酒又清，长河恨不入杯倾。\n人间富贵同飘瓦，何物空教误此生。",""],["此生疏旷绝堪嗔，遇酒逢花便不驯。\n身外悠悠无染著，胸中的的有阳春。",""],["避嚣来野寺，学静惯参禅。\n般若台风静，多罗树雨连。\n老龙寒剑影，孤鹤避茶烟。\n玄到无言处，推窗一枕眠。",""],["立马松溪寺，长风扫断桥。\n逢僧无故老，磨石记前朝。\n崖古树遮目，台荒草没腰。\n坐陪清话久，鄙吝顿然消。",""],["荒村难问市，古刹倒芳樽。\n强饮开怀抱，沈酣罢讨论。\n欹枕无多梦，连床更几人。\n明朝回马首，归路莫逡巡。",""],["吟尖方滑溜，醉眼欲摩挲。\n总为高情遣，其如逸兴何。\n儒风便脱落，僧话转多罗。\n且莫嘲同异，孔门有四科。",""],["登高穷暮景，云树郁苍苍。\n牛饱眠烟草，鸟归送夕阳。\n渔艇趋前浦，僧钟出上方。\n坐深清到耳，寒涧落铿锵。",""],["剖破绿云房，来供天上郎。\n白分成片玉，清嚼满池霜。\n红子堆盘灿，馀甘浔齿香。\n青门随处是，何必问炎凉。",""],["披襟纳晚凉，微雨洒回廊。\n松吼虬龙怒，稻翻云雾黄。\n新词称绝唱，爽气协清商。\n更到山城远，檐铃代击梆。",""],["杏坛作孔道，杏林鸣仙居。\n儒医次第业，董樊先后车。\n三部脉息会，一点灵台虚。\n移此药天下，何必论刀圭。",""],["招提清欲水，不许点尘侵。\n径曲履痕薄，云封塔影深。\n佛说幻于古，人心巧似今。\n几多朝市客，方寸有山林。",""],["野寺寻真处，凭高望眼遥。\n天心留胜槩，人语在层霄。\n俗气从前避，清歌取次饶。\n明朝南北梦，嘉会惜寥寥。",""],["水啮沙中石，声声入耳幽。\n忽然疑砥柱，何处觅瀛洲。\n野寺偏宜夏，溪毛可荐秋。\n棹歌来往发，到底不惊鸥。",""],["脚根不避路，到处便为家。\n醉过十年梦，风抟一望沙。\n闲情诗入画，生意草方芽。\n长者须投辖，清清一味茶。",""],["尘封簪笏厚，一拂自今年。\n屯拟经纶济，忧当天下先。\n亭深风月上，书饱夜灯前。\n直到亨衢稳，披云见此天。",""],["烟草软十里，江云绕几家。\n犬灵夜当户，鸥懒晓眠沙。\n有缘寻道路，无处问根芽。\n兀兀推蓬坐，方壶有剩茶。",""],["去路还归路，今年似昔年。\n坐高三尺浪，争著一篙先。\n风急鸟更疾，云移岸欲前。\n不堪回首处，家在一方天。",""],["坐入江村夜，凄风两鬓生。\n渔灯忽明灭，野渡尚纵横。\n匣剑嫌光逸，囊琴觉调更。\n谯声不到耳，忽过雁归衡。",""],["宵发龙头镇，午过番阳湖。\n潴容百流秽，风轶片帆孤。\n光芒镜未似，畔岸天为模。\n野笛渔舟晚，行行雁落芦。",""],["眼眶才落此湖光，却叹身如湖里航。\n破浪只销心上稳，乘风何必望中洋。\n浃宵飞渡真为策，泛月归来不用忙。\n许国有怀如李泌，孤城明日是端阳。",""],["岸圻湖光恶，天翻万叠云。\n真于百死地，扶出再生人。\n未构唐公稿，几随屈子沦。\n冯夷应有意，留我献明君。",""],["一舸放此老，泛泛江湖游。\n寄迹真浮梗，何心问撞舟。\n路通颜氏濑，诗入米家流。\n有子横舟在，白头高卧丘。",""],["厌家思作客，客久梦还家。\n两睫抉此月，寸心纷似麻。\n亏盈真有度，南北更无差。\n岑寂谁驱得，开尘放瓮霞。",""],["春半尚无花出墙，一番疏雨为催芳。\n煖从南去多应早，寒到北来真较长。\n金粟陌头才柳色，银瓶窗外乱梅香。\n何如燕子还相识，衔得空泥占屋傍。",""],["春思苦撩乱，啼乌来树间。\n寒光尽流水，雨暝失高山。\n案牍求生意，妻孥强笑颜。\n家乡在万里，长是梦中还。",""],["何处开怀抱，天涯问讯人。\n懒成长似癖，酒薄也添春。\n只拼心中苦，相看竹上青。\n应门无客报，头秃不须巾。","何处开怀抱，天涯问讯人。\n懒成长似癖，酒薄也添春。\n只拚心中苦，相看竹上青。\n应门无客报，头秃不须巾。"],["晓风吹面软，轻帽送寒归。\n山阁雨声碎，野亭云气霏。\n草知催地力，青欲上人衣。\n闲数随来雁，今朝似较稀。",""],["雨凉侵短榻，春睡起偏迟。\n鸠拙寻遗构，鹰扬耐蚤饥。\n干戈经路滑，箫管动乡悲。\n愿和征夫泪，吹来鬓上丝。",""],["云点行人鬓，相看尽是翁。\n檐流翻作雨，衫薄尚禁风。\n欲混鹅毛白，休迷鹤顶红。\n梅花惊大晚，春老北枝空。",""],["少壮薄宦游，老作隐学士。\n种竹缘江坡，清风日来此。\n此心虚且贞，对竹颜无泚。\n扬尘落飘飘，夜雨频磨洗。\n老劲掣六鳌，渭川不在彼。\n垂垂雪低枝，寒梢依日起。\n白发映绿簪，何必论年纪。\n龙孙呈萧森，断截备国史。\n椽管秃瓮多，董狐良足儗。\n丹砂天上来，绯衣忽加尔。\n故人重相过，无主亦自美。\n引泉务厚滋，醉日还移祉。\n威凤谐笙簧，笑歌闻正始。\n再过三十年，此坡付儿子。",""],["积雪堆还堕，贪心欲占秋。\n桥迟驱蹇策，江晓打鱼舟。\n山向云中老，人如画里游。\n僵眠饿茅屋，歌舞乱南楼。",""],["夜雪密于昼，春寒忽过秋。\n忙搊东郭履，不见子猷舟。\n枝压鸟争啄，花浓蝶怕游。\n望中浑一色，何处认琼楼。",""],["茅屋不知得，春来三月深。\n蛛丝过游目，鸟语自伤心。\n谋到野中获，诗随景上寻。\n何人兼吏隐，吾欲再生今。",""],["社鼓村村闹，相看又一年。\n好怀因出郭，尘肺欲浇泉。\n山怪云堆恶，林疏日影穿。\n笑歌惊落帽，无意仰书天。",""],["高柳未匀绿，小桃初著红。\n两家斗芳媚，一任付东风。\n供茗来方士，扶犁见老翁。\n杜鹃非吊蜀，肠断莫岑中。",""],["短墙垂薜荔，茎嫩绿眠苔。\n吊古谁能事，匡今我不才。\n烟萝孤隼落，泉镜乱鱼开。\n立马长桥问，源头何处来。",""],["孤村寻窦氏，古庙拜刘生。\n风节乾坤老，流光草木荣。\n感时思警策，屯难厌浮名。\n俯伏山陵下，卑陈犬马情。",""],["贼来夫就䌸，贼去妇欲捐。\n赎身尚可百，挥金安惜千。\n赤手捍锋刃，死心良可镌。\n亦有几男儿，鱼肉终无传。","贼来夫就縳，贼去妇欲捐。\n赎身尚可百，挥金安惜千。\n赤手捍锋刃，死心良可镌。\n亦有几男儿，鱼肉终无传。"],["晴霞绚朝日，相对玉峰高。\n白发明蓬矢，青樽送海桃。\n洛中应主社，林下已忘骚。\n何处寻司马，斑衣未二毛。",""],["将军驰露布，有喜上龙颜。\n破竹迎锋下，持斨未缺间。\n天地若为大，鲸鲵秪自顽。\n论功书杰阁，欲拟燕然山。",""],["翛翛此长夜，一榻百虑生。\n何如晏眠人，日上三两楹。\n眷彼金石声，杂我砌下鸣。\n心茅日斩刈，寒谷迁双莺。\n开口笑未得，著耳颓垣倾。\n恶风穿鸟户，相对独关情。",""],["泥涂四老翁，伏腊商山侧。\n不堕留侯机，安使汉庭识。\n天子惊且疑，梦寐见颜色。\n颓衰挟痴儿，隐祸顿销息。\n一言系炎鼎，表表人臣极。\n非无经国资，所志在逃匿。\n冥鸿奋高秋，习习快两翼。\n岂知觊觎人，有恨填胸臆。\n神器匪私授，造化良可测。\n白云方英英，紫芝窅无迹。",""],["西风听鸣镝，马首云已东。\n征夫诜诜行，惨淡尘烟中。\n潢池恣狗鼠，崩骞并元戎。\n霜重铁衣冷，奔突驱群?。\n杀气日未薄，岂必三刑同。\n旧鬼乌啄肉，新鬼号瑶空。\n寒月照营白，暝色霏蒙蒙。\n岂不念妻儿，饥冻垂飞蓬。\n北里倾尊醁，南邻烧烛红。\n岁暮未归得，何当思挂弓。","西风听鸣镝，马首云已东。\n征夫诜诜行，惨淡尘烟中。\n潢池恣狗鼠，崩骞并元戎。\n霜重铁衣冷，奔突驱群?。\n杀气日未薄，岂必三刑同。\n旧鬼乌啄肉，新鬼号瑶空。\n寒月照营白，暝色霏濛濛。\n岂不念妻儿，饥冻垂飞蓬。\n北里倾尊醁，南邻烧烛红。\n岁暮未归得，何当思挂弓。"],["春来三月好，景足四郊中。\n豁豁羁怀放，骙骙马首东。\n林深藏鸟语，香远送花风。\n缓辔真如意，当途肯叹穷。\n远山青掩霭，短草绿蒙茸。\n思入兰亭妙，诗嫌谢老工。\n洗觥钱换酒，侧帽鬓垂蓬。\n野气迷坰坞，茅檐接大空。\n感时谁可后，忧世我当雄。\n百亩全无种，春饥未卜丰。\n杜鹃桥上过，休遇洛阳翁。",""],["世为衣冠重，文兼道义名。\n夏官思赞理，天部写铭旌。\n夜月秋亭古，春风晚棹轻。\n旧游元是梦，寒骨照山明。",""],["纷纷入世路，生死竟如何。\n两县野棠合，西曹旧案多。\n濠梁遗好伴，薤露踏哀歌。\n萧索盱眙墓，还看宿草么。",""],["教子祈忠国，匡扶愿显亲。\n元非博富贵，终见荷丝纶。\n乌帽新笼发，霞绡稳称身。\n焚香开玉轴，举目是枫宸。",""],["乍出寒郊外，分明似坝桥。\n合冰连断野，孤树入层霄。\n瘦马还堪策，饥乌信可招。\n一程兼百里，行尽不知遥。",""],["地旷心逾远，天寒气更清。\n识时曾似雁，解语不闻莺。\n公瑾元非酒，羊斟却怨羹。\n宦情羁思并，怅怅此郊行。",""],["厚颜思肉食，何意数干支。\n葭管愁添线，昆明待凿池。\n奔波三日路，滋味几人知。\n收得闾阎事，琅玕向我披。",""],["独有乾坤意，墙头欲放花。\n先几催草木，候气蛰龙蛇。\n塞上翁难识，垆边酒易赊。\n更无人肯问，温饱是谁家。",""],["好日瞢腾过，幽怀拍塞开。\n空随驴上老，不见雪中梅。\n和气因人致，风烟逐我来。\n城头悲鼓角，寒璧落残苔。",""],["不问燕山桂，那知玉井泉。\n稚儿方缊草，老妇未衣绵。\n夜梦追三窟，朝餐费万钱。\n提兵须几镇，何独向西川。",""],["春祠冬烝夜，清清入妙香。\n一班随进退，终岁异温凉。\n册祝昭禋远，衣冠卜吉藏。\n不须占王气，寒冱树苍苍。",""],["何处寻云窦，泉凝雪满池。\n林端悬鲫鲙，山麓集江蓠。\n貂帽寒绵卒，茅檐哭饿儿。\n为探幽兴出，番惹闷相随。",""],["松密堪承露，山高不碍云。\n金汤元有主，天地本无文。\n仰赖祖宗德，从教夷夏分。\n若非雄据稳，戎马尚缤纷。",""],["去路还归路，伤怀更几何。\n风尘随处是，须鬓笑人多。\n衰草牛横笛，霜林鸟乱歌。\n无端情思恶，掩耳莫相过。",""],["傅生姻家子，少独事一室。\n野气薄城郭，大朴浑不失。\n长途买棹夫，抱难纷如质。\n质之者为谁，王子我所密。\n入口即禹穴，雅不伸占毕。\n忽来告我归，四方志了一。\n居然改大观，逾望已六七。\n为告我故人，作器须树漆。\n我行与王子，摩厉方自弼。\n遽曰前人车，飞骞杳无匹。","傅生姻家子，少独事一室。\n野气薄城郭，大朴浑不失。\n长途买棹夫，抱难纷如质。\n质之者为谁，王子我所密。\n入口即禹穴，雅不伸佔毕。\n忽来告我归，四方志了一。\n居然改大观，逾望已六七。\n为告我故人，作器须树漆。\n我行与王子，摩厉方自弼。\n遽曰前人车，飞骞杳无匹。"],["剑外行骢日，春风为拂鞍。\n相思劳太史，知己尚儒冠。\n象马须忘险，疮痍未剧安。\n无缘起诸葛，留与阵图看。",""],["列圣联宾驭，开山閟玄灵。\n熊罴俨象魏，喉嗌限边庭。\n文皇主万国，武略呵六丁。\n南天立斧扆，北漠空毡屏。\n诏檄靖氛祲，弧矢威麋泠。\n仁宗薄世祚，章帝垂遥青。\n文人号宣朗，载籍辉繁星。\n英庙驻狩辙，策士惊羸瓶。\n穹庐覆真主，臣妾居靡宁。\n回天入缵服，杰阁图渠形。\n两朝定主鬯，多难携常经。\n外蛇就藩府，永巷辞严扃。\n殿色日炯炯，宫流夜溁溁。\n柴桑犬睡屋，荻藻渔翻汀。\n老农问旱魃，乐腊功玄冥。\n升平见歌舞，贤俊易岧嵉。\n梦觉过百岁，垣墉谁一听。\n风愆布后轨，剑舄分遗馨。\n六驾宫车晏，八音山谷停。\n木天元有撰，铁笔已忘硎。\n汉原陪翼亮，秦祀增光荧。\n谩记鼎湖谶，毋刊狠石铭。\n龙髯攀弰角，凤翥献翘翎。\n午夜风潜壑，霜天月在坰。\n虎丘干象纬，骊阜失崤泾。\n贱臣愧肉食，闵世随漂萍。\n分行拜厘祝，五云和露零。\n老马先主心，腐草后秋萤。\n长夜代烛光，冷石殊醉醒。\n天地有常主，断鳌撑北溟。","列圣联宾驭，开山閟玄灵。\n熊罴俨象魏，喉嗌限边庭。\n文皇主万国，武略呵六丁。\n南天立斧扆，北漠空毡屏。\n诏檄靖氛祲，弧矢威麋泠。\n仁宗薄世祚，章帝垂遥青。\n文人号宣朗，载籍辉繁星。\n英庙驻狩辙，策士惊羸瓶。\n穹庐覆真主，臣妾居靡宁。\n回天入缵服，杰阁图渠形。\n两朝定主鬯，多难携常经。\n外蛇就藩府，永巷辞严扃。\n殿色日炯炯，宫流夜溁溁。\n柴桑犬睡屋，荻藻渔翻汀。\n老农问旱魃，乐腊功玄冥。\n升平见歌舞，贤俊易岧嵉。\n梦觉过百岁，垣墉谁一听。\n风愆布后轨，剑舄分遗馨。\n六驾宫车晏，八音山谷停。\n木天元有撰，铁笔已忘硎。\n汉原陪翼亮，秦祀增光荧。\n谩记鼎湖谶，毋刊狠石铭。\n龙髯攀弰角，凤翥献翘翎。\n午夜风潜壑，霜天月在坰。\n虎丘干象纬，骊阜失崤泾。\n贱臣愧肉食，闵世随漂萍。\n分行拜釐祝，五云和露零。\n老马先主心，腐草后秋萤。\n长夜代烛光，冷石殊醉醒。\n天地有常主，断鳌撑北溟。"],["长安日已远，蜀道胡尔难。\n恋恋佳儿心，夜夜梦中还。\n一命得取道，万里谁当关。\n去时年少行，惊见毛发斑。\n母寿古亦稀，儿归良独艰。\n菊花酿露魄，豸绣明春颜。\n东望拜天子，南国方威蛮。\n九阪须叱驭，四牡行歌还。",""],["潦雨没街渠，源头水亦活。\n归骑惊瀊涡，努力睛闪烁。\n入门坐空斋，旅思苦索莫。\n岂无居高堂，谁复念蛙窟。\n疏茅湿已穿，重𫄨疑大薄。\n愁添甲子头，望入巫山脚。\n昨夜方酣眠，清风动帷幕。","潦雨没街渠，源头水亦活。\n归骑惊瀊涡，努力睛闪烁。\n入门坐空斋，旅思苦索莫。\n岂无居高堂，谁复念蛙窟。\n疏茅湿已穿，重絺疑大薄。\n愁添甲子头，望入巫山脚。\n昨夜方酣眠，清风动帷幕。"],["闭门深寂寂，有待为君开。\n书笥元无底，酒乡羞未醅。\n鸣鸠雨不歇，惊燕夜方回。\n飒飒清凉足，明朝秋气来。",""],["交谊论今古，知心见子期。\n只缘多病癖，深荷寄方奇。\n行蚁竹枝上，小车花外移。\n盘餐聊尔共，重约抱琴时。",""],["掩袖黄昏泪，深闺白发新。\n不缘身后语，能系未亡人。\n有子承衰谢，无家合苦辛。\n君恩还士论，赢得对苍旻。",""],["暂把好怀抱，开颜向客边。\n岁穷还有日，醉倒不须钱。\n笳鼓儿童市，寒酸尺五天。\n不妨论甲子，明日又添年。",""],["客愁连岁积，都到夜灯边。\n家信来三日，官衔直几钱。\n买痴作白眼，把酒问青天。\n卧听晓钟发，翻疑说去年。",""],["燕歌墙外度，高遏彩云边。\n袖出降魔剑，囊无卖赋钱。\n星躔随历次，更漏一壶天。\n莫怨宫流水，泠泠不系年。",""],["守岁翻便睡，思兄来梦边。\n有官非肉食，无吏索租钱。\n漉酒问燕市，烹鱼见楚天。\n相思愿相见，相共祝长年。",""],["年从此夜尽，年从此夜来。\n天日各有度，会合应无媒。\n烛销商妇泪，杯覆王孙哀。\n逐贫不饿死，驱厉徒生猜。\n揽镜羞蓬鬓，壮士胡为哉。",""],["摇鞭催马络，莫道看春迟。\n错认重经处，还疑未到时。\n林坰自远俗，村落尔相知。\n最喜杜公子，追游当我期。",""],["春草不受剪，茸茸弄鲜新。\n好山三月景，野渡百年身。\n花雨湿穿径，燕风轻掠人。\n春归何底急，来往小车频。",""],["袍笏瞻天近，衙筹坐日移。\n偶随安石屐，忘却习家池。\n野店当垆媪，长途弛担儿。\n淡烟桃杏坞，春色有人知。",""],["溪流迎我白，野烧为农菁。\n黎杖不扶老，春衫难得成。\n岸柳莺语滑，渚蒲鱼浪生。\n无由纳佳境，抉眦饱山明。",""],["出门消客恨，杯酒力春贫。\n树立青霄上，蝶随金谷邻。\n四方多事日，万里欲归人。\n卬首溪桥晚，孤舟阁水云。",""],["少从南国游，负却东山卧。\n云深矮屋封，天青孤鸟过。\n索索诗酒缘，劳劳簿书课。\n拂衣见高冈，顿把春愁破。",""],["春睡苦不熟，何事来相关。\n浅莎没深渚，白鸟飞青山。\n典绂桑麻主，扶犁虎豹间。\n无家酿新酒，社日乐风悭。",""],["阳刚负干德，铁石男子肠。\n云何妇女力，能任天地纲。\n剥极复乃生，理胜气自降。\n所以君子心，表白工词扬。","阳刚负乾德，铁石男子肠。\n云何妇女力，能任天地纲。\n剥极复乃生，理胜气自降。\n所以君子心，表白工词扬。"],["开济归才望，江湖成倦游。\n萱花清昼梦，堂背暮山秋。\n范妪支家造，苏郎抱国忧。\n黄花三十度，祈伴寿樽讴。",""],["料尔年家会，风谈一座秋。\n道形先石履，清响震山楼。\n花趁雨争发，鱼亲人自浮。\n信渠兼隐吏，相与为时谋。",""],["谁云冠盖侣，也自解忘机。\n高谊悲萍梗，官资略显微。\n泉从石溜下，云与鹤兼飞。\n落日斜穿径，归来尽染衣。",""],["春风荡晴江，夜雨落梧叶。\n南坡有高人，孤亭占清绝。\n看竹孰主宾，问月几圆缺。\n泉池三伏冰，花砌五更雪。\n独抱栽培心，造化论工拙。",""],["闽学师先觉，楚歌悲后生。\n相思不相见，秋雨暮山横。",""],["青门回巷月，白杨飞岸云。\n萧瑟入清夜，衣冠疑故人。\n空悬丝五两，怅望剑孤津。\n宰木看看拱，秋涛隐泪痕。",""],["老树摩崖风壑秋，似添哀思泣松楸。\n一函已了三生事，杯土难教万虑休。\n命锸且当今日务，摇鞭却忆去年游。\n荒亭展目云飞处，目到云飞泪已流。",""],["山延震位郁巃嵷，老父幽堂许我封。\n地脉藏真待人显，天峰列秀为谁供。\n丈夫清骨须移竹，处士芳魂欲抚松。\n恨杀九京终不作，惺时犹想梦时容。",""],["五里郊行转入村，何堪拈笔步招魂。\n楚歌薤露知无艺，吴爱甘棠幸有存。\n忍废蓼莪于弟子，但传清白与儿孙。\n戴鳌山立泛鲸海，难拟高深一念恩。",""],["衰服营城越一年，才登山麓泪潸然。\n乾坤异待千金直，首领同归拱璧全。\n马鬣新封当易合，牛眠故道不虚传。\n许多狐兔冗孤冢，安用苏公负郭田。",""],["云窦流泉吸不干，挽将洗我恨应难。\n门前有束生何忝，囊里无金死更安。\n神道千年留望柱，穹碑万口识休官。\n报恩莫罄身输国，拭泪含悲强一餐。","云窦流泉吸不乾，挽将洗我恨应难。\n门前有束生何忝，囊里无金死更安。\n神道千年留望柱，穹碑万口识休官。\n报恩莫罄身输国，拭泪含悲强一餐。"],["望里山头云满巾，麻衫泪渍旧翻新。\n功名未了难为子，升斗才沾不养亲。\n公论自能扬朽骨，雅怀应不放闲身。\n许多感慨干吾虑，短榻长檠夜达晨。",""],["山从东来壁面西，云侵霄汉冈陵低。\n草露湿履尚浥浥，松风拂笛长凄凄。\n三曲九曲流不断，一峰两峰青欲迷。\n哀哀举柩即深圹，精灵鉴此无穷凄。","山从东来壁面西，云侵霄汉冈陵低。\n草露湿履尚浥浥，松风拂笛长凄凄。\n三曲九曲流不断，一峰两峰青欲迷。\n哀哀举柩即深圹，精灵鉴此无穷悽。"],["四尺孤坟未告成，奇观百样一时生。\n祖宗合散枝连干，朝揖分明雨后晴。\n甲位文峰惊崒嵂，离宫天马自纵横。\n王维若染无声妙，可是山灵更有情。",""],["终天抱痛泪潸潸，宰柏青皮半欲斑。\n一息梦翻惊梦觉，百年人几见人间。\n寒乌飞诉无言恨，癯鹤归灵不忆还。\n最是追思旧游地，曾随翁马上兹山。",""],["才出衡门马首东，一山高处路腰通。\n云封青冢千年主，雨净黄冠数亩宫。\n有玉可辉幽宅夜，无金难买墓田丰。\n哀怀耿耿浑无际，圣主追恩俟大同。",""],["华轩人几解闲行，春色无情过眼明。\n草湿衬花疑绣地，山连蒙霭欲罗城。\n短桥深藓惊蹄滑，啮岸高枝惯鸟鸣。\n尘虑已忘清入骨，不妨穷壑洗淙声。","华轩人几解閒行，春色无情过眼明。\n草湿衬花疑绣地，山连蒙霭欲罗城。\n短桥深藓惊蹄滑，啮岸高枝惯鸟鸣。\n尘虑已忘清入骨，不妨穷壑洗淙声。"],["年来习得懒于云，秃笔严披肆典坟。\n草屋厚乘忘漏雨，纸窗微隙可容曛。\n朝宜论列野宜俗，生有穹碑死有文。\n前代鼎彝今具在，莫言铭后更无勋。",""],["规将好景辏春华，朝士装成处士家。\n夜雨忽添枝上叶，东风犹拂鬓边花。\n鸟如唤我梦初断，山似羞人云半遮。\n却怪此身羁宦辙，无多缘分伴烟霞。",""],["野寺寻芳著屐忙，雨花沾袖趁风香。\n从头捡点伤春事，抚掌瞢腾过日光。\n黄四娘来迎笑脸，杜工部已破愁肠。\n流年去去谁留住，大债如天次第偿。",""],["才离城市即山林，古刹停骖一解襟。\n我欲静中还有得，谁言删后不须吟。\n茶椀润枯烟灶湿，酒杯销泪烛痕深。\n相逢尽话浮生梦，梦觉浮生只此心。",""],["谁解挥戈却日光，年来年去自家忙。\n世情落落话移榻，心绪忉忉笑举觞。\n声入北风毛欲树，梦回南国背多芒。\n不如袖袖无关系，到得浮沉老道场。","谁解挥戈却日光，年来年去自家忙。\n世情落落话移榻，心绪忉忉笑举觞。\n声入北风毛欲树，梦回南国背多芒。\n不如袖袖无关系，到得浮沈老道场。"],["轩冕维身丘壑怀，神交万里故人偕。\n秋风入棹思归路，夜雨连床忆小斋。\n几处樵歌惊耳聩，一声渔笛破心霾。\n仙舟却也无前誉，折角巾归笑满街。",""],["物色都收上笔尖，惊人句法俗人厌。\n云横水蘸天移棹，风泊花飞昼卷帘。\n暂息敢忘黄鸟知，浪游应惹白鸥嫌。\n归来小坐温残蠹，一夜悠悠过几签。","物色都收上笔尖，惊人句法俗人厌。\n云横水蘸天移棹，风泊花飞昼捲帘。\n暂息敢忘黄鸟知，浪游应惹白鸥嫌。\n归来小坐温残蠹，一夜悠悠过几签。"],["朝野牢牢两系身，十年疏更一朝亲。\n交游自古能无别，张范于今又有人。\n风力摇摇江上柳，晴光漾漾水中苹。\n相期何处梅花发，深夜寒檐再共巡。","朝野牢牢两系身，十年疏更一朝亲。\n交游自古能无别，张范于今又有人。\n风力摇摇江上柳，晴光漾漾水中蘋。\n相期何处梅花发，深夜寒檐再共巡。"],["古林阴木欲无冈，孤棱冉郁撑穹苍。\n铮铮万籁惊残梦，阳乌走曜衣麻桑。\n腔中湛湛无何有，川上晴光花间柳。\n老农日日理生涯，数口命悬田百亩。\n野云洞口为谁开，青峰个个迎人来。\n大颠解我文学会，一肩稳挈诗囊陪。\n二难四美一时集，许多眼界闲收拾。\n却费将军五万笺，笔锋扫秃烟犹湿。\n洗觥命酌还自讴，山花笑上游人头。\n花香簌簌落酒魄，嘹嘹野鹤舒青眸。\n春和却也有秋爽，不独兰亭解心赏。\n浪云今日非古人，德星昨夜禅关朗。","古林阴木欲无冈，孤棱冉郁撑穹苍。\n铮铮万籁惊残梦，阳乌走曜衣麻桑。\n腔中湛湛无何有，川上晴光花间柳。\n老农日日理生涯，数口命悬田百亩。\n野云洞口为谁开，青峰个个迎人来。\n大颠解我文学会，一肩稳挈诗囊陪。\n二难四美一时集，许多眼界閒收拾。\n却费将军五万笺，笔锋扫秃烟犹湿。\n洗觥命酌还自讴，山花笑上游人头。\n花香簌簌落酒魄，嘹嘹野鹤舒青眸。\n春和却也有秋爽，不独兰亭解心赏。\n浪云今日非古人，德星昨夜禅关朗。"],["村落空梁新燕泥，受风斜影乱东西。\n去年租税门无吏，今日逢迎主有鸡。\n春过一番人坐梦，马延再纪路难迷。\n淳音欲挽回清庙，谁在唐虞敢任夔。",""],["笑笑长年过虎溪，此回忘却自家奇。\n三槐器宇步犹缓，五柳丰神手欲携。\n野鸟几声人逐北，零花万点岸移西。\n无情只似风中蝶，都向诗坛借品题。",""],["处处柴门日举烟，几人春思不成眠。\n长锄拄阁山头雨，短笛横吹洞口天。\n芳草联镳清得句，便松连榻静谈玄。\n怪来野鹤相亲意，嘹亮一声飞过前。",""],["春江拥雪护行舟，舟上豪人自在流。\n樯尾无笼多去鸟，笔头有刃少全牛。\n杨州会里花呈瑞，宋子门前柳更愁。\n顾我关心名利上，何如莎草一眠鸥。",""],["深篙撑出柳阴船，直到芦根浅水边。\n刈麦食新生意足，卖花担旧叫声便。\n钓鱼台上竿成竹，载酒堂前草覆田。\n鼓楫放歌歌欲醉，问奴有几杖头钱。",""],["小棹悠悠走水光，浪翻花片触殷香。\n好山岑寂添诗瘦，细雨廉纤促渡忙。\n壮志未能忘伐木，微躯元不出空桑。\n年来识得真滋味，老菜馀花匝地黄。",""],["为取深青洗却迂，石梁趺坐正刚予。\n匣中宝剑腾还否，天上银河落未如。\n饮雪香分归洞侣，佩环声碎宴池馀。\n沧桑果是无根说，会见何人去恶书。",""],["十里春骄碧玉蹄，为分清思草堂西。\n风抛鱼尺水痕阔，云织莺梭树影低。\n芣苡盈筐人自采，豕蛇归穴剑无提。\n太平有象伊周在，谁向桃源问五溪。",""],["深掩柴扃老却春，不知花烂已迷滨。\n漫漫野草踏成路，泼泼江流空问津。\n最是一年生事急，谩劳百舌巧声新。\n坐馀忽地东风恶，举扇何人要避尘。",""],["微暑侵凉晴半阴，养花天为主人深。\n除教蔓草开三径，恨不松根长百寻。\n东郭梵音鲸入壑，西山瀑布练飞岑。\n坐中有客闲评史，几见丹心照古今。",""],["送归春事已阑珊，雨惹云衣万叠峦。\n愧我无诗虚好景，多君有力障狂澜。\n水心亭子论心会，虚白堂中袖手观。\n击缶浩歌箕踞稳，自家风味欲无官。",""],["谁为吾人购二天，马前万滴沃公田。\n顿教赤土俱行潦，要使黄云足备𫗴。\n一念果然回大造，五龙应不让先贤。\n新亭拟入滁阳事，欲代苏公续一篇。","谁为吾人购二天，马前万滴沃公田。\n顿教赤土俱行潦，要使黄云足备饘。\n一念果然回大造，五龙应不让先贤。\n新亭拟入滁阳事，欲代苏公续一篇。"],["并马郊行趁月凉，渠源十里路岐长。\n岭横云际衣全湿，林抹烟笼影半光。\n熠耀数星萤在草，丰穰几处稻登场。\n太平可是真无象，何事茅檐稳睡厖。",""],["山留残月路穿云，数里模糊认未真。\n鸟似唤醒人转急，犬于临别客还亲。\n依稀茅屋无扃户，寂寞茶烟少并邻。\n独有山花知我意，随风吹入马蹄尘。",""],["一骑香风晚稻花，淡烟深处有人家。\n崎岖石磴两膝屈，腾踏野桥双眼赊。\n山黛惯来迎浴日，溪声元不碍流霞。\n未闲人作闲游计，谁信浮生别有涯。","一骑香风晚稻花，淡烟深处有人家。\n崎岖石磴两膝屈，腾踏野桥双眼赊。\n山黛惯来迎浴日，溪声元不碍流霞。\n未閒人作閒游计，谁信浮生别有涯。"],["石田无主半榛荒，古刹看看瓦砾场。\n山脊垂头欲宾主，泉声入耳助凄凉。\n空阶雨过苔侵壁，圮屋春来燕语梁。\n怪我征轺破寥落，谈玄坐上月痕光。",""],["昨宵霏雨作秋声，为洗尘途待我行。\n水合宫商添节奏，山横翠黛转分明。\n风便马足轻三舍，露蘸林梢湿两肱。\n天与游人送清景，无端诗思一时生。",""],["石路硗硗马足劳，偶来山寺访方袍。\n会教玉带换一语，不独金山有二豪。\n疏竹半窗移日影，长松万壑响秋涛。\n固知方外有馀地，野鹤一声鸣九皋。",""],["古木修篁寺寺幽，遣怀随处暂停驺。\n欲留残照五里落，偶有好风双鬓飕。\n林下风流非学晋，胸中经纬在匡周。\n从今先后为忧乐，多少闲思强上楼。","古木修篁寺寺幽，遣怀随处暂停驺。\n欲留残照五里落，偶有好风双鬓飕。\n林下风流非学晋，胸中经纬在匡周。\n从今先后为忧乐，多少閒思强上楼。"],["秋风吹起逸人心，按志仙踪次第寻。\n溪泛桃红春不断，洞迷烟绿路方深。\n鹤旋吼树声相入，鹿转晴崖影半阴。\n最爱黄花供地主，破觥添得几巡斟。",""],["平田处处是桑麻，燥土曾经炼彩霞。\n白石煮来应有术，碧莲开遍未多夸。\n清饶掬雪三生梦，闲倚撩云半日涯。\n前路险夷浑不碍，秪须驰使访灵槎。","平田处处是桑麻，燥土曾经炼彩霞。\n白石煮来应有术，碧莲开遍未多誇。\n清饶掬雪三生梦，閒倚撩云半日涯。\n前路险夷浑不碍，秪须驰使访灵槎。"],["马足轻轻绊暮烟，山隈便坐自怡然。\n忘归借使解回日，见道何妨不在川。\n入画王维真有数，留诗玉井更无前。\n荒坛古木如知觉，肯向麻姑学永年。",""],["君为山灵壮几分，倒囊携酒共穿云。\n松头露滴罗衣润，墙角风醒落帽醺。\n寒涧取青千尺雪，长杠扫尽八千军。\n西风回首东南路，观瀑亭前日已曛。",""],["万山深处两吟身，鄙吝都消幸有邻。\n风景因人添却胜，物华随意看来真。\n壁立词锋山鬼泣，源穷经案野猿呻。\n扬尘几度俱浮梦，谁见桃花洞里春。",""],["好景谁将此画移，百年老子一裘披。\n素琴不许闲人听，只有高山流水知。","好景谁将此画移，百年老子一裘披。\n素琴不许閒人听，只有高山流水知。"],["紫气入斗肇闽学，苏文趾美眉山童。\n真才一出动天地，不知谁任为罗功。",""],["云浮漠漠山为骨，山瘦棱棱云作衣。\n动静交时方见道，更于何处问庖牺。",""],["东风吹柳黄金细，折枝词向行人媚。\n来时去时同此毡，乡学国学易其位。\n杨君升蚤孚奇占，韩公谪后深膏味。\n长安燕落画梁泥，桥门士启先生秘。",""],["莆阳十年磨桂斧，旴江十年樵桂楚。\n锋霜落手眼星光，桂林一入争先睹。\n莫惜桂林小君用，知君借与桂林重。\n状元峰头应有人，明远楼中学臧梦。\n君不见张曲江，柳愚溪，宣城寄迹君须知。\n万金不爱打碑楮，都付来人公是非。\n又不见思骏马，买骏骨，许多朽瘠封洼窟。\n孙阳一上黄金台，桃花叱拨惊驽骀。\n明年俊乂纾忠怀，随君傧策升尧阶。",""],["淡淡晴光倒浸川，去年风景似今年。\n何人疋马郊行急，茅屋家家待举烟。",""],["恼人春思欲葱芊，野寺愁看碧玉椽。\n社散不知谁是醉，几回搔首晚风前。",""],["处处柴门小小坡，暗香风里马蹄过。\n闲人检点春消息，细数雨飞花几多。","处处柴门小小坡，暗香风里马蹄过。\n閒人检点春消息，细数雨飞花几多。"],["才见游人著葛巾，一场好景一番新。\n卖花声过街头急，忙杀洛阳桥上春。",""],["共卜朱轮轧轧声，随来膏雨自分明。\n矢心掬水三年冷，障眼飞尘一夜清。\n召伯只争先后著，南人不异古今情。\n缶音也学鸣韶濩，附尾曾垂不朽名。",""],["天忘下土秋悭雨，千里膏田半欲枯。\n云脚怪他山外过，风声撩我望中孤。\n郊亭谩阻欧公兴，方社空遗董子图。\n野老数惊鸣垤鹳，一瓢谁倒慰来苏。",""],["马便熟路立风嘶，野寺云林绿半垂。\n眼豁不知天更大，心焦却怨雨来迟。\n柳残晴岸翻成趣，花发秋江正及时。\n杖屦叨陪消俗虑，一囊收得几联诗。",""],["满腔浑是染丹青，王国专班小傅霖。\n鸿桷人多驰宦志，鹈梁谁更动乡心。\n河间正协匡时制，董子元无抱膝吟。\n前席虚怀咨对便，一帘风月伴书淫。",""],["花择人，人爱花，天成宾主东篱下。\n渊明一去不复归，彭泽留作一场话。\n南丰逸人学陶者，六十年来无定价。\n寿芳偏趁此花清，凭我笔端驱造化。\n楼头鼓，苑中诗，谁云草木尽无知。\n寿君元是此花种，寒英岁岁霜高枝。",""],["怪底妖氛犯法星，薤歌愁断路人情。\n宪纲秋色台中草，史笔春官石上铭。\n鹤病故园怀旧主，虬蟠丘首护先生。\n西风不减诸郎恨，吹落寒乌夜夜声。",""],["使君江上买归舟，载得月明真似秋。\n浃岸柳丝怜老稚，满楼醉色下汀洲。\n宜休未必如前辈，易退何妨挽末流。\n公论到头惟笔在，甘棠不独咏西周。",""],["夜雨西窗欲睡时，芭蕉声碎枕边诗。\n此君果是无闲物，好见周公为解颐。",""],["不把闲身绾半通，孔颜都在此腔中。\n小庵移傍灵峰下，要使荆公避远锋。",""],["冻容不减玉颜色，疏影横檐却避春。\n雪夜槎牙舒铁骨，最堪图赠未亡人。",""],["船到昶溪溪上泊，夔夔故老送新茶。\n却将往迹闲敲博，谁是当年十万家。",""],["自与孤寒别老根，洛阳台上几争论。\n两家色样专芳味，一阵东风受主恩。\n玉带也曾占宰相，金樽随处闹王孙。\n谁能拔此挥吟赏，多种桑麻补厚坤。",""],["曾于此处夹龙飞，血溅孤冈迹未知。\n反火威灵归后著，得糠符谶炳先几。\n函尸僭伪来何暮，破胆腥膻遁恐迟。\n真主默交天地相，元功犹自说刘基。",""],["官舟薄暮下都昌，冒险篙师报日康。\n霞锦一机天自织，波文万顷水成章。\n远山黛锁真嫌画，新月眉横恰对缸。\n且尽一尊开拍塞，山城寥落夜催梆。",""],["石氏富非朝夕得，财多元是祸之媒。\n香尘锦帐无名目，未必贪夫为朵颐。",""],["志多名郡据长江，今日翻为一战场。\n杨贼未燔城尽砾，李生应吊笔如杠。\n生灵鱼鳖知多少，节制貔貅正富强。\n折首几何惊奏凯，更无人似相公沆。",""],["贫儒不用买山钱，到处开堂坐煖毡。\n白鹿效灵名古洞，紫阳卫道辟闲田。\n一湖水面真无恙，五老峰头尚有镌。\n末学虚怀遭雨恶，瓣香遥奠愧崇贤。","贫儒不用买山钱，到处开堂坐煖毡。\n白鹿效灵名古洞，紫阳卫道辟閒田。\n一湖水面真无恙，五老峰头尚有镌。\n末学虚怀遭雨恶，瓣香遥奠愧崇贤。"],["少年曾诵二泉诗，不似庐山未见时。\n苍翠已从言外得，巑岏到使梦中迷。\n欧公履历能忘险，朱子文章足解疑。\n今日维舟访真迹，三君容我?前旗。",""],["十年驰梦到庐山，假道匆匆竟莫攀。\n炉里有烟疑是雾，灶中无火却成丹。\n银河几道归潭底，铁笔千秋寄石颜。\n我固负山山负我，一时和雨没云间。",""],["万仞崚嶒落大江，芙蓉一朵镜中藏。\n官家列镇雄南服，老氏离宫占上方。\n花木不须春自好，星辰无碍夜分光。\n饶他胜槩名天下，总是吾人作主张。",""],["处处溪边鼓杂钲，木龙吹浪夺龙精。\n汨罗有策追诗债，屈子无心作怨声。\n汉武瓶砂还捕蝎，淮南拌豆欲驱蝇。\n剪蒲骨肉频斟酒，江上寒峰为送青。",""],["元亮作官还爱菊，好声嬴得刊于竹。\n彭泽千年留故名，更有何人武芳独。",""],["撚菊接篱酣白酒，不因五斗折腰人。\n若教此趣知冯道，更有何心事二君。",""],["杨契丹画菽与桑，寒足为衣饥为粮。\n郑广文画松与柏，铁骨棱棱雪霜魄。\n何如更画椿与萱，冰绡一幅天根全。\n青柯八百未云老，丹花岁岁儿孙联。\n海波扬尘话长喙，垂垂景莫日方曙。\n饥寒无恙雪霜丝，孝子有心难得绘。",""],["亡人奔走霸图开，与块终为贾祸胎。\n愧杀阿婆轻一饭，博将庙食万年来。",""],["英雄落落苦沈埋，赤手扶炎亦壮哉。\n借使夜亡非相国，谁怀斗印上高台。",""],["钟宝深藏悍妇刀，纵拳更合罪谁曹。\n若非平勃交欢力，汉业真如燎毳毛。",""],["家隙司牝或并雄，斗粟尺布无弟兄。\n平生握手欢正洽，逐兔攫金如路逢。\n壮哉桃源三义士，异姓纠结成肤功。\n三物一盘还一㰱，诅词烈烈蜚英风。\n南阳草庐履踏趿，虎牢战气徒匌蓊。\n死生成败未足惜，泉台相见无赧容。\n恨不停舟夜深过，踣麟反袂悲人穷。",""],["刺船逆水正趋北，开窗放山却忆南。\n排排列戟见崷崒，个个堆螺披黯参。\n南人与山自为伍，北地忽见成癖耽。\n吊古感慨访故事，惯路剧谈沣沛间。\n蜿蜒上腾作王气，清淑下结钟龙颜。\n白晢亭长一剑士，胡敢抉睫窥函关。\n秪缘项益嬴氏毒，顿教约法能胜残。\n鸿门示玦过鸟道，平城脱马蹲虎崟。\n遂鹿翼明画犄角，大业立就亡艰难。\n衣锦昼行话乡曲，放歌树石深深镵。\n几欲磨苔认蝌蚪，便觉笔底波澜翻。\n谁里无桑更无梓，白头竟未图生还。\n白头竟未图生还。",""],["一道官河负国储，百年疏凿失前驱。\n猬螗故纸墨犹湿，华衮人言扫不除。\n建议更非王主事，食功那得宋尚书。\n从今人胜天才定，两跃芳声半简馀。",""],["怀玉多年不易沽，价高留取作人模。\n胸中若使边生有，囊里何妨郑子无。\n旴水源源明道派，闽山矗矗紫阳徒。\n蓝青以次须时用，方信须眉是丈夫。",""],["仕国知君有蕙心，青丝五两拜恩深。\n作宾若愧风开帐，案令休猜土化金。\n衙鼓冬冬公座晓，籧腔切切故乡音。\n行舟落雁芦花岸，先把官箴次第寻。","仕国知君有蕙心，青丝五两拜恩深。\n作宾若愧风开帐，案令休猜土化金。\n衙鼓鼕鼕公座晓，籧腔切切故乡音。\n行舟落雁芦花岸，先把官箴次第寻。"],["青衫犹忆去年时，风范于今便作师。\n席煖圣贤清入骨，吟穷苜蓿苦添髭。\n惯通乡话如归鸟，更凿芳心为守雌。\n荔子不能羁客思，安排博带绾青丝。",""],["禄仕从来不拣官，清衙嬴得为亲欢。\n诗书有味缘多结，案牍无关梦更安。\n江上菰蒲春入棹，云间风味月当坛。\n许多陆子在桃李，会见长风生两翰。",""],["倚剑男儿易别离，壮游风味许谁知。\n来时荷碧乱翻袖，归去柳青初上眉。\n南调夜怀非楚士，北堂春梦似周嫠。\n两头消息几千里，莫惜秋江短棹移。",""],["客魂未扫娥眉翠，函谷阴阴宰木新。\n黄纸一通风雨梦，青缃两幅画图真。\n生封有恨看花子，死报毋忘结草人。\n道左穹碑磨藓日，鸟声泣断几番春。",""],["谩说春霞醉风力，海棠睡倒倚墙梢。\n却知宰辅无滋味，酽醋从来是故交。",""],["人寿百年亲共之，万里客子归未迟。\n秋风一帆趁鹏翮，清歌不负黄花期。",""],["未信须眉梦里真，龙眠老手负高邻。\n寿觞有咏多名笔，便作山中不老人。",""],["我生与君未识面，掉笔难教续楚歌。\n太史有连图永迹，墨痕翻作泪痕多。",""],["富媪销魂贫失母，棺声惊发汝滨硎。\n助边卜氏将军署，入郭庞公处士星。\n生死无缘逃大块，文章有幸托思亭。\n子规啼夜娟娟月，风泪深痕宰树青。",""],["好风催煖上梅枝，香落佳儿舞袖垂。\n堂上尽堪娱寿母，人间元自有瑶池。\n青冥细斫天台近，浴日刚从海屋离。\n归箧琅琅珠玉富，白云经岁绕峨眉。",""],["亭覆春云竹几竿，未教无主客来看。\n补林药起儒生俗，当户驱回炎吏难。\n万卷昼帘清入幌，十年夜雨碧馀寒。\n元功可是谁忘得，欲作秦箫和去鸾。",""],["江东归梦看云时，两疏陈情总孝思。\n那更鲈鱼堪作脍，只缘衮职正缫丝。\n孤帆夜落潮声静，五鼎秋移菽水私。\n料得北堂非恤纬，手中纫线整朝衣。",""],["烛痕长照泪痕干，恳疏云归系母安。\n万古纲常元有孝，几人风节肯无官。\n野云斜度吴江白，山雨初深燕曲寒。\n须备庙堂前席问，流民蚤入画中看。","烛痕长照泪痕乾，恳疏云归系母安。\n万古纲常元有孝，几人风节肯无官。\n野云斜度吴江白，山雨初深燕曲寒。\n须备庙堂前席问，流民蚤入画中看。"],["天涯有子侍翁归，深夜焚香草疏时。\n赖有元良新孝理，不妨离别恼相知。\n江光夜舫南山梦，木榻秋斋北雁期。\n桑落酒杯团骨肉，莫教人说报君迟。",""],["陌上垂杨枝上风，依依似管别儿翁。\n恨无鸣雨回行马，愁见流云催去鸿。\n垒遍万郊须问幕，江深五月可瞻枫。\n到家便说陈情事，奏草行行是教忠。",""],["婆娑椿树碍曦光，移向庐陵孝子堂。\n白发侵寻蝇黍字，青山八十主宾觞。\n祝词须到看桃实，益算从教与线长。\n安得老人问消息，铭心未肯说存亡。",""],["异乡难作故乡离，握手临岐更赋诗。\n归到江头方酒熟，行过岭表是瓜期。\n青屏野色随人有，白鹭官资未尔羁。\n见说崖山沈辇迹，陆公遗事寄相知。",""],["恶风酸鼻酿寒胎，败叶离披半覆台。\n吟骨棱棱羸马钝，羁怀琐琐道邻开。\n狐狸未取寻常备，桑落还须三百来。\n路上𫄨儿真入画，郑公知是几时回。","恶风酸鼻酿寒胎，败叶离披半覆台。\n吟骨棱棱羸马钝，羁怀琐琐道邻开。\n狐狸未取寻常备，桑落还须三百来。\n路上絺儿真入画，郑公知是几时回。"],["坐听风铎减于秋，寒到千门信欲留。\n学士有怀支大厦，将军何意锡重裘。\n冰川幻术谁争浴，雪窦吟高我欲雠。\n南北气无愆伏候，莫教人苦说秦周。",""],["摘来采采满筐云，野味全凭水火匀。\n千片碎分千里月，一囊收拾一年春。\n玉川格局字字古，雀舌名头处处新。\n洗手拆封如见面，却惊身是异乡人。",""],["故乡茶叶异乡烹，添得吟肠一味清。\n水凿冰崖凝碧椀，火翻雪浪覆青瓶。\n含鎗谩说呈新品，带脚从今减旧声。\n愧我相知无谏议，也须三椀坐严更。",""],["坐深华月冷侵裾，秋去人间我自知。\n影射阴阳遭地隔，光摇星汉与天垂。\n昨宵未到十分满，后夜却愁些子亏。\n损益由来割昏晓，更于何处问元龟。",""],["碧天流月如秋否，依旧山河一镜移。\n丹叶飘风散云影，青娥惯冷浴冰池。\n残年两度光仍好，今夜三更睡较迟。\n秪恐分身照闺怨，寒衣犹未到边陲。",""],["残堞莫云愁欲断，几堆暴骨领锋馀。\n何如完节只女子，到得收名在史书。\n末俗似从浇处革，人心真见静中虚。\n不知折箭还存否，好付男儿学守雎。",""],["紫殿云浮日影开，传宣分历下灵台。\n蚤县象魏思周典，方信玑衡有帝裁。\n虎拜班中万国在，龙飞天上七年来。\n深山穷发知春到，前度斗杓惊又回。",""],["碧天如洗夜云轻，犹与殷勤唱渭城。\n莫道两京非远别，不如行路本无情。",""],["我家去君百里程，忆昔相别今几春。\n去年幸接同采好，不知俱是离乡人。\n君今欲归归便得，北堂健母儿循循。\n我欲随君恨无翼，愿作江边飞渡云。",""],["将星垂曜烛西南，江汉师行惯解骖。\n鸟道层空千里阁，旌头划破半江岚。\n雪深淮蔡须成算，夜宴宾僚未易参。\n露布驰功报天子，脱衣沽酒壮歌酣。",""],["老健真逾马据鞍，封侯不道丈夫难。\n阵图石上书千卷，钗钏途中菜几盘。\n壮略春分江雨断，雅歌夜逼蜀山寒。\n安排凯乐迎归节，虎拜蜩蝉换豸冠。",""],["低枝花蘸水流香，未信游人苦日长。\n见说西湖好风景，山川别是一温凉。",""],["倚墙梅绽雨中肥，落弹惊回燕雀飞。\n见说西湖好风景，不知处士几时归。",""],["管弦声拂柳堤通，双颊微微带酒红。\n见说西湖好风景，昔年曾认画图中。",""],["镜痕风静露纹平，万点寒山落影清。\n见说西湖好风景，杖藜何日傍湖行。",""],["混元罨画野屏舒，一老烟蓑钓上鱼。\n见说西湖好风景，尽拈书卖肯移居。",""],["采莲曲里采莲船，碧落中浮去更还。\n见说西湖好风景，柂楼蚤饭惜花天。",""],["六桥人卖浊醪香，斜带疏篱花半黄。\n见说西湖好风景，不如秋叶过江忙。",""],["寒潭风雨洗娟娟，人上水晶宫里船。\n见说西湖好风景，越中真有小壶天。",""],["雪峰眼底无巴蜀，寒月纷纷雁荡来。\n见说西湖好风景，山阴旧伴许流杯。",""],["深夜坐庭华月满，新秋爽气净炎蒸。\n题诗剔蠹嫌无酒，作字如蝇不用灯。\n湿露添凉恬睡鹤，西风摇劲起饥鹰。\n只愁井上梧桐叶，渐渐离披数未能。",""],["忽去忽来如寤寐，相违相见已忘言。\n望尘独倚长亭下，勒马难回落木边。\n家信劳兄三载梦，官箴费我五更眠。\n浮云好似憎怀抱，明日楚江今日燕。",""],["忆弟郢船棹更疾，送兄冀马行偏迟。\n异乡同气重留恋，一日万里分路岐。\n刀圭吐纳还自爱，平生温饱恒观颐。\n粗布大被及蚤制，频频为卜归来期。",""],["孤鸿高骞志在远，双凤食竹不长群。\n裹药却病思见弟，牵衣割爱苦事君。\n抱琴便作思归引，储钱为买抛青春。\n闻道乡郊尚多垒，厚集战士方如云。",""],["来时葛衣畏杲日，别去尽脱轻罗裳。\n喜根天性翻作怨，愁向人前却类狂。\n加餐谩说长为客，饮水方知不似乡。\n故园花鸟如相候，时有青州来短墙。",""],["行路莫计几多日，不到家时行未休。\n孤侄拍手迎门笑，老母望眼依闾愁。\n开土近山宜树栗，引泉入沼容方舟。\n结交旧有陶与谢，相招时作东湖游。",""],["还家短日思永日，行路无情元有情。\n天涯手足向分袂，故国山水寒齐盟。\n不妨深雪压篷屋，秪愁缺月临孤城。\n谷口子真韩吏部，逢人惟说泪交横。",""],["借楼曾当望云亭，三岁寒宵梦杳冥。\n苏子连床成偶合，狄公踪迹厌丹青。\n相逢欲话还无语，忍别沈酣尚怕醒。\n疋马郊关轻万里，为贪西谷煮寒冰。",""],["十年不作江湖游，今日重来缓我忧。\n女柩才归土未掩，妻骸束䌸岁已周。\n官常苦系甘贫病，家祸因仍谁怨尤。\n江南不独赋庾信，摇落更多悲早秋。","十年不作江湖游，今日重来缓我忧。\n女柩才归土未掩，妻骸束縳岁已周。\n官常苦系甘贫病，家祸因仍谁怨尤。\n江南不独赋庾信，摇落更多悲早秋。"],["懒心避俗通三昧，恩义驱人说二难。\n捩柁风生催郢客，出门云杳入燕山。\n纵横士马悲途梗，惯熟楼台当旅还。\n举目烟霄有征雁，几时书帛寄乡关。",""],["寒郊佳处总堪悲，仗剑南行远我师。\n入路便知归有日，到家翻忆别多时。\n百忧欲洒千行泪，两地难禁半夜思。\n宦学恶怀谁共赋，满床纤管不成词。",""],["冷风吹落归湖雁，霜月照寒啼树乌。\n山县且听更鼓响，江乡须避夜灯疏。\n肃清门户远城郭，整理冠裳拜帝都。\n愧我尚为升斗累，洛中思见马君无。",""],["投檄云归便放舟，大兄真为掩吾羞。\n贾生应悔无长策，崔氏从前下冗流。\n恬退特书真宰奏，告身超格后人收。\n是非不必论今昔，深锁松筠禾黍秋。",""],["临椷洒墨便忘馨，为爱监军奋执冰。\n只恁干戈心上战，已拼老瘦见时惊。\n秦关野树闻鸡犬，巫峡安流惯雨晴。\n羌笛一声悬榻下，蚤从阊阖见文星。","临椷洒墨便忘馨，为爱监军奋执冰。\n只恁干戈心上战，已拚老瘦见时惊。\n秦关野树闻鸡犬，巫峡安流惯雨晴。\n羌笛一声悬榻下，蚤从阊阖见文星。"],["园亭曲曲似山深，有约睢阳著谏林。\n莫道旧筌真忘却，爱君元是百年心。",""],["溟蒙酥雨足花台，为报春工次第开。\n自是主翁深避俗，不须园吏候人来。","溟濛酥雨足花台，为报春工次第开。\n自是主翁深避俗，不须园吏候人来。"],["坐石援琴一曲馀，隔墙鸣鹤乱池鱼。\n也知识到无声处，绿野堂中恐未如。",""],["写却林塘更写山，墨池终日未曾干。\n非关有意留踪迹，描画平生与后看。","写却林塘更写山，墨池终日未曾乾。\n非关有意留踪迹，描画平生与后看。"],["才说宜休梦也清，杖藜今见几人行。\n昔年丁卯桥边事，别是乾坤一段情。",""],["短草蒙茸花半菲，开门徙倚对春晖。\n野人不解主翁意，谷口年年恨未归。",""],["云隈矮屋压筼筜，风雨时时撼草堂。\n长老相寻谈故事，武侯坐石已非羊。",""],["烂菊垂枝傍竹叉，清芬绝胜弄春花。\n洗觥绕径酣吟赏，为惜西风老岁华。",""],["嫩叶柔条押障青，顿教图画失真形。\n老松怪底生崖壑，不作人家倚屋屏。",""],["凿破寒江活水侵，放船随处是山阴。\n仰天歌罢沧浪曲，落日归鸦已到林。",""],["木节疏疏叶渐繁，果奴千树没人看。\n年来不管浮生计，睡足东窗日几竿。",""],["清风桥头思古人，囊无苏君金百斤。\n田庐仅仅足老我，鸢鱼上下逃形真。",""],["棚花别主自成芳，似待诗狂与酒狂。\n未许悬车消息近，边陲烽火日来忙。",""],["超然台高秋半时，幽香自许幽人知。\n分付西风莫相怨，朝来已放出墙枝。",""],["不让西园景致多，洛中输我老摩挲。\n秪缘恩重怀忧蚤，为倩风篁作浩歌。",""],["位先八座裴公府，家近扁舟范蠡湖。\n见说午桥风骨好，寿时曾入画中无。",""],["冰添渠水分馀润，风到松林却半回。\n进退有机饶自得，更于何处见胚胎。",""],["招隐山头第四泉，坐来深汲见奫然。\n主人一挽天河力，引到方壶已十年。",""],["南山真见北山移，莫怪名家擅两奇。\n好看畦蔬春雨足，许多滋味自家知。",""],["道源深处在人求，分得濂溪别院幽。\n花底酒杯池上钓，年来鱼鸟不相猷。",""],["几年移屋入山深，曾约烟霞老住林。\n悔却出来归已晚，山灵应笑负初心。",""],["云满秋江月满台，江南风景梦中开。\n喜心倒极翻悲壮，一纸家书万里来。",""],["水火都消一念馀，盆池风浪足游鱼。\n眼前有物皆真境，坐到心斋亦自如。",""],["不为南人便北山，白云飞尽泪痕干。\n于今谁在中朝隐，才著冠裳已厌看。","不为南人便北山，白云飞尽泪痕乾。\n于今谁在中朝隐，才著冠裳已厌看。"],["雨回炎毒蚤秋清，瘦马驱驰怯泞行。\n独见晚山归路好，数声高鸟似关情。",""],["三十年过浪食菲，愧无佳句似元晖。\n名园何处追呼赏，不见山公倒载归。",""],["春深谷口种筼筜，莫负坡仙咏雪堂。\n相对若为租税客，不须抵掌笑屠羊。",""],["世路纷纷又几叉，一场春梦一番花。\n经旬溽雨蒸炎毒，怪杀潢污落井华。",""],["览镜翻疑两鬓青，几人尘世解逃形。\n东风不著闲花柳，谁写天真入翠屏。",""],["新竹数茎明月侵，半窗光影半窗阴。\n巡檐欲共分良夜，不学相如赋上林。",""],["灵椿倚屋绿云繁，潦倒停杯一笑看。\n昨夜秋涛新入枕，篷居堪作定风竿。",""],["遭逢此日还此时，一觞一咏谁相知。\n半筵凉月自宾主，不管鸣蝉高树枝。",""],["于今方信墨磨人，岛瘦郊寒郢匠斤。\n检点漫成才百首，知无一字逼唐真。",""],["短壑长松老架芳，潜移谷狠与山狂。\n孤云杳杳飞来鹤，似为诗人索债忙。",""],["见说秋来铁骑多，寒分塞月影摩挲。\n多忧懒作征夫怨，老将知谁解雅歌。",""],["冰盘行菜不厌足，呼童煮茗撑江湖。\n放帘独坐亦自好，门外故人来有无。",""],["鲈鱼苦系张公子，一叶扁舟江上回。\n莫向园丁问生理，于今老鹤几番胎。",""],["谋国吁筹开布泉，涓涓滴滴涴眉然。\n明农若为匡时策，自把犁锄望有年。",""],["榻连午院逐阴移，吟得诗成字字奇。\n客邸情怀归路景，几多心事几相知。",""],["青精饱饭更无求，丈席相期为探幽。\n愧我果为迂拙累，不知何以赞王猷。",""],["独倚寒斋听漏传，宵残烛影月纷然。\n老亲药饵相扶久，二竖销磨报可全。\n有子愿输通籍蚤，事君须念食租前。\n四方志业还家梦，可是湖湘了百年。",""],["重门深深候人立，夜深掩面愁人识。\n机心却笑痴门神，白昼弯弧不相射。\n今年守著屠沽儿，去岁浪说王谢宅。\n门衰门盛神不知，纸上功名殊费力。\n我家破屋无何有，美士入门不见丑。\n今年错把糊上门，邻里儿童尽惊走。",""],["分宴江头春几度，巡檐笑语此宵中。\n万家烟火旧城郭，百里风光今异同。\n暝隔短墙索花品，月移当径问诗筒。\n明朝别有桥山赋，残角声悲接晓钟。",""],["古木青回半夜飔，为添孤愤泣忠词。\n事君正始非时样，落第于今薄主司。\n汗竹已刊身后史，谏垣如见镜中丝。\n燕山秀异多灵物，窦氏诸郎几建祠。",""],["肝肠坎坷日纡萦，落日严祠对古城。\n廷策有怀输蚤见，国忧何意幸终成。\n忠从寒士心逾壮，人到乡闾议更清。\n抱愧不能躬展拜，过门愁听夜乌声。",""],["山麓春云覆黄屋，雨丝脉脉送衰颜。\n忽来归鹤坐松滴，却换野猿啼莫殷。\n几处陵原开别殿，长留弓剑在人间。\n妙香隐隐祠官祝，萧索微臣掩袖还。",""],["年年惯见清明雨，今日恰遭行路中。\n青毡捉襟泣双脚，石燕拂羽迎斜风。\n冢边处处哭新鬼，墙外纷纷飞乱红。\n瘦马冲泥逐光景，眼中细草碧摇空。",""],["短蓑破盖风力弱，从官归骑如行云。\n楚客不厌一宵雨，燕市虚过三月春。\n牧笛远远牛饭去，村鼓逢逢鸡啄群。\n茅檐野老社公语，何日炙背还曛曛。",""],["蓼莪真为横经废，风木应添客枕愁。\n独抱鸣哀诗一卷，可随明月上江楼。",""],["多病床头堆汉史，羁愁梦里入唐诗。\n春风瘦马虔州路，花鸟相看非旧时。",""],["青鞋白氎成小隐，韦曲杜陵称旧家。\n京国不来闲里梦，风霜应放鬓边花。\n朱酡颜驻凭丹药，尺五云高望玉芽。\n恐过十年非渭老，陇梅春信忆天涯。",""],["彭城哭，哭列江，声断还续。\n父沦渊，儿震腹，梦魂何处寻遗躅。\n根原只为天，君足汨罗江，江上行人惄。\n万家儿，万家儿，临风动我彭城哭。",""],["云惨惨，风萧萧，虎皮蒙马尾缠腰。\n黄河赤羽夜半膳，层冰叠作千夫桥。\n蹻腾噬贼孤城下，狼烟猎猎侵寒霄。\n两县四顾无健儿，壮哉二令鼓战频。\n食尽力穷无奈何，义气奋激冲丹田。\n丈夫有死在得所，岂必裹尸归远边。\n肢肉脔喋血如水，瞋目抉裂骂不已。\n君不见上蔡人思霍父母，谁道包瓜本无杞。\n百年春雨老耕犁，儿童识得王平西。\n愧他奔窜终亦死，臭腐自等醯中鸡。\n更无妻子问，向死复何恨。\n本为王家生，亦为王家卒。\n睢州去何远，张许惊再出。\n莫说死何益，莫说生更好。\n生死源头梦一场，秋露泠泠原上草。\n君不见颜杲卿，史官有传名兼收。\n赠官荫子殊恩录，莫作怨鬼丘园啾。",""],["日中楼，楼里日。\n侧轮晃朗碍楼低，疏绮玲珑日出入。\n日在天，自上下，楼倚山云作高架。\n朝朝暮暮送且迎，寸影真逾连璧价。\n此意何所自，有亲白发长居此。\n神仙好楼亲似仙，斑衣不用金与紫。\n日出问授衣，日入还侍侧。\n未信人生一过客，双瞳炯炯漆似黑，日中犹辨丝五色。\n亲年老逼少，子心忧逐喜。\n去日不可回，来日未可拟。\n层楼尚见元宋遗，人过百龄今可几。\n人子心，未可识。\n安得天上人，偷与长生籍，更注亲年应南极。\n楼中有日即有亲，仰歌长笑楚天碧。",""],["白马之良兮，鋈金以为饰兮。\n子观于都兮，予欲为子驭兮。\n白马之骙兮，琢玉以为勒兮。\n子适野兮，予欲执子鞭兮。\n白马之宜兮，亦或仰予秣兮。\n子遨游其何之兮，予为子仆其何痡兮。",""],["有登斯堂仰美人兮，彼美人之情惟意之诚。\n意之诚，斯德之贞。\n是可仰也，必有师也。\n必有友也，必有后之承也。\n有登斯堂怀美人兮，彼美人之降维意之防。\n意之防，斯道之藏。\n是可怀也，惟其师也。\n惟其友也，惟其后之光也。\n有登斯堂慕美人兮，彼美人之诚意足以遁世。\n遁于世，是以无悔。\n是可慕也，何负师也。\n何负友也，何后之人可閟也。",""],["采衣新兮，归子舞于庭兮。\n母兮母兮，寿且贞兮。\n羞子珍兮，子之乐也真兮。",""],["采衣尨兮，归子舞于堂兮。\n母兮母兮，寿且康兮。\n进子觞兮，子之乐也狂兮。",""],["采衣且佩兮，归子舞于堂之背兮。\n母兮母兮，寿且惠兮。\n宴子谖草之树兮，子之乐也遂兮。",""],["瞻彼北堂，采采其谖。\n谖可以忘忧也，母之静也专。\n母心有石，其可镌也。\n瞻彼北堂，森森其柏。\n柏可以依也，母之渊也塞。\n母家有政，其可国也。\n瞻彼北堂，有松有竹。\n有松有竹，母之鬈也绿。\n彼天之寿，眷兹平格。\n彼孝子心，永言式谷。",""],["天生圣人，为民立极。\n六合顺轨，九围承式。\n惟辟奉天，惟以乂民。\n民物乃康，祥祯聿臻。\n于赫圣皇，允惟民主。\n仁覆普天，德超邃古。\n时维仲冬，雨雪愆期。\n圣心恻然，轸我民饥。\n曰灾所由，厥咎在朕。\n我其躬祷，为民请命。\n斋肃郊坛，庭燎有辉。\n大君戾止，淠淠龙旗。\n既类既旅，对越在上。\n神监孔昭，锡之灵贶。\n始自西北，有渰浮浮。\n迨于既夕，望之油油。\n诘旦礼成，雪霰交集。\n飞若玉屑，化为琼液。\n匪亟匪徐，巧当其时。\n惟帝克诚，昭假不迟。\n弥望皑皑，藏污掩慝。\n其令所加，岁无螟蜷。\n既沾既足，我亩我疆。\n其兆维何，丰年穰穰。\n颂声载路，既阜民生，乃永皇祚。\n勿谓蚩蚩，民惟邦畿。\n勿谓茫茫，天高听卑。\n天难忱斯，惟德是保。\n惟皇祗德，奉若天道。\n厥德不回，受禄于天。\n臣拜稽首，天子万年。","天生圣人，为民立极。\n六合顺轨，九围承式。\n惟辟奉天，惟以乂民。\n民物乃康，祥祯聿臻。\n于赫圣皇，允惟民主。\n仁覆普天，德超邃古。\n时维仲冬，雨雪愆期。\n圣心恻然，轸我民饥。\n曰灾所由，厥咎在朕。\n我其躬祷，为民请命。\n斋肃郊坛，庭燎有辉。\n大君戾止，淠淠龙旂。\n既类既旅，对越在上。\n神监孔昭，锡之灵贶。\n始自西北，有渰浮浮。\n迨于既夕，望之油油。\n诘旦礼成，雪霰交集。\n飞若玉屑，化为琼液。\n匪亟匪徐，巧当其时。\n惟帝克诚，昭假不迟。\n弥望皑皑，藏污掩慝。\n其令所加，岁无螟蜷。\n既沾既足，我亩我疆。\n其兆维何，丰年穰穰。\n颂声载路，既阜民生，乃永皇祚。\n勿谓蚩蚩，民惟邦畿。\n勿谓茫茫，天高听卑。\n天难忱斯，惟德是保。\n惟皇祗德，奉若天道。\n厥德不回，受禄于天。\n臣拜稽首，天子万年。"],["孤舟投野宿，客睡何曾牢。\n起坐候明发，去意又滔滔。\n雾深埋虎豹，峡坼睡鼍鳌。\n况乃风水恶，舟行牵挽劳。\n叹息谓役夫，吾应愧尔曹。",""],["爰作斯室，习卜之吉。\n基之构之，以燕以翼。\n君子于居，以食以息。\n彼后也贤思，弗坠于绩。\n爰作斯堂，抡木之良。\n曰梓曰楠，曰百其章，斯工斯臧。\n君子于居，咏笑且扬。\n彼后也昌思，有缉于光。\n爰作斯门，于河之坟。\n有焕其文，有岸其枨。\n车也斯屯，马也斯奔。\n君子之德之存，彼后也蕃。\n于公之子，于公之孙。",""],["欲别执君手，君行忆侬否。\n日暮愁翻飞，江头立搔首。\n山回人不见，风帆出高柳。\n明明尧舜朝，此别岂应有。\n愿子竭忠赤，益酬主恩厚。\n往事何足论，逢人须闭口。\n葳蕤菊与兰，岁晏还相守。\n无令秋霜至，摧没随藜莠。",""],["申甫不可作，二疏迹难追。\n公家贤弟昆，视之奚愧为。\n名满天地间，身在云水涯。\n譬彼双凤凰，高翔不可羁。\n我愿采芳菊，泛彼黄金卮。\n云端托飞鸟，为我往遗之。\n斯以制颓龄，永为国羽仪。\n幸此未暮年，起佐休明时。\n勋华正在御，邈哉皋与夔。",""],["五峰高，五峰高。\n肤寸雨天下，桔槔胡尔劳。\n萧萧风木增悲号，人生踪迹殊蓬蒿。",""],["芗溪清，芗溪清。\n年光似昼夜，一涸复一盈。\n从今霜月乌啼更，莫使哀哀孝子听。",""],["鹤鸣皋兮奚求，羽毨兮惟修。\n衣玉雪兮云岫，濯江波兮月洲。\n有丹渥兮莫售，巢老松兮惊髯虬。\n烟萝风籁兮与?，高轩乘兮胫之羞。\n青田有子兮方岁周，和鸣唳兮九秋。\n连翮干霄兮清都，游绦旋光兮仪收。\n投饵饼兮不受，引吭而嘎兮悲啾。\n㧐身奋翼兮向南州，回翔兮故丘。\n老稚往观兮夷犹，江夏有楼兮栖休。\n飞上下兮天光流，露滴兮发萧幽。\n玄圃开而舞鹿兮呦呦，仙子跨兮翱游。\n白而苍兮斯寿，子来兮来兮，偕凤兮鸣周。","鹤鸣皋兮奚求，羽毨兮惟脩。\n衣玉雪兮云岫，濯江波兮月洲。\n有丹渥兮莫售，巢老松兮惊髯虬。\n烟萝风籁兮与?，高轩乘兮胫之羞。\n青田有子兮方岁周，和鸣唳兮九秋。\n连翮干霄兮清都，游绦旋光兮仪收。\n投饵饼兮不受，引吭而嘎兮悲啾。\n㩳身奋翼兮向南州，回翔兮故丘。\n老稚往观兮夷犹，江夏有楼兮栖休。\n飞上下兮天光流，露滴兮发萧幽。\n玄圃开而舞鹿兮呦呦，仙子跨兮翱游。\n白而苍兮斯寿，子来兮来兮，偕凤兮鸣周。"],["嗟岐路之欹倾兮，胡追逐而缤纷。\n舟放楫兮山之岑，车错毂兮江之𣸣。\n直夫后皇之易化兮，兰萎畹而树榛。\n跃健马兮腰垂弸，嘅燕赵之慷慨兮不若古，生兹毒丑兮熟与衡。\n畎亩战场兮耒耜，兵鼓坎坎兮云征。\n血腻草兮和雨腥，沆?千里兮无完城。\n羌守臣之引咎兮，脱簪组而自絇。\n刑探饴而思恍怆兮，噤咭隔而谁语。\n天子明见兮时艰尔处，符匪专握兮囷械乃茹。\n驱犬羊兮抟翼虎，戢若勚兮准若辜。\n事靡盬兮旋复而所。\n揽涕泪而感旷荡兮无涯，夜耿耿兮不寐。\n思奋报兮帅厉，神歘忽兮天之际。\n铁鏦铮兮马嘶，惊觉兮舞昌被。\n如醉兮如痴，日坎廪兮天子知。\n噫是贞坚兮拂所施，无抑郁以毙兮徒伤悲。\n有涣命兮允归，康复泰兮秉机，知?负初兮夫奚疑归。\n分归兮九秋，风瑟瑟兮潦水收。\n木叶下兮寒露绸，旋车兮道之周。\n雁廱廱兮南幽，蟋蟀宵征兮啾啾。\n容与兮夷犹，心摇摇兮禾黍丘。\n仰象魏兮在袖，岂长往兮叹休。\n巫山高兮云依，峡水清兮星移。\n方有书兮药有苗，师赤松兮友子乔。\n身健便兮拟嫖姚，徙倚夷兮逍遥。\n蕙可佩兮芰可衣，鹤和鸣兮鸥狎飞。\n毋曰乐憺憺兮将忘机。\n超氛埃兮淑丽，贞臣匪放兮省疚瘵之希微。\n发种种兮飒如其稀，心怦怦兮如遗。\n有梦兮不违，有坐兮向墀。\n居高兮体卑，哀剥落兮方离。\n披鸟敛翼兮欲安栖，绸缪桑土兮胡尔迟。\n恩衔义结兮草木知，将感召而来兮天朝羽仪。","嗟岐路之欹倾兮，胡追逐而缤纷。\n舟放楫兮山之岑，车错毂兮江之濆。\n直夫后皇之易化兮，兰萎畹而树榛。\n跃健马兮腰垂弸，嘅燕赵之慷慨兮不若古，生兹毒丑兮熟与衡。\n畎亩战场兮耒耜，兵鼓坎坎兮云征。\n血腻草兮和雨腥，沆?千里兮无完城。\n羌守臣之引咎兮，脱簪组而自絇。\n刑探饴而思恍怆兮，噤咭隔而谁语。\n天子明见兮时艰尔处，符匪专握兮囷械乃茹。\n驱犬羊兮抟翼虎，戢若勚兮准若辜。\n事靡盬兮旋复而所。\n揽涕泪而感旷荡兮无涯，夜耿耿兮不寐。\n思奋报兮帅厉，神歘忽兮天之际。\n铁鏦铮兮马嘶，惊觉兮舞昌被。\n如醉兮如痴，日坎廪兮天子知。\n噫是贞坚兮拂所施，无抑郁以毙兮徒伤悲。\n有涣命兮允归，康复泰兮秉机，知?负初兮夫奚疑归。\n分归兮九秋，风瑟瑟兮潦水收。\n木叶下兮寒露绸，旋车兮道之周。\n雁廱廱兮南幽，蟋蟀宵征兮啾啾。\n容与兮夷犹，心摇摇兮禾黍丘。\n仰象魏兮在袖，岂长往兮叹休。\n巫山高兮云依，峡水清兮星移。\n方有书兮药有苗，师赤松兮友子乔。\n身健便兮拟嫖姚，徙倚夷兮逍遥。\n蕙可佩兮芰可衣，鹤和鸣兮鸥狎飞。\n毋曰乐憺憺兮将忘机。\n超氛埃兮淑丽，贞臣匪放兮省疚瘵之希微。\n发种种兮飒如其稀，心怦怦兮如遗。\n有梦兮不违，有坐兮向墀。\n居高兮体卑，哀剥落兮方离。\n披鸟敛翼兮欲安栖，绸缪桑土兮胡尔迟。\n恩衔义结兮草木知，将感召而来兮天朝羽仪。"],["萧萧寒雨对高秋，寂寂空床拥敝裘。\n归去钧天频有梦，挽回沧海独无谋。\n平生颇诧任公子，末路方思马少游。\n珍重故人招隐意，草堂南郭可淹留。",""],["长陵西接黄花镇，白雪苍岩夜色遥。\n阴殿衮龙犹在目，往时松柏已干霄。\n总闻一怒风尘起，想见千官迁次朝。\n怅极两京兴废事，小山何意起渔樵。",""],["昔我童稚年，闻子才名振。\n丽藻擅词坛，波涛惊笔阵。\n虽云网罗密，有才反见摈。\n别来岁几何，忽讶繁霜鬓。\n鱼目俗所珍，孰辨瑜与瑾。\n今子领儒绅，道德师后进。\n此中一青毡，不博王侯印。\n修途自此始，往哉幸加慎。\n他日能相思，尺书通问讯。","昔我童稚年，闻子才名振。\n丽藻擅词坛，波涛惊笔阵。\n虽云网罗密，有才反见摈。\n别来岁几何，忽讶繁霜鬓。\n鱼目俗所珍，孰辨瑜与瑾。\n今子领儒绅，道德师后进。\n此中一青毡，不博王侯印。\n脩途自此始，往哉幸加慎。\n他日能相思，尺书通问讯。"],["秋宇澹无云，荧荧河汉长。\n街头人语寂，明月照我床。\n客子夜不寐，揽衣起徬徨。\n中庭凉露积，绕砌鸣寒螀。\n因之百感集，中宵涕沾裳。\n江南八月交，稻熟已堪尝。\n况复秋风起，还忆鲈鱼乡。\n朋友讶不归，寄我书数行。\n为言东邻叟，相约候耕桑。\n岂不念离居，时哉未忍忘。\n誓将拂衣去，回首市尘黄。",""],["望望城南隅，彩云凝不飞。\n金舆游幸地，万马争驱驰。\n马前拥才人，校猎勇如罴。\n一箭落飞鸟，重赏穷民脂。\n中有射雕将，姓名知为谁。\n百金换一狐，马首络青丝。\n臂弓更腰箭，突击纵所为。\n一从恃宠爱，立致倾国赀。\n威势何翕烈，顾盼生陆离。\n君看草头露，转瞬尽朝曦。\n因风致危词，彼昏恐不知。",""],["忆醉杏园春，近在廿载前。\n朋旧忽寥落，参辰各一天。\n有客蓬岛姿，来泛辽海边。\n相逢解岑寂，令我心豁然。\n念子初仕时，潇洒禁中仙。\n俄迁江上群，佳政早流传。\n一从登宪府，荏苒将十年。\n今复辞京阙，远上河洛船。\n秋蝉号衰柳，暮鸟冲寒烟。\n惆怅从兹分，莽莽隔山川。\n远役何足悲，修途愿勉旃。\n无令壮心摧，赠子以龙泉。","忆醉杏园春，近在廿载前。\n朋旧忽寥落，参辰各一天。\n有客蓬岛姿，来泛辽海边。\n相逢解岑寂，令我心豁然。\n念子初仕时，潇洒禁中仙。\n俄迁江上群，佳政早流传。\n一从登宪府，荏苒将十年。\n今复辞京阙，远上河洛船。\n秋蝉号衰柳，暮鸟冲寒烟。\n惆怅从兹分，莽莽隔山川。\n远役何足悲，脩途愿勉旃。\n无令壮心摧，赠子以龙泉。"],["新安文献郡，君家独推先。\n衣冠萃一门，金玉清相联。\n卓哉司马公，清白自家传。\n功名三十载，持节多在边。\n虎符归把握，龙敕屡传宣。\n允称丝纶命，何惭报答年。\n以兹结主知，华要地频迁。\n貤荣三锡命，恩霈及重泉。\n璀璨琅函重，淋漓御墨鲜。\n感兹时展读，珍重托瑶篇。\n我观潘夫子，忠孝道两全。\n勖哉图令终，庶以企前贤。",""],["终日困羁旅，驱马出城𬮱。\n折简辱招游，感子故意真。\n谁家好池馆，金张帝室姻。\n入门金奏作，歌舞掩比邻。\n劝客琥珀杯，坐客锦绣茵。\n复具麒麟脯，充此盘中珍。\n是日天气和，微风吹白苹。\n林深鸣好鸟，水浅见修鳞。\n小浦容舟入，遥山隔座新。\n我来纵游览，已足浣心尘。\n况复同胞友，语笑情弥亲。\n于兹不痛饮，落花笑杀人。\n他年江海上，相望参与辰。","终日困羁旅，驱马出城闉。\n折简辱招游，感子故意真。\n谁家好池馆，金张帝室姻。\n入门金奏作，歌舞掩比邻。\n劝客琥珀杯，坐客锦绣茵。\n复具麒麟脯，充此盘中珍。\n是日天气和，微风吹白蘋。\n林深鸣好鸟，水浅见脩鳞。\n小浦容舟入，遥山隔座新。\n我来纵游览，已足浣心尘。\n况复同胞友，语笑情弥亲。\n于兹不痛饮，落花笑杀人。\n他年江海上，相望参与辰。"],["忆昔同登科，相好如弟昆。\n回首祗昨日，倏更廿寒温。\n中间几聚散，风雨最销魂。\n今我偶南来，而子复北辕。\n临岐重执手，恻恻夫何言。\n祖道值春晚，落花拥篱根。\n何以赠远行，采拟思芳荪。\n夫子玉堂英，词赋陋文园。\n今去定承宠，重上金马门。\n同时持橐入，借问今谁存。\n江水日东注，羲和忽西奔。\n愿子早登庸，捐躯答至尊。\n俊也下驽才，恐负海岳恩。\n别来各努力，馀事置勿论。",""],["长安帝王都，仕路此通津。\n冠盖满朝省，共喜侍龙鳞。\n之子胡不乐，念我白头亲。\n引领城南隅，凄然独伤神。\n尺疏回天听，稽首颂皇仁。\n喜深起沉疾，解棹潞河滨。\n行当慰倚闾，一笑慈颜春。\n我昔客金陵，怜渠风物新。\n江流抱城郭，山翠落衣巾。\n且言丽晨旭，瑶街净纤尘。\n形胜冠全吴，气候近吾闽。\n白鱼兼紫笋，调膳足羞珍。\n由来天性乐，外物莫比伦。\n君亲岂有异，孝子亦忠臣。\n绝裾应府辟，彼哉温太真。",""],["怪底严寒候，花飞遍八荒。\n人皆欣岁事，我更念戎行。\n陇麦萌应绿，江云色半苍。\n从来感格意，不在走群望。",""],["三白呈祥日，群黎引领时。\n轻随柳絮舞，润许麦苗知。\n郢上惭高调，山阴负宿奇。\n祗应且饱饭，歌舞答恩私。",""],["细雨梧桐外，萧然草阁秋。\n病馀还药石，梦里只松楸。\n世事看多丑，妻孥劝早休。\n不愁生计薄，万卷是良畴。",""],["因悲乡井异，寓目思纷纷。\n野店没青草，山田种白云。\n雨声连晦朔，日色变朝曛。\n道有疮痍者，大安异所闻。",""],["射策占高名，分符镇列城。\n军声千里振，智术万人惊。\n坐拥青油幕，行巡细柳营。\n祗今须将略，慎勿厌谈兵。",""],["兵法满胸中，奇谋妙折冲。\n共荣分阃寄，还拟取侯封。\n落日明旌旆，飞霜上剑锋。\n即看残寇灭，销甲事春农。",""],["天低垂户外，斗转宿城阴。\n卧病抛书卷，偷闲解佩衿。\n坐怜明月近，梦破白云深。\n正尔愁岑寂，钟声出暮林。","天低垂户外，斗转宿城阴。\n卧病抛书卷，偷閒解佩衿。\n坐怜明月近，梦破白云深。\n正尔愁岑寂，钟声出暮林。"],["百里昌平道，停车日未昏。\n浮生浑作梦，旧事复谁论。\n山色围平野，溪流抱独村。\n向来征战地，营垒到今存。",""],["林密青相戛，山空翠欲流。\n吹箫何处客，日暮未归舟。",""],["先生海内称儒宗，气格不与俗人同。\n晚以著书为寔历，道着利名面已红。\n今者抗疏辞天子，拂衣去伴商山翁。\n我歌送之感且叹，却惭羽翼在樊笼。\n豫愁别后知音少，临分更为抚丝桐。\n曲终酒罢各分手，冷冷江上多清风。",""],["忆昔联舟下江水，月明杯酒吴江中。\n十五年来浑一梦，几回念我枉诗筒。\n今我不乐岁又暮，思君空伫南飞鸿。\n近闻解印谢尘鞅，头白颓然成老翁。\n闲来只辨江心水，汲取烹茶陆羽同。\n我似相如多渴病，每日视草明光宫。\n安得就君分一勺，坐遣胸中臆虑空。\n诗成对雨支颐坐，冷风飒飒鬓双蓬。","忆昔联舟下江水，月明杯酒吴江中。\n十五年来浑一梦，几回念我枉诗筒。\n今我不乐岁又暮，思君空伫南飞鸿。\n近闻解印谢尘鞅，头白颓然成老翁。\n閒来只辨江心水，汲取烹茶陆羽同。\n我似相如多渴病，每日视草明光宫。\n安得就君分一勺，坐遣胸中臆虑空。\n诗成对雨支颐坐，冷风飒飒鬓双蓬。"],["我昔与子投气分，爱子胸襟无俗韵。\n几岁为郎坐粉闱，一麾出守还山郡。\n郡城楼阁枕山巅，二水交流汇其前。\n近郭千家灯火市，缘溪万顷桑麻田。\n比闻凋敝渐非古，恺悌今逢贤府主。\n敷政还回列县春，洗冤更有随车雨。\n闽中道脉却在兹，城南尚有延平祠。\n祠下溪毛清可摘，门墙仰止有馀师。",""],["公昔官居学士院，承恩数上金銮殿。\n一从休直下西清，南国山川题欲遍。\n迩来宵旰劳天颜，已闻下诏征公还。\n江上空怀鸥鹭侣，朝端定接夔龙班。\n偶逢菊节开芳饯，极目烟波锦帆远。\n心如江水只流东，节比黄花偏耐晚。\n簪笔重看侍讲帏，凤池挥翰迅如飞。\n更欲烦公经纬手，殷勤为补山龙衣。","公昔官居学士院，承恩数上金銮殿。\n一从休直下西清，南国山川题欲遍。\n迩来宵旰劳天颜，已闻下诏徵公还。\n江上空怀鸥鹭侣，朝端定接夔龙班。\n偶逢菊节开芳饯，极目烟波锦帆远。\n心如江水只流东，节比黄花偏耐晚。\n簪笔重看侍讲帏，凤池挥翰迅如飞。\n更欲烦公经纬手，殷勤为补山龙衣。"],["落日满川春树晴，东风江上锦帆轻。\n把袂问公从此别，几时棹返石头城。\n石城楼阁烟花绕，公在江湖忧廊庙。\n谁云卧洛似富韩，共言分陜同周召。\n三年报政拜彤墀，正是重瞳注想时。\n宣室倘承前席问，东南赤子多疮痍。\n疮痍满目何时愈，便合留公辅明主。\n白云休恋故山栖，海内苍生望霖雨。",""],["琐闼仙郎冰玉姿，襟怀好似杜拾遗。\n孤忠时上皂囊疏，馀兴春吟白雪诗。\n南国三年行报政，倾城饯送车马盛。\n几番飞梦绕亲闱，彩衣今喜逢家庆。\n春酒高堂何限情，东风引棹上玉京。\n晓漏还随鹓鹭入，朝阳共听凤凰鸣。\n圣皇纳谏同尧舜，山甫之职当补衮。\n君看千年青史上，惟有忠孝流声远。",""],["东吴之山虞山高，秀拔众山谁与伍。\n终日出云遂为霏，利泽在人惠良溥。\n公之奇秀自岳降，貌似古人心更古。\n仕途坎壈三十年，晚始拥旄开制府。\n先声想已到百城，楚女越童争歌舞。\n彩幡风暖春行县，画戟霜飞秋按部。\n闾阎从此无疮痍，道路还闻息豺虎。\n我老为儒迂且腐，日给太仓惭何补。\n祝公惟愿政有成，早晚还朝事明主。",""],["博平郡守太丘孙，粉署为郎名蔼蔼。\n公退闭门谢俗氛，其中有草生书带。\n矫如冬寒挺孤松，清比秋蟾印溪濑。\n北都艺苑职校抡，何限贤豪归盻睐。\n望重清时久见推，恩深大郡俄超拜。\n共言才可济时艰，却喜身还随道泰。\n南浦离筵芳草边，故人班马垂杨外。\n杯倾春酿休辞醉，鱼出寒冰兼可脍。\n升平海内官府乐，澶漫山东疆域大。\n南通舟楫控江淮，东望山川连海岱。\n赴官谁不羡朱轮，作县人争瞻皂盖。\n闾阎憔悴今应苏，使君岂弟民所赖。\n淮阳卧治还有成，颖川课职当居最。\n一麾岂足为君淹，钟鼎勋名端可蔡。",""],["我昔官居白玉堂，五更振佩朝明光。\n君之先人司喉舌，献纳从容在帝旁。\n每见殿东供奉退，凤仪秀拔重班行。\n自我不见今十载，伤心耆旧半存亡。\n君才不忝名家胄，法冠豸服何辉煌。\n弭节留都刚会面，又闻奏最上江艎。\n闪闪旌旗辉白日，明明画戟飞秋霜。\n行处想应无豺虎，山妖水怪尽逃藏。\n比闻处处鬻男女，江南江北多旱蝗。\n官府诛求何日已，闾阎百孔兼千疮。\n我曹肉食惭无补，言之感激热中肠。\n君侯忠孝夙自许，触目民隐心悲伤。\n此去应前宣室席，愿无缄默负吾皇。\n临分不尽叮咛语，意逐东流江水长。","我昔官居白玉堂，五更振佩朝明光。\n君之先人司喉舌，献纳从容在帝旁。\n每见殿东供奉退，凤仪秀拔重班行。\n自我不见今十载，伤心耆旧半存亡。\n君才不忝名家胄，法冠豸服何辉煌。\n弭节留都刚会面，又闻奏最上江艎。\n闪闪旌旂辉白日，明明画戟飞秋霜。\n行处想应无豺虎，山妖水怪尽逃藏。\n比闻处处鬻男女，江南江北多旱蝗。\n官府诛求何日已，闾阎百孔兼千疮。\n我曹肉食惭无补，言之感激热中肠。\n君侯忠孝夙自许，触目民隐心悲伤。\n此去应前宣室席，愿无缄默负吾皇。\n临分不尽叮咛语，意逐东流江水长。"],["丁君自是东吴英，读书多似郑康成。\n夜光暗掷无人识，西丘结屋学逃名。\n虽曾荐起至王国，鲈鱼味好薄侯鲭。\n伊昔汉五侯，气势何翕烈。\n子云之笔札，君卿之唇舌，出入门下附炎热。\n当时裘马虽轻肥，惜哉白圭已玷缺。\n岂若西丘短褐骑羸马，来往江湖自潇洒。\n短刺不投公府中，长裾耻曳侯门下。\n今年金陵初识面，爱子风情何邈缅。\n玉麈高谈坐为倾，彩毫题句人皆羡。\n凤凰台，白鹭洲，南朝古寺都游遍。\n一朝兴尽忽辞归，向我索诗入行卷。\n君行君行慎勉旃，他日试看高士传。",""],["芉原分手太匆匆，却喜今朝语笑同。\n尽日舟行山色里，几家人住水声中。\n江湖自笑长为客，齿发那能久不翁。\n明日停桡武夷下，细将真诀问崆峒。",""],["几回来往建州道，下马逢人说好官。\n一见又为天外别，相逢真似梦中看。\n雷霆入地惊湍吼，虎豹蹲林乱石攒。\n我昔仗君曾脱险，追思珠泪不胜弹。",""],["我因作宦多江海，汝亦离乡几岁华。\n细检来书同会面，暂随归梦一还家。\n莲开驿舍清风远，柳发河桥别思赊。\n早晚剑津系舟楫，可能相候夕阳斜。",""],["帝城瑞气晓氤氲，凤阁参差势入云。\n驰道争闻传警跸，垂衣重见拱华勋。\n仗移雉尾班初合，身近螭坳诏得闻。\n薄劣十年叨侍从，自惭何以答明君。",""],["寻常送客不曾悲，送尔停杯惜别离。\n作倅正当山水郡，致身真负圣明时。\n百年富贵非吾愿，前辈风流是汝师。\n涉世久知才有用，岂同侪叔众嫌痴。",""],["禁城残雪未全消，又见春归到柳条。\n乡国忽惊魂梦断，风尘暗遣鬓毛凋。\n一尊得醉聊开口，五斗虽贫耻折腰。\n自爱木兰好烟水，赋归不用小山招。",""],["中左门间坐讲臣，九霄地切侍龙鳞。\n礼成湛露开周燕，泽普濡云识舜仁。\n翠管细传仙乐曲，瑶盘频送御厨珍。\n小臣既醉歌天保，愿祝皇图亿万春。",""],["佐郡南州旧有声，一麾今去领专城。\n铃斋昼静留高咏，稻垄春晴看耦耕。\n圣代淳风无楚越，汉廷良吏尽公卿。\n君才不止二千石，拭目云霄万里程。",""],["羡君此去际芳辰，南浦歌残草色新。\n供奉再通中禁籍，飞腾不负百年身。\n久闻西北驰边报，又道东南备徼巡。\n廊庙可忧非一事，纳忠元属谏垣臣。",""],["抗疏清朝辞好官，一麾谪去远龙颜。\n朋簪聚散萍蓬外，仕路升沉梦寐间。\n秘阁共嗟刘向去，长沙终见贾生还。\n君恩随地堪酬答，莫羡逍遥侍从班。",""],["樽前把袖日初斜，共指江潭去路赊。\n送客不堪逢岁杪，缄诗何惜到京华。\n洞庭天阔云垂野，湘浦秋深雁泛沙。\n圣代祗今贤是宝，莫教地产止丹砂。",""],["一区深坞可藏春，卢橘杨梅次第新。\n九陌风尘不到地，百年云水自由身。\n轩中留客惟棋局，枕上看山亦葛巾。\n闻说藏书馀万卷，青云还属后来人。",""],["竹林风日不同游，又向江头问去舟。\n天地百年皆逆旅，风烟五岭亦中州。\n树深云锁千岩暝，水阔天连一雁秋。\n闻说随身多药饵，用时须向古方求。",""],["莫言人世重依违，青史他年有是非。\n贾子忧时聊短疏，屈平直道是危机。\n偏州谪倅衣冠惜，三楚经行草木辉。\n从此召还知有日，别君何事更沾衣。",""],["江村花柳春犹浅，水郭亭台日正迟。\n幔卷暂教山翠入，尊开侧见竹光移。\n朝簪未许真抛得，杯酒应拼与醉期。\n况是同游无俗侣，凭君更续旧题诗。","江村花柳春犹浅，水郭亭台日正迟。\n幔卷暂教山翠入，尊开侧见竹光移。\n朝簪未许真抛得，杯酒应拚与醉期。\n况是同游无俗侣，凭君更续旧题诗。"],["东南紫气郁葱葱，清跸时劳下九重。\n花夹绮罗通御道，旗分龙虎盛军容。\n三秋鱼鸟惊天仗，万国衣冠翊圣躬。\n尽说归来罢巡狩，已闻中诏撤行宫。",""],["长亭日暮酒初醒，策马西风问去程。\n几处啼猿催客泪，满林落叶送秋声。\n鸣笳昼寂狼烟净，贡篚东来鸭绿平。\n灯火万家弦管沸，不知辽海是边城。",""],["踪迹城山近已稀，重来游衍暮忘归。\n高台突兀凌虚白，古刹荒凉隐翠微。\n上界僧归梵磬响，低林鸟宿佛灯辉。\n迩来自觉尘缘薄，不为入山不息机。",""],["古木修篁护小轩，溪云谷鸟伴闲眠。\n烟花冉冉骄阳月，风雨潇潇寒食天。\n行役敢辞南又北，憩居真以日为年。\n偶逢故旧开官酝，一饮直须吸百川。","古木脩篁护小轩，溪云谷鸟伴閒眠。\n烟花冉冉骄阳月，风雨潇潇寒食天。\n行役敢辞南又北，憩居真以日为年。\n偶逢故旧开官酝，一饮直须吸百川。"],["年资端与望俱深，况复名高翰墨林。\n地远梦回青琐闼，官清吟对紫薇阴。\n庙堂尚赖经邦手，江海常悬补衮心。\n最是越中山水好，公馀何惜暂登临。",""],["河桥欲别惜分违，把袂相看到夕晖。\n好向一官思报称，愿从同榜借光辉。\n青青草色留人醉，片片杨花逐马飞。\n此景不堪频怅恋，岭民翘首望君归。",""],["高怀偶与碧山俱，吟对钤冈兴有馀。\n小阁乍开延紫翠，层楼遥望入清虚。\n一帘树色留啼鸟，万卷芸香避蠹鱼。\n仰止定知闻道早，宫墙咫尺圣人居。",""],["柳绿莺啼二月天，家家门外泊湖船。\n伤心世事随流水，回首春风又隔年。\n客路红尘心半染，亲坟宿草恨长牵。\n亦知温饱非吾事，负郭何须二顷田。",""],["石榴有子兆开先，况复来从雨露边。\n一座惊看无似者，诸公持赠不徒然。\n家如王祐多阴德，齿及商瞿未暮年。\n见说近来兰入梦，试看明月掌珠圆。",""],["作宦浔阳兴亦佳，不须勾漏问丹砂。\n水当县郭时时白，山倚江城面面遮。\n民醉却逢终日社，官闲每放午时衙。\n使君自是今潘岳，试看河阳一县花。","作宦浔阳兴亦佳，不须勾漏问丹砂。\n水当县郭时时白，山倚江城面面遮。\n民醉却逢终日社，官閒每放午时衙。\n使君自是今潘岳，试看河阳一县花。"],["秋来风物总堪悲，寂寞空斋独坐时。\n霜气暗凋门柳色，露华寒动井梧枝。\n才非用世归须早，事不萦心起每迟。\n更欲移家深竹里，不教姓字俗人知。",""],["年年问讯乡园使，齿发祗如初别时。\n共喜承恩当晚暮，曾闻卜寿过期颐。\n三餐不换公卿贵，内行还堪族党归。\n凭仗春风阶下竹，平安长报客边知。",""],["新诗读罢烛频弹，东壁垂光照夜阑。\n已有声名高谏院，况兼风雅擅骚坛。\n心降合作低头拜，病起还思洗眼看。\n巴客纵能歌下里，其如郢曲和皆难。",""],["肃肃千门虎旅屯，月斜剑佩影初分。\n钧天乐奏万年曲，宝鼎烟腾五色云。\n杳窱金闺清漏转，圣明天语近臣闻。\n太平时节身难遇，万国同心祝圣君。",""],["使星何处照人红，路指江陵汉水东。\n旌节晓看冲朔雾，楼船秋喜借湖风。\n威仪汉室原存庙，礼乐虞廷重秩宗。\n何限疮痍吴楚道，烦公细采达重瞳。",""],["昔年湖上访茅庐，五月扁舟过雨初。\n旧事怪来连夕梦，故人别后几封书。\n新迁涵水鸣珂里，何异庚桑畏垒居。\n我拟官成赋归去，卜邻相伴老樵渔。",""],["怜君垂老涉鲸波，落日风烟奈别何。\n睡石江头秋月冷，分茅岭上瘴云多。\n蛮乡酒熟何人共，海国书来有雁过。\n岂是天涯成远别，出门回首限山河。",""],["对君强饮不成欢，连日眉尖别思攒。\n两鬓十年非故貌，一身万里更微官。\n风尘为客吾将老，世路无媒古亦难。\n相约抽身早归隐，木兰烟水有渔竿。",""],["万里苍梧书未还，时占剑气斗牛间。\n君才雅称名藩牧，我病犹惭近侍班。\n世事浮沤曾足问，人生黑发未容闲。\n诗成寄寿凭归翼，目断寒云隔万山。","万里苍梧书未还，时占剑气斗牛间。\n君才雅称名藩牧，我病犹惭近侍班。\n世事浮沤曾足问，人生黑发未容閒。\n诗成寄寿凭归翼，目断寒云隔万山。"],["官联八座望尤崇，凶讣俄传叹息同。\n屡触雷霆惊壮节，终垂日月照遗忠。\n山中续食清廉吏，身后易名简肃公。\n感旧怀贤嗟莫及，凄然泪洒向西风。",""],["几度人来报使旌，暗中吾自数归程。\n相逢岁晚翻疑梦，忍说春来又卜行。\n风雨幽怀何处写，江天病眼此时明。\n夜来春意知多少，步到前庭问紫荆。",""],["观风南楚人犹羡，领邑东瓯尔自知。\n冻合遥空辞我地，春回满县到官时。\n事于忙后宜防错，言向甜中恐售欺。\n岁岁东风池草绿，梦中相忆自成诗。",""],["离亭客散夕阳低，江树依依送马蹄。\n但使云缄无断续，不妨尘迹各东西。\n春山雨过蛮溪涨，晓岸花开越鸟啼。\n我有一言君记取，归装南物不须携。",""],["忆在武夷同醉日，感君高韵薄秋云。\n今来手握山东宪，众许才空冀北群。\n尘世浮名春梦似，玉堂旧话夜灯闻。\n年来鬓发俱非昨，要遣丹青早策勋。",""],["年来百事不堪论，独得山游兴尚存。\n千里钟声疑有寺，数家烟火自成村。\n秋高树有凌霜叶，水落沙仍带雨痕。\n最与乡园相似处，几株残柳对柴门。",""],["晓日争看汉使旌，衣冠祖饯欲倾城。\n回瞻北极心应恋，归见终南眼倍明。\n驷马今过题柱处，关人旧识弃𦈡生。\n倚门应念亲头白，不独归为昼锦荣。","晓日争看汉使旌，衣冠祖饯欲倾城。\n回瞻北极心应恋，归见终南眼倍明。\n驷马今过题柱处，关人旧识弃繻生。\n倚门应念亲头白，不独归为昼锦荣。"],["柴门寂寂昼长扃，苑树移阴霜满庭。\n共许登堂论契阔，今来立马叹伶俜。\n朝中旧恨平津阁，湖上清风孺子亭。\n试向沧浪问渔父，此时还有几人醒。",""],["倦来散步绕池行，池上风生白苎轻。\n春雨小堂留燕语，夕阳高柳逗蝉声。\n杯深向客难同醉，梦熟何人却唤醒。\n可是闲官无限乐，官坊翰苑总登瀛。","倦来散步绕池行，池上风生白苧轻。\n春雨小堂留燕语，夕阳高柳逗蝉声。\n杯深向客难同醉，梦熟何人却唤醒。\n可是閒官无限乐，官坊翰苑总登瀛。"],["冯唐头白尚为郎，觉尔旌麾去有光。\n共羡骅骝今展足，谁怜鸿雁各分行。\n西湖春近梅先白，上国秋初叶已黄。\n惆怅彭城离别地，几时风雨复连床。",""],["天曹最绩奏神京，望重三朝属老成。\n江上晓云侵旆湿，梅边腊雪照船明。\n人传左右虚台席，帝眷尚书识履声。\n共喜兹行归鼎轴，致君应见世升平。",""],["马首风尘苦未休，三年刚得此回游。\n树藏宿雾迷宫苑，水绕平堤接御沟。\n黄犊眠来千嶂晚，翠禽啼断半溪秋。\n多情更有临渊羡，拟向沧浪上钓舟。",""],["客中别子恨难禁，况复萧萧秋满林。\n君去修途宜努力，我于时事每惊心。\n半生身世江湖远，百里桑麻雨露深。\n佐邑想应多暇日，哦松庭院昼沉沉。","客中别子恨难禁，况复萧萧秋满林。\n君去脩途宜努力，我于时事每惊心。\n半生身世江湖远，百里桑麻雨露深。\n佐邑想应多暇日，哦松庭院昼沉沉。"],["好事重重慰北堂，清朝甲第喜传芳。\n曲江宴罢袍新绿，太守符分带已黄。\n汉室勋名看并美，韦门庆泽羡逾长。\n桂枝元是君家物，借问今年第几郎。",""],["屋外山光碧四围，几株松桂傍山扉。\n何妨移竹供潇洒，自爱开樽对翠微。\n啼鸟声中惊节换，寒梅枝上报春归。\n独怜远客风尘里，回首年年忆钓矶。",""],["小小亭台短短墙，茅斋静处著绳床。\n排檐寒色几竿竹，隔座轻烟一瓣香。\n明镜未容悲岁晚，青山也解笑人忙。\n年来饱饭便便睡，梦里身如在故乡。",""],["霜风凄惨岁华深，木落空庭噪暮禽。\n犹有翠筠堪志节，岂无碧水可澄心。\n浮生迹似漂流梗，造士功惭跃冶金。\n草阁卷帘时自遣，孤吟遥对白云岑。","霜风悽惨岁华深，木落空庭噪暮禽。\n犹有翠筠堪志节，岂无碧水可澄心。\n浮生迹似漂流梗，造士功惭跃冶金。\n草阁捲帘时自遣，孤吟遥对白云岑。"],["一经幸际圣明时，宦辙东西任所之。\n潇散迹还兼吏隐，痴顽心祗似童儿。\n借来法帖临池习，乞得名花带雨移。\n地僻每迂高士驾，才疏敢和古人诗。",""],["握虎分符出拥驺，共言官是古诸侯。\n印闲不比分司日，山近偏逢露冕秋。\n田里几时歌乐业，庙堂此日得分忧。\n别来不惜双鱼寄，应有潮来到石头。","握虎分符出拥驺，共言官是古诸侯。\n印閒不比分司日，山近偏逢露冕秋。\n田里几时歌乐业，庙堂此日得分忧。\n别来不惜双鱼寄，应有潮来到石头。"],["檐鹊朝来送喜忙，俄闻新命下鳣堂。\n共夸腾踏能千里，独惜翻飞各一方。\n越地重儒知俗美，周官垂训要刑祥。\n俸钱纵倍贤关日，须信齑盐滋味长。","檐鹊朝来送喜忙，俄闻新命下鳣堂。\n共誇腾踏能千里，独惜翻飞各一方。\n越地重儒知俗美，周官垂训要刑祥。\n俸钱纵倍贤关日，须信齑盐滋味长。"],["方城汉水今犹昔，旧事销磨一梦间。\n遗爱尚称羊叔子，清风犹说鹿门山。\n民穷赖汝勤安辑，俗薄凭谁力挽还。\n竹马欢迎何足羡，要看去日众号攀。",""],["漏转彤楼唱晓鸡，千官鹄立殿东西。\n香飘辇路佩声合，日映宫云扇影齐。\n已觉冰消流水细，即看花重亚枝低。\n天家可是春偏早，禁柳宫槐莺乱啼。",""],["霜雁南飞日又斜，官船催发鼓频挝。\n三年几作还乡梦，八月真看泛斗槎。\n幽似覆盆仍望照，春回枯井也生芽。\n简书可畏归须早，肯为江南滞使华。",""],["迢迢蜀道阻潘舆，使者频归问起居。\n筵出上尊黄票酒，函开御墨紫泥书。\n也知彩服心长恋，其奈岩廊席久虚。\n书报北堂应一笑，圣恩新遣佩金鱼。","迢迢蜀道阻潘舆，使者频归问起居。\n筵出上尊黄票酒，函开御墨紫泥书。\n也知綵服心长恋，其奈岩廊席久虚。\n书报北堂应一笑，圣恩新遣佩金鱼。"],["清名俭德重当时，道路人传即口碑。\n全陜山川遗爱在，留官管钥旧臣宜。\n门无杂客迹如扫，案有残书手自披。\n几疏乞骸恩未许，朴忠应结九重知。",""],["拥炉独坐有馀情，箭漏声传忽二更。\n一树寒花铃阁静，半庭残雪纸窗明。\n赏心自爱年芳近，回首翻怜世网撄。\n牢落异乡归未得，只凭春酒破愁城。",""],["谁将短笛怨中吹，肠断孤鸿对落晖。\n宾馆正逢尘榻下，秋江又报客帆归。\n天涯同榜几人在，江左前朝旧事稀。\n却忆太平门外路，隔湖烟树雨霏微。",""],["弟昆托契十年中，人事浮云逐眼空。\n君已分符岭以外，我仍簪笔殿之东。\n才能济美古犹少，志在酬恩远亦同。\n须识别离无限思，江流目断是南鸿。",""],["流落炎州未足嗟，乾坤随寓即为家。\n昔贤此是投荒地，异事今传入梦槎。\n高节峥嶒昭日月，浮荣聚散等云霞。\n爱君不得从君去，目断南天岭树斜。",""],["三日斋坛致礼同，俄看飞絮已漫空。\n诚孚未觉天心远，瑞应元知世运隆。\n香爇龙涎酬景贶，占凭鸡骨报年丰。\n多情欲和阳春句，冻笔呵成愧未工。",""],["江海重承召命新，彤庭虎拜觐龙鳞。\n君恩似借微臣宠，仙果先颁内府珍。\n翠篚擎来金弹满，冰盘捧出绛珠匀。\n荐馀正席尝偏好，未有涓埃答帝仁。",""],["碧藕堆盘玉不如，穷冬风物更怜渠。\n颁从御府荣方重，嚼罢文园渴已除。\n恩比连丝知未断，心能容物爱中虚。\n毫分无补真叨食，惭愧黄封走使车。",""],["礼成荐鲔圣心欢，恩许尝新遍从官。\n一饱敢忘明主德，百年深愧腐儒餐。\n銮刀细切怜霜脍，官酝旋开侑玉盘。\n食罢感恩思补报，冯驩长铗未须弹。",""],["别久重逢问濯缨，尊前相对夜灯明。\n异乡骨肉堪流涕，故国交游半死生。\n富贵谁无桑梓念，江湖久负鹭鸥盟。\n何时粗了乾坤债，归去青山学耦耕。",""],["江湖为客久沉沉，几度书来慰我心。\n白璧空教双足刖，红尘已觉二毛侵。\n钟仪居晋还南操，庄舄思乡祗越吟。\n三尺渔矶便堪老，此中费得几多金。",""],["才颇如人命不如，江湖落魄几年馀。\n一官老始分鳣席，千里妻能挽鹿车。\n心泰也知由乐道，眼昏可得便抛书。\n但求苜蓿盘中满，弹铗无劳叹食鱼。",""],["蓬莱殿阁隔尘嚣，云卷珠帘讲幄高。\n扇影开时瞻御座，炉烟飞处簇宫袍。\n横经未觉天颜远，问道应忘玉体劳。\n身际明时叨侍从，犹惭无术补秋毫。","蓬莱殿阁隔尘嚣，云捲珠帘讲幄高。\n扇影开时瞻御座，炉烟飞处簇宫袍。\n横经未觉天颜远，问道应忘玉体劳。\n身际明时叨侍从，犹惭无术补秋毫。"],["迩英持橐总儒绅，香案前头立讲臣。\n颇怪地偏饶雨露，不知身已近星辰。\n彤墀仗簇皇威肃，玉几书呈御览新。\n讲罢自天传赐宴，九重喜色溢龙鳞。",""],["百官朝退翠华来，日映红云讲殿开。\n驸马带刀还夹陛，将军列戟尽衔枚。\n论思地禁荣重入，简拔恩深愧不才。\n宴罢仍从东观集，直疑步武接三台。",""],["向来道路避乘骢，今拜外台秩更崇。\n身远螭头封事简，冠仍豸角触邪同。\n开尊暮对潇湘雨，弭节秋生鄂渚风。\n极目江天迷楚望，夜来空仰法星红。",""],["叹息曲江同宴后，年年减却会中人。\n别来见面翻疑梦，老去交情转觉亲。\n镜里勋名嗟未晚，花前酒盏劝须频。\n逢君祗合腾腾醉，明日相望参与辰。",""],["时来千里慰衰迟，洗眼灯前手自披。\n遗爱曾闻随处有，古音休叹少人知。\n明时失士良为耻，壮岁还山恐未宜。\n正是圣君求治日，沧江谁许钓纶垂。",""],["故乡归作雪中游，万里凝华漾素秋。\n色借旌幢兵气合，光连营垒阵云收。\n成功岂必调商鼎，料敌何如下蔡州。\n旧日草堂无恙否，门前时见拥鸣驺。",""],["君在江南正忆渠，我来君复动征车。\n如何鸿燕时难并，可是参商迹便疏。\n闭户只穷羲氏学，忧时曾上贾生书。\n兹行绩奏天颜悦，应得承恩佩紫鱼。",""],["两为三辅号□平，千里耕桑蔼颂声。\n汉史无劳夸长倩，韦门又喜得玄成。\n江空山色依帆转，阙晓钟声杂佩鸣。\n朝谒承明轮奏对，可应无语及苍生。","两为三辅号□平，千里耕桑蔼颂声。\n汉史无劳誇长倩，韦门又喜得玄成。\n江空山色依帆转，阙晓钟声杂佩鸣。\n朝谒承明轮奏对，可应无语及苍生。"],["孤舟夜雨一灯青，卧听城乌泪暗零。\n千里子心怜寸草，百年人世叹浮萍。\n情深未挂当年剑，才劣犹惭太史铭。\n身在异乡亲浅土，莫辞归路载残星。",""],["征贤诏下促骊歌，江上风烟别思多。\n群从几人登正路，九霄何地答恩波。\n筹边即见销金甲，待漏重看振玉珂。\n若向江湖怀旧侣，缄题时托雁南过。","徵贤诏下促骊歌，江上风烟别思多。\n群从几人登正路，九霄何地答恩波。\n筹边即见销金甲，待漏重看振玉珂。\n若向江湖怀旧侣，缄题时托雁南过。"],["多病长思卧翠微，重来江阁坐朝晖。\n未能报国心徒恋，且喜看山愿不违。\n对酒忽闻啼鸟过，赏春空惜落花飞。\n分明此地真蓬岛，吟倚阑干晚未归。",""],["落落才名迥出群，紫髯又见作参军。\n书生莫道不知武，记室从来要有文。\n别路共伤千里月，怀人知隔数重云。\n三湘春近多来雁，却要音书别后闻。",""],["炎炎畏景昼偏长，竹簟藤床觅上方。\n出户便惊尘土满，脱巾且趁水风凉。\n径松滴翠凝冰砚，砌竹分阴上粉墙。\n头白老僧无一事，惟将双眼看人忙。",""],["空庭谁种万琅玕，赢得斋时对榻看。\n座起午烟应瀹茗，帘垂暮雨漫焚檀。\n燔柴何幸逢周典，簪笔也曾忝汉官。\n今日甘泉谁扈从，梦回星月近瑶坛。",""],["焚香扫地拥氍毹，却饮辞荤称病躯。\n卧向青山三日后，消来杂念半分无。\n风应扫雾开千嶂，雨为清尘遍九衢。\n郊罢愿颁宽大诏，坐教海宇尽欢娱。",""],["历尽山川力未休，一官今去赞刀州。\n清名何必羡留琐，利器还应见解牛。\n客路秋初飞一叶，官河日晚泊千艘。\n寄书莫道无来雁，人在蓬瀛正倚楼。",""],["士行公才俱绝俦，乌台新拜宠恩优。\n朝廷正合留长孺，乡里应多识太丘。\n雪意远含宫树暝，江声寒送石城秋。\n南朝古寺题诗处，何日从君觅旧游。",""],["隐居谷口漫逃名，时有高人扣竹扃。\n枕簟昼长迷蝶梦，江湖天阔羡鸿冥。\n囊收珠玉几千首，家住蓬壶近百龄。\n他日一杯何处祝，夜深频望老人星。",""],["又觉金天爽气新，古今不驻是羲轮。\n月明万户悬砧杵，日落扁舟罢钓纶。\n遥忆故人多梦寐，独怜晚岁尚风尘。\n几时投老青山下，共汲清泉煮涧莼。",""],["病客逢秋忆故园，汝来应得赖温存。\n江湖岁晚身千里，骨肉情多酒一尊。\n别后关河长问信，愁来风雨更思君。\n西窗灯火寒无梦，旧事中宵得细论。",""],["此君标格最堪怜，几度相看思悄然。\n密叶风含声细细，高梢露裛色娟娟。\n影分枕簟疑无暑，润映琴书合并妍。\n我欲结君为密友，相将同到岁寒天。",""],["空江木落奈愁何，卧听霜鸿带月过。\n老去身浮青雀舫，秋来梦入白鸥波。\n青牛早解庄生语，衰凤真惭楚客歌。\n早晚归寻樵牧侣，深山结屋傍云萝。",""],["十年不作清都梦，直道受知自圣君。\n恩重江湖来召命，秋深鸿雁惜离群。\n公卿不贵深持法，竹帛还期早策勋。\n预报商霖今有兆，为公指点出山云。",""],["平生用世守遗经，老去真为国典刑。\n班马文章高汉代，夷夔礼乐重虞廷。\n身轻似得长生术，名就犹当未暮龄。\n人物斗南称第一，他年汗简有馀青。",""],["岭表衣冠几百年，曲江公后更谁贤。\n早能见道陈编外，晚却游心太古前。\n马帐谈经罗俊彦，凤池挥翰待儒仙。\n须知辅养吾君德，却要伊川在讲筵。",""],["一门圭组羡多贤，仝榜金绯独妙年。\n归省正逢家庆日，别离须记岁寒天。\n南都人物阳秋里，两浙山川节制前。\n到处疮痍应可念，城西休问泛湖船。",""],["太湖风兮白波，瞻望洞庭兮森云萝。\n撷杜蘅兮水中，吊范蠡兮山阿。\n目盈盈兮不极，美人远兮柰何。\n渺予怀兮夕阳，听不可兮吴歌。",""],["夫唯山之效美兮，纷众万之淑祥。\n有振振之令鸟兮，绚采采之文章。\n涓高梧以营室兮，口卒瘏而周皇。\n殷九苞之未诞兮，轩远翥而求凰。\n陆海邈其伏阴兮，屏尔类以自臧。\n大网结于中野兮，二苞格而鸣冈。\n徙阿阁于戾止兮，披晨曦之耿光。\n嘅禄运之倏穷兮，翳冲漠而遥翔。\n奇气宕于六天兮，毛衣委于故邦。\n群鸱倨以自迈，众息下其如僵。\n苟灵光之弗泯，虽捐性其奚伤。\n谇曰：予悲夫云和之曲卒不续兮，顾此鸟之永遗。\n岂四灵之不有兮，世盖溷之以蝘蜓与螽斯。",""],["朝发汾河，暮经白沟。\n茫然战场，四时为秋。\n黄云阨关，壮士不忧。\n拔剑斫地，战骨无收。\n风沙冥冥，髑髅啸歌。\n鸟飞不下，客行奈何。\n世无凰麟，龙虎斗争。\n谁哉弄丸，四海解兵。",""],["菖歜葱葱，在彼涧滨。\n岁茁九花，世人不纫。\n秘之颍谷，以俟云君。\n念彼菉葹，苍苍广津。\n菖歜青青，在彼原隰。\n岁茹九节，可以绝粒。\n华滋寂寥，尔乃独立。\n世无神皇，凤衰麟泣。",""],["翼翼黄雀，集彼榛柯。\n上有鸷鸟，下有虞罗。\n低飞不可，高飞奈何。\n曷不去此，野田有禾。\n鹏雏摇摇，隼则制之。\n兔罝纤纤，鸿则罹之。\n龙潜在渊，可以全身。\n壤蠖不屈，何以引伸。\n朱凤威垂，稠羽是依。\n鸱枭化之，矰弋安施。",""],["梁之山兮，岳岳其砥。\n石之磐磐，兴云及雨。\n肤合之施，其谁弗被。\n立天之中，君子不匮。\n天常西亏，地亦东溃。\n我不尔奠，曷其有位。\n大皇时行，大浸时滋。\n怀贞用敦，君予以几。",""],["井之京京，其出渊渊。\n汔至不繘，谓我叵泉。\n甃如幕如，我梦乘如。\n寤怀载且，维以永戏。\n井之渊渊，爰是用汲。\n王明王明，受此戬福。\n渫而不食，于井何伤。\n君子之履，不迁其方。",""],["湔湔流泉，行彼地中。\n灿为星宿，丽尔云空。\n万殊之母，直遂涵弘。\n贲以正本，蒙以养功。\n君子果行，丕显其逢。\n湔湔流泉，㶁㶁滥觞。\n积为江汉，博大以刚。\n彼王者明，受福无疆。\n神龙所都，厥澍载滂。\n君子利用，何往弗臧。",""],["采铜铸宝鼎，炼作九还丹。\n服食寿长生，长生千万年。\n白日跨飞龙，宸游上九天。\n如何鼎湖路，一去无时还。\n君子贵返终，仙术谅非难。\n方士费论说，彼心讵能安。\n秦皇与汉武，黄土高巑岏。",""],["陵坡回燠风，楸枰净如沐。\n戒言寻浩渺，聊以散沈郁。\n况兹二月半，芳草萋以绿。\n青霞媚遥天，乌巾入殊俗。\n嵚崎麦斜岩，幽人有高足。\n怀贤招艾轩，探真小樵谷。\n世缘夙已断，碧岭不可辱。\n君看南昌尉，去去从所欲。",""],["麦斜何崭崭，兹游惬心魂。\n石洞入窈窕，不说桃花源。\n白云走平地，崇冈亦崩奔。\n松篁翳重阴，境幽判寒暄。\n天关手可摩，始觉所历尊。\n赤城去不远，玉禾行当蕃。\n相期马子微，于此采灵根。",""],["贪清不自爱，历历疏远目。\n缅怀云居胜，驾言陟层曲。\n樛枓遁斧斤，岐径积朴樕。\n云栈纷当心，不敢轻落足。\n扪枯骤战兢，披荆逾匍匐。\n尪羸无奈何，况复迷浚谷。\n虽无夔莘警，讵测蜒蚿伏。\n少焉青霞深，转思白日速。\n山海信伟观，何以慰彳亍。\n我行孰驱迫，自致穷途哭。\n伯阳不出门，世路了如烛。\n愿昭篯子诫，或免华山辱。",""],["搜奇头欲改，禹穴未得傍。\n忽慕麦斜岩，玄境足佳况。\n连峰削芙容，石门天下壮。\n筼筜复修纤，天声落屏嶂。\n云居独奇绝，遐思愈飞飏。\n以兹发高踪，力欲排云上。\n百息径崄艰，一眺极沆漭。\n鹓鸾税仙骖，芝荪洗凡状。\n试按山海图，一一皆不妄。\n虽然羸瘵成，已过平生望。\n应悲蜉居子，兀兀坐盆盎。\n吾将从卢敖，直与云露抗。\n西凌昆仑风，东薄沧海浪。\n前期邈悠悠，拊膺以惆怅。","搜奇头欲改，禹穴未得傍。\n忽慕麦斜岩，玄境足佳况。\n连峰削芙容，石门天下壮。\n筼筜复修纤，天声落屏嶂。\n云居独奇绝，遐思愈飞飏。\n以兹发高踪，力欲排云上。\n百息径崄艰，一眺极沆漭。\n鹓鸾税仙骖，芝荪洗凡状。\n试按山海图，一一皆不妄。\n虽然羸瘵成，已过平生望。\n应悲蜉居子，兀兀坐盆盎。\n吾将从卢敖，直与云露抗。\n西凌昆崙风，东薄沧海浪。\n前期邈悠悠，拊膺以惆怅。"],["云居不可升，塞型眇天上。\n讽然下何岭，歘若坠青嶂。\n数日愁险艰，及此爱平旷。\n林墟相维亘，川原亦排荡。\n春容丽华滋，百草不相放。\n踌躇谷鸟喧，坐失青藜杖。\n山中胜事繁，林叟重揖让。\n岂无山水癖，筋力故莫彊。\n栗里在人境，君子有末尚。",""],["南行遵溪浒，流景何楚楚。\n溪毛绣藻蘩，游鱼聚相喣。\n锦石亦参错，绿发明可数。\n小者如卧羊，大者如伏虎。\n飞湍所磨荡，兀兀自太古。\n丛薄交深春，不但蔚榛楛。\n兹游倦登陟，到此一延伫。\n况有令主人，意气不为忤。\n担囊轻百里，一一适我所。\n春花未终极，岂即怀故土。\n锦江非不佳，人情薄如楮。\n西游杜陵老，安得免愁苦。",""],["晴光荡游目，一雨山逾碧。\n翛然戒晨征，乃尔骋双屐。\n修林静宿氛，故术没行迹。\n仆夫重远路，贱子有奇癖。\n南循抵仙城，北放兰阪陌。\n波岭行有需，朋曹意安极。\n我生无漫游，允得就三益。",""],["蓬门霜雪繁，玉颜苦禁当。\n稍识春风面，春风转断肠。",""],["蚕盛不理妆，露采陌上桑。\n但知织作?，不觉年貌伤。",""],["宝镜皎如月，价值千黄金。\n偏照可怜色，不照可怜心。",""],["客有罗浮君，羽衣行翩翩。\n长揖谢世事，炼性三十春。\n沆瀣不满口，貌如藐姑神。\n问道广成子，空同高嶙峋。\n挂瓢椅树枝，振舄天风门。\n朅来吊延陵，晤言东海滨。\n示我紫尸术，挺身入层云。\n誓将结瑶华，引手长相亲。","客有罗浮君，羽衣行翩翩。\n长揖谢世事，鍊性三十春。\n沆瀣不满口，貌如藐姑神。\n问道广成子，空同高嶙峋。\n挂瓢椅树枝，振舄天风门。\n朅来吊延陵，晤言东海滨。\n示我紫尸术，挺身入层云。\n誓将结瑶华，引手长相亲。"],["郎今落海滨，侬亦可怜身。\n不见昌阳草，何曾生要津。\n侬身不下堂，郎居隔江水。\n虽则隔江水，思心日万里。\n昔别于何时，十载参与商。\n岂是无所见，狼嘴夜夜张。\n夜夜抚素琴，恻恻生怨慕。\n枯桐在膝上，梧子在何处。\n融融四五月，婉婉采莲女。\n海上无芙渠，谁则识莲子。\n低头摘荷叶，举头看月光。\n归来觅剪刀，为欢制衣裳。\n终日对海棠，终夜不成寐。\n何以不成寐，花开侬独自。\n登楼看双星，蜘蛛在楼角。\n绵绵腹中丝，求匹不能得。\n欢去一何久，欢来一何晏。\n来时何所赠，双双云锦段。",""],["出自吴东门，遥望姑胥台。\n望久无所见，回风惨蒿莱。\n图王志未就，神木生劫灰。\n三复春秋传，英雄使人哀。",""],["越女进馆娃，楚囚落天涯。\n二物不并立，海水漂鸱夷。\n湛卢南入郢，神物竟先知。\n吴宫八百年，旦夕游鹿麋。\n缅晤丧亡主，岂尽庸以?。",""],["震泽夫何如，岁晏意自好。\n天风吹玄冥，雪浪入浩溔。\n鼋鼍浮山岳，白日摇晴昊。\n洞庭渺林屋，流水隔烦恼。\n昔有绿毛翁，于此采玄草。\n风云白石床，鬼物为持保。\n闻兹长道念，携舻事幽讨。\n平生竹溪逸，矧是同怀抱。\n相从扪绿云，坐听启鸿宝。\n终当吸沆瀣，去去游亭纛。",""],["觏子在逆旅，失子在岁晏。\n一似南飞鸿，一似西归燕。\n繁露戾修林，终风捷如箭。\n过翼趋所期，殊方卒相见。\n物情异冷煖，人事阻华面。\n迟余玉门春，子复穴梁殿。",""],["东君御征辕，玄冥迅回车。\n温风倏尔至，古梅茁其葩。\n桃户新受符，蓼盘香团芽。\n感此念故里，兼之怀年华。\n炙蛎洽弟兄，问岁话桑麻。\n二期走逋旅，簪绂生叹嗟。\n坐兹失初服，五内长负疴。\n兔窟有穴狐，凰木亦栖鸦。\n悟机贵在蚤，勿令负云霞。","东君御征辕，玄冥迅回车。\n温风倏尔至，古梅茁其葩。\n桃户新受符，蓼盘香团芽。\n感此念故里，兼之怀年华。\n炙蛎洽弟兄，问岁话桑麻。\n二期走逋旅，簪绂生叹嗟。\n坐兹失初服，五内长负痾。\n兔窟有穴狐，凰木亦栖鸦。\n悟机贵在蚤，勿令负云霞。"]]});
